/* FRAME/12 Design System — Tokens, Panel Grammar, Screentone, and Motion on Twos.
   Works standalone without Tailwind. All rules are scoped to .f12-* classes. */

/* @tokens:start */
/* Generated by @frame12/tokens — generated, do not edit by hand. */
/* Cross-platform metric-matched fallbacks for Dela Gothic One, Zen Kaku Gothic New, and
   M PLUS 1 Code across macOS, Windows, Linux (Liberation/DejaVu/Noto), and Android (Roboto)
   so cold-network .woff2 swaps do not reflow headings, controls, paragraphs, or tables. */
@font-face {
  font-family: "f12DisplayFallback";
  src: local("Arial"), local("Helvetica Neue"), local("Helvetica"), local("Liberation Sans"), local("Arimo"), local("Nimbus Sans"), local("Nimbus Sans L"), local("Roboto"), local("Noto Sans"), local("FreeSans");
  font-weight: 400;
  size-adjust: 131.74%;
  ascent-override: 88.05%;
  descent-override: 21.86%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "f12DisplayFallbackDejaVu";
  src: local("DejaVu Sans"), local("Bitstream Vera Sans"), local("Verdana");
  font-weight: 400;
  size-adjust: 120.3%;
  ascent-override: 96.4%;
  descent-override: 23.9%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "f12BodyFallback";
  src: local("Arial"), local("Helvetica Neue"), local("Helvetica"), local("Liberation Sans"), local("Arimo"), local("Nimbus Sans"), local("Nimbus Sans L"), local("Roboto"), local("Noto Sans"), local("FreeSans");
  font-weight: 400;
  size-adjust: 99.1%;
  ascent-override: 117.05%;
  descent-override: 29.06%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "f12BodyFallbackDejaVu";
  src: local("DejaVu Sans"), local("Bitstream Vera Sans"), local("Verdana");
  font-weight: 400;
  size-adjust: 90.5%;
  ascent-override: 128.17%;
  descent-override: 31.82%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "f12MonoFallbackConsolas";
  src: local("Consolas");
  font-weight: 400;
  size-adjust: 90.91%;
  ascent-override: 110%;
  descent-override: 25.85%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "f12MonoFallback";
  src: local("Menlo"), local("DejaVu Sans Mono"), local("Courier New"), local("Liberation Mono"), local("Cousine"), local("Noto Sans Mono"), local("Droid Sans Mono");
  font-weight: 400;
  size-adjust: 83.19%;
  ascent-override: 120.21%;
  descent-override: 28.25%;
  line-gap-override: 0%;
}

:where(:root) {
  --font-f-display: var(--font-dela-gothic-one, "Dela Gothic One"), "f12DisplayFallback", "f12DisplayFallbackDejaVu", "Arial Black", "Helvetica Neue", sans-serif;
  --font-f-body: var(--font-zen-kaku-gothic-new, "Zen Kaku Gothic New"), "f12BodyFallback", "f12BodyFallbackDejaVu", "Hiragino Sans", "Helvetica Neue", "Arial", sans-serif;
  --font-f-mono: var(--font-m-plus-1-code, "M PLUS 1 Code"), "f12MonoFallbackConsolas", "f12MonoFallback", ui-monospace, "SF Mono", "Menlo", monospace;

  --f-gutter-pair: 12px;
  --f-gutter-scene: 20px;
  --f-gutter-change: 32px;

  --f-stroke: 2.5px;
  --f-stroke-pencil: 1px;
  --f-stroke-detail: 1.5px;
  --f-pose: 83.33ms;
  --f-fps: 12;

  --f-shadow-sheet: 0 1px 0 rgba(0, 0, 0, 0.05), 0 18px 40px -26px rgba(0, 0, 0, 0.5);
  --f-shadow-peg: inset 0 1px 2px rgba(0, 0, 0, 0.25);
  --f-backdrop: rgba(12, 12, 12, 0.78);
  --f-diff: #ffffff;
}

:where(:root),
:root[data-theme="light"],
.f12-theme-light {
  --f-desk: #e2e3e5;
  --f-sheet: #ffffff;
  --f-panel: #ffffff;
  --f-ink: #121212;
  --f-ink-2: #4b4b4b;
  --f-rule: #121212;
  --f-tone: #121212;
  --f-grid: #e3e3e3;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #e2e3e5;
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]):not(.f12-theme-light) {
    --f-desk: #000000;
    --f-sheet: #050505;
    --f-panel: #19191a;
    --f-ink: #f1f0ea;
    --f-ink-2: #b9b8b1;
    --f-rule: #f1f0ea;
    --f-tone: #f1f0ea;
    --f-grid: #2c2c2d;
    --f-marker: #ffd60a;
    --f-marker-ink: #121212;
    --f-hole: #000000;
    color-scheme: dark;
  }
}

:root[data-theme="dark"],
.f12-theme-dark {
  --f-desk: #000000;
  --f-sheet: #050505;
  --f-panel: #19191a;
  --f-ink: #f1f0ea;
  --f-ink-2: #b9b8b1;
  --f-rule: #f1f0ea;
  --f-tone: #f1f0ea;
  --f-grid: #2c2c2d;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #000000;
  color-scheme: dark;
}
/* @tokens:end */

/* ===================================================================== Scoped Base & Reset */
.f12-dash,
.f12-sheet,
.f12-scene,
.f12-panel,
.f12-pair,
.f12-rng,
.f12-metric,
.f12-chart,
.f12-ints,
.f12-btn,
.f12-field,
.f12-input,
.f12-textarea,
.f12-check-field,
.f12-checkbox-control,
.f12-checkbox-input,
.f12-radio-group,
.f12-radio-item,
.f12-radio-control,
.f12-radio-input,
.f12-switch,
.f12-switch-input,
.f12-switch-track,
.f12-switch-thumb,
.f12-tabs,
.f12-tabs-list,
.f12-tabs-trigger,
.f12-tabs-content,
.f12-dialog,
.f12-select,
.f12-select-content,
.f12-tooltip-wrap,
.f12-menu-wrap,
.f12-menu,
.f12-table-wrap,
.f12-balloon,
.f12-balloon-standalone,
.f12-tag,
.f12-badge,
.f12-ghost-wire,
.f12-receipt,
.f12-receipt-list {
  box-sizing: border-box;
}

.f12-dash *,
.f12-dash *::before,
.f12-dash *::after,
.f12-sheet *,
.f12-sheet *::before,
.f12-sheet *::after,
.f12-panel *,
.f12-panel *::before,
.f12-panel *::after,
.f12-field *,
.f12-check-field *,
.f12-radio-group *,
.f12-tabs *,
.f12-dialog *,
.f12-select *,
.f12-select-content *,
.f12-menu *,
.f12-table-wrap *,
.f12-ghost-wire *,
.f12-receipt *,
.f12-receipt-list * {
  box-sizing: border-box;
}

.f12-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
  user-select: none;
  -webkit-user-select: none;
}

:where(.f12-frame button, .f12-sheet button, .f12-dialog button, button[class*="f12-"]) {
  font: inherit;
  color: inherit;
}

.f12-frame :focus-visible,
.f12-sheet :focus-visible,
.f12-dialog :focus-visible,
[class*="f12-"]:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}

/* ===================================================================== Sheet & Pegs */
.f12-dash {
  container-type: inline-size;
  position: relative;
}
.f12-dash :where(h2, h3, p, ul) {
  margin: 0;
}
.f12-dash :where(ul) {
  list-style: none;
  padding: 0;
}

.f12-frame {
  background: var(--f-desk);
  color: var(--f-ink);
  font-family: var(--font-f-body);
  padding: 20px;
  border-radius: 4px;
}

.f12-sheet {
  position: relative;
  background: var(--f-sheet);
  color: var(--f-ink);
  font-family: var(--font-f-body);
  padding: 44px 28px 28px;
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-change); /* 32px = scene change */
  box-shadow: var(--f-shadow-sheet);
  counter-reset: f12-cut;
}

.f12-pegs {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 26px;
  align-items: center;
}
.f12-peg {
  display: block;
  background: var(--f-hole);
  border: 1px solid var(--f-grid);
  box-shadow: var(--f-shadow-peg);
}
.f12-peg.round {
  width: 11px;
  height: 11px;
  border-radius: 50%;
}
.f12-peg.slot {
  width: 26px;
  height: 8px;
  border-radius: 4px;
}

.f12-hd {
  display: flex;
  flex-wrap: wrap;
  gap: 16px 24px;
  align-items: flex-end;
  justify-content: space-between;
}
/* Let the text column shrink below its longest unbreakable token so long titles/IDs wrap (or,
   failing that, overflow inside the sheet) instead of widening the page on narrow screens. */
.f12-hd > .f12-hd-text {
  min-width: 0;
}
.f12-eyebrow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
/* Eyebrow chips (file paths, IDs) may be one unbreakable token: let them shrink and break
   rather than push a narrow sheet wider than the viewport. */
.f12-eyebrow > :is(.f12-tag, .f12-badge) {
  min-width: 0;
  overflow-wrap: anywhere;
}
.f12-title {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: clamp(30px, 5.2cqi, 46px);
  line-height: 1.02;
  margin-top: 10px;
  letter-spacing: 0.005em;
  text-wrap: balance;
}
/* Programmatic focus target only (e.g. after a breadcrumb steps up a level); not operable, so
   no ring — the heading itself is the visible landmark. */
.f12-title[tabindex='-1']:focus {
  outline: none;
}
.f12-sub {
  font-family: var(--font-f-mono);
  font-size: 12px;
  color: var(--f-ink-2);
  margin-top: 8px;
  letter-spacing: 0.04em;
}

/* ===================================================================== Scene & Gutter Grammar
   12px = pair, 20px = same scene, 32px = scene change */
.f12-scene {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
  gap: var(--f-gutter-scene);
  min-width: 0;
}
.f12-scene.f12-scene-split {
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
}
.f12-scene.f12-scene-stack {
  grid-template-columns: minmax(0, 1fr);
}
.f12-scene.f12-scene-equal {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.f12-scene.f12-scene-three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.f12-scene.f12-scene-areas {
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: none;
}
.f12-scene.f12-scene-areas > [data-area],
.f12-scene-area {
  min-width: 0;
  grid-area: auto;
}
.f12-scene-area {
  display: flex;
  flex-direction: column;
}
.f12-scene-area > .f12-panel {
  flex: 1;
}
@media (min-width: 860px) {
  .f12-scene.f12-scene-areas:not([data-scene-bp]) {
    grid-template-columns: repeat(var(--f12-scene-cols, 12), minmax(0, 1fr));
    grid-template-areas: var(--f12-scene-areas);
  }
  .f12-scene.f12-scene-areas:not([data-scene-bp]) > [data-area] {
    grid-area: var(--f12-area);
  }
}
.f12-scene.f12-scene-pair {
  gap: var(--f-gutter-pair);
}
.f12-scene.f12-scene-scene {
  gap: var(--f-gutter-scene);
}
.f12-scene.f12-scene-change {
  gap: var(--f-gutter-change);
}

.f12-pair {
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-pair);
  min-width: 0;
}
.f12-pair > .f12-panel {
  flex: 1;
}

/* ===================================================================== Panel */
.f12-panel {
  position: relative;
  min-width: 0;
  display: flex;
  flex-direction: column;
  color: var(--f-ink);
  font-family: var(--font-f-body);
}
.f12-panel-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}
.f12-panel-frame polygon {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: var(--f-stroke);
  stroke-linejoin: miter;
}
.f12-panel-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  position: relative;
  padding: 24px 22px 22px;
}
.f12-panel.f12-slant-bottom > .f12-panel-body {
  padding-bottom: 36px;
}
.f12-panel.f12-slant-top > .f12-panel-body {
  padding-top: 36px;
}
.f12-cut {
  position: absolute;
  top: -8px;
  left: 16px;
  z-index: 1;
  padding: 0 6px;
  line-height: 16px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.12em;
  background: var(--f-sheet);
  color: var(--f-ink);
}
/* <Sheet autoCut> also sets --f12-autocut-display inline; this attribute rule keeps cut labels
   numbered where a strict CSP blocks inline style attributes (static pages in webviews). */
.f12-sheet[data-autocut] {
  --f12-autocut-display: block;
}
.f12-cut[data-autocut] {
  display: var(--f12-autocut-display, none);
  counter-increment: f12-cut;
}
.f12-cut[data-autocut]::before {
  content: "C-" counter(f12-cut, decimal-leading-zero);
}
.f12-panel.f12-slant-top > .f12-cut {
  top: 8px;
}
.f12-panel.f12-panel-quiet {
  background: var(--f-panel);
  border: 1px solid var(--f-rule);
}
.f12-panel.f12-panel-quiet:not(.f12-rect) {
  background: none;
  border: 0;
}
.f12-panel.f12-panel-quiet > .f12-panel-frame > polygon {
  stroke-width: 1;
}
.f12-panel.f12-panel-quiet > .f12-panel-body {
  padding: 16px 18px;
}
.f12-panel.f12-panel-quiet.f12-slant-bottom > .f12-panel-body {
  padding-bottom: 32px;
}
.f12-panel.f12-panel-quiet.f12-slant-top > .f12-panel-body {
  padding-top: 32px;
}

/* ===================================================================== Tag & Badge */
.f12-tag {
  position: relative;
  display: inline-block;
  vertical-align: middle;
  max-width: 100%;
  overflow-wrap: break-word;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-marker-ink);
  background: var(--f-marker);
  padding: 1px 6px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.f12-tag-stamp {
  font-family: var(--font-f-display);
  font-size: 11px;
  font-weight: 400;
  line-height: 1.25;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 2px 8px;
  border: 2px solid var(--f-rule);
  background: var(--f-panel);
  color: var(--f-ink);
  transform: rotate(-3deg);
  transform-origin: center;
}

.f12-badge {
  position: relative;
  display: inline-block;
  vertical-align: middle;
  max-width: 100%;
  overflow-wrap: break-word;
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 2px 7px;
  background: var(--f-marker);
  color: var(--f-marker-ink);
  border: 2px solid var(--f-rule);
}
.f12-badge-t {
  position: relative;
  z-index: 1;
}
.f12-tag svg,
.f12-badge-t svg {
  display: inline-block;
  vertical-align: middle;
  margin-inline-end: 4px;
}
.f12-status-glyph {
  margin-inline-end: 4px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
  user-select: none;
  -webkit-user-select: none;
}
.f12-status-neutral {
  background: var(--f-panel);
  color: var(--f-ink);
  border: 1px solid var(--f-rule);
}
.f12-status-info {
  background: var(--f-panel);
  color: var(--f-ink);
  border: 1.5px solid var(--f-rule);
}
.f12-status-success {
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  border-inline-start: 5px solid var(--f-rule);
  font-weight: 700;
}
.f12-status-warning {
  background-color: var(--f-panel);
  background-image: repeating-linear-gradient(
    -45deg,
    transparent 0 5px,
    var(--f-grid) 5px 6.5px
  );
  color: var(--f-ink);
  border: 2px dashed var(--f-rule);
  font-weight: 700;
}
.f12-status-warning .f12-status-glyph {
  color: var(--f-ink);
}
.f12-status-danger {
  background: var(--f-ink);
  color: var(--f-panel);
  border: 2px solid var(--f-rule);
  box-shadow: inset 0 0 0 1.5px var(--f-panel);
  font-weight: 700;
}
.f12-status-danger .f12-status-glyph {
  color: var(--f-panel);
}
.f12-tag-stamp.f12-status-neutral,
.f12-tag-stamp.f12-status-info {
  border-width: 2px;
}
.f12-tag-stamp.f12-status-success,
.f12-tag-stamp.f12-status-warning,
.f12-tag-stamp.f12-status-danger {
  font-weight: 400;
}

/* ===================================================================== GhostWire & Receipt */
.f12-ghost-wire {
  display: grid;
  grid-template-columns: minmax(0, max-content) minmax(24px, 1fr) minmax(0, max-content);
  align-items: center;
  gap: var(--f-gutter-pair);
  min-width: 0;
  max-width: 100%;
  color: var(--f-ink);
  font-family: var(--font-f-mono);
}
.f12-ghost-wire.f12-ghost-wire-vertical,
.f12-ghost-wire[data-orientation="vertical"] {
  grid-template-columns: minmax(0, 1fr);
  justify-items: start;
}
.f12-ghost-wire-endpoint {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  padding: 4px 10px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  line-height: 1.35;
  color: var(--f-ink);
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-ghost-wire-from {
  border: 2px solid var(--f-rule);
  background: var(--f-panel);
  font-weight: 700;
}
.f12-ghost-wire-to {
  border: 2px dashed var(--f-rule);
  background: var(--f-sheet);
  font-weight: 500;
}
.f12-ghost-wire-connector {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 24px;
  width: 100%;
}
.f12-ghost-wire.f12-ghost-wire-vertical .f12-ghost-wire-connector,
.f12-ghost-wire[data-orientation="vertical"] .f12-ghost-wire-connector {
  flex-direction: row;
  justify-content: flex-start;
  min-width: 0;
  width: auto;
  padding-inline-start: 14px;
}
.f12-ghost-wire-svg {
  display: block;
  width: 100%;
  height: 12px;
  overflow: visible;
  flex-shrink: 0;
}
.f12-ghost-wire.f12-ghost-wire-vertical .f12-ghost-wire-svg,
.f12-ghost-wire[data-orientation="vertical"] .f12-ghost-wire-svg {
  width: 12px;
  height: 28px;
}
.f12-ghost-wire-line {
  stroke: var(--f-rule);
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
  fill: none;
}
.f12-ghost-wire-reveal {
  stroke: #fff;
  stroke-width: 12;
  fill: none;
}
.f12-ghost-wire-label {
  font-family: var(--font-f-mono);
  font-size: 11px;
  line-height: 1.3;
  color: var(--f-ink-2);
  text-align: center;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-ghost-wire.f12-ghost-wire-vertical .f12-ghost-wire-label,
.f12-ghost-wire[data-orientation="vertical"] .f12-ghost-wire-label {
  text-align: start;
}

.f12-receipt-list {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--f-gutter-pair);
  list-style: none;
  margin: 0;
  padding: 0;
  min-width: 0;
  max-width: 100%;
}
.f12-receipt-item {
  min-width: 0;
  max-width: 100%;
  display: inline-flex;
}
.f12-receipt {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  padding: 3px 8px;
  border: 1.5px solid var(--f-rule);
  background: var(--f-panel);
  color: var(--f-ink);
  font-family: var(--font-f-body);
  font-size: 12px;
  line-height: 1.4;
}
.f12-receipt-origin {
  display: inline-flex;
  align-items: center;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  color: var(--f-ink);
}
.f12-receipt-origin .f12-status-glyph {
  margin-inline-end: 0;
}
.f12-receipt-value {
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  color: var(--f-ink);
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-receipt-code {
  font-family: inherit;
  font-size: inherit;
  font-weight: inherit;
  color: inherit;
  background: none;
  padding: 0;
}
.f12-receipt-link {
  color: var(--f-ink);
  text-decoration: underline;
  text-decoration-thickness: 1.5px;
  text-underline-offset: 2px;
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-receipt-link:hover {
  background: var(--f-marker);
  color: var(--f-marker-ink);
}
.f12-receipt-title {
  font-family: var(--font-f-body);
  font-size: 12px;
  color: var(--f-ink);
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-receipt-date {
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-burst {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 150%;
  height: auto;
  transform: translate(-50%, -50%);
  opacity: 0;
  pointer-events: none;
}
.f12-burst line {
  stroke: var(--f-ink);
  stroke-width: 2;
  stroke-linecap: square;
}

/* ===================================================================== SegmentedControl (RangeTabs) */
.f12-rng {
  position: relative;
  display: inline-flex;
  flex: none;
  isolation: isolate;
  border: var(--f-stroke) solid var(--f-rule);
  background: var(--f-panel);
}
.f12-rng-ind {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  background: var(--f-diff);
  mix-blend-mode: difference;
  pointer-events: none;
}
.f12-rng-btn {
  cursor: pointer;
  background: none;
  border: 0;
  display: grid;
  justify-items: center;
  padding: 6px 16px 5px;
  color: var(--f-ink);
  min-width: 64px;
}
.f12-rng-btn + .f12-rng-btn {
  border-left: 2px solid var(--f-rule);
}
.f12-rng:not(:has(.f12-rng-ind)) .f12-rng-btn[aria-pressed="true"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-rng-n {
  font-family: var(--font-f-display);
  font-size: 18px;
  line-height: 1;
}
.f12-rng-u {
  font-family: var(--font-f-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.f12-rng-btn:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -6px;
}
.f12-rng:not(:has(.f12-rng-ind)) .f12-rng-btn[aria-pressed="true"]:focus-visible {
  outline-color: currentColor;
}

/* ===================================================================== Tempo Control
   Native radios in the segmented appearance (.f12-rng / .f12-rng-btn). No indicator slide:
   the control that sets motion does not itself move. */
.f12-tempo {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
  display: grid;
  gap: 4px;
  justify-items: start;
}
.f12-tempo-legend {
  padding: 0;
  margin-bottom: 4px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink);
}
.f12-tempo .f12-tempo-opt {
  position: relative;
  min-width: 44px;
  min-height: 44px;
  align-content: center;
  padding: 6px 10px 5px;
}
.f12-tempo-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: inherit;
}
.f12-tempo-opt:has(.f12-tempo-input:checked) {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-tempo-opt:has(.f12-tempo-input:focus-visible) {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
  z-index: 1;
}
.f12-tempo:disabled .f12-tempo-opt {
  cursor: not-allowed;
  opacity: 0.55;
}
.f12-tempo-note-reduced {
  display: none;
}
@media (prefers-reduced-motion: reduce) {
  .f12-tempo-note-reduced {
    display: block;
  }
}
.f12-tempo-note {
  margin: 0;
  max-width: 32ch;
  font-family: var(--font-f-mono);
  font-size: 11px;
  line-height: 1.4;
  color: var(--f-ink);
}

/* ===================================================================== Button & Input */
.f12-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  font-family: var(--font-f-mono);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: var(--f-stroke) solid var(--f-rule);
  background: var(--f-panel);
  color: var(--f-ink);
  padding: 8px 16px;
  font-size: 12px;
  line-height: 1.2;
}
.f12-btn-sm {
  padding: 5px 10px;
  font-size: 11px;
}
.f12-btn-md {
  padding: 8px 16px;
  font-size: 12px;
}
.f12-btn-lg {
  padding: 12px 22px;
  font-size: 13px;
}
.f12-btn-primary {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-btn-secondary {
  background: var(--f-panel);
  color: var(--f-ink);
}
.f12-btn-marker {
  background: var(--f-marker);
  color: var(--f-marker-ink);
}
.f12-btn:hover:not(:disabled) {
  box-shadow: 3px 3px 0 var(--f-rule);
}
.f12-btn:active:not(:disabled) {
  box-shadow: none;
}
.f12-btn:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-btn:disabled {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
  background: var(--f-panel);
}

.f12-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-family: var(--font-f-body);
  color: var(--f-ink);
}
.f12-label {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-field-req {
  color: var(--f-ink);
  font-weight: 700;
}
.f12-input {
  width: 100%;
  padding: 9px 12px;
  font-family: var(--font-f-body);
  font-size: 14px;
  line-height: 1.4;
  color: var(--f-ink);
  background: var(--f-panel);
  border: var(--f-stroke) solid var(--f-rule);
  border-radius: 0;
}
.f12-input::placeholder {
  color: var(--f-ink-2);
}
.f12-input:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-input:disabled {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
  background: var(--f-panel);
}
.f12-field.f12-field-compact {
  gap: 4px;
}
.f12-input.f12-input-compact {
  padding: 6px 10px;
  font-size: 13px;
  border-width: 1.5px;
}
.f12-textarea {
  width: 100%;
  min-height: 84px;
  padding: 9px 12px;
  font-family: var(--font-f-body);
  font-size: 14px;
  line-height: 1.45;
  color: var(--f-ink);
  background: var(--f-panel);
  border: var(--f-stroke) solid var(--f-rule);
  border-radius: 0;
  resize: vertical;
}
.f12-textarea::placeholder {
  color: var(--f-ink-2);
}
.f12-textarea:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-textarea:disabled {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
  background: var(--f-panel);
}
.f12-textarea.f12-textarea-compact {
  min-height: 68px;
  padding: 6px 10px;
  font-size: 13px;
  line-height: 1.4;
  border-width: 1.5px;
}
.f12-hint {
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-error {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink);
  margin: 0;
}
.f12-error-flag {
  background: var(--f-marker);
  color: var(--f-marker-ink);
  padding: 0 4px;
  font-weight: 700;
}

/* ===================================================================== Checkbox, RadioGroup, Switch & Tabs */
.f12-check-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-family: var(--font-f-body);
  color: var(--f-ink);
}
.f12-check-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.f12-check-label {
  font-family: var(--font-f-body);
  font-size: 14px;
  line-height: 1.4;
  color: var(--f-ink);
  cursor: pointer;
  user-select: none;
}
.f12-check-field-compact .f12-check-label,
.f12-field-compact .f12-check-label,
.f12-radio-item-compact .f12-check-label {
  font-size: 13px;
}
[data-disabled] .f12-check-label {
  color: var(--f-ink-2);
  cursor: not-allowed;
}
.f12-check-meta {
  padding-inline-start: 34px;
}

.f12-checkbox-control,
.f12-radio-control {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  flex: none;
}
.f12-checkbox-input,
.f12-radio-input {
  -webkit-appearance: none;
  appearance: none;
  margin: 0;
  width: 24px;
  height: 24px;
  background: var(--f-panel);
  border: var(--f-stroke) solid var(--f-rule);
  cursor: pointer;
  display: block;
}
.f12-checkbox-input {
  border-radius: 0;
}
.f12-radio-input {
  border-radius: 50%;
}
.f12-checkbox-input.f12-checkbox-compact,
.f12-radio-input.f12-radio-compact {
  border-width: 1.5px;
}
.f12-checkbox-input:focus-visible,
.f12-radio-input:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-checkbox-input:disabled,
.f12-radio-input:disabled {
  cursor: not-allowed;
  border-style: dashed;
  opacity: 0.6;
}
.f12-checkbox-input:checked,
.f12-checkbox-input:indeterminate,
.f12-checkbox-input.f12-checkbox-indeterminate,
.f12-checkbox-input[data-indeterminate="true"] {
  background: var(--f-ink);
}
.f12-checkbox-mark,
.f12-radio-mark {
  position: absolute;
  inset: 0;
  width: 16px;
  height: 16px;
  margin: auto;
  pointer-events: none;
  opacity: 0;
}
.f12-checkbox-mark {
  color: var(--f-panel);
}
.f12-radio-mark {
  color: var(--f-ink);
}
.f12-checkbox-input:checked + .f12-checkbox-mark,
.f12-checkbox-input:indeterminate + .f12-checkbox-mark,
.f12-checkbox-input.f12-checkbox-indeterminate + .f12-checkbox-mark,
.f12-checkbox-input[data-indeterminate="true"] + .f12-checkbox-mark,
.f12-radio-input:checked + .f12-radio-mark {
  opacity: 1;
}

.f12-radio-group {
  border: 0;
  padding: 0;
  margin: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: var(--font-f-body);
  color: var(--f-ink);
}
.f12-radio-group.f12-radio-group-compact {
  gap: 6px;
}
.f12-radio-legend {
  padding: 0;
  margin-bottom: 6px;
}
.f12-radio-items {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.f12-radio-group.f12-radio-group-compact .f12-radio-items {
  gap: 6px;
}
.f12-radio-group.f12-radio-group-horizontal .f12-radio-items {
  flex-direction: row;
  flex-wrap: wrap;
  gap: 10px 18px;
}
.f12-radio-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.f12-switch {
  position: relative;
  display: inline-grid;
  flex: none;
  min-width: 54px;
  width: max-content;
  height: 28px;
}
.f12-switch.f12-switch-compact {
  min-width: 48px;
  height: 24px;
}
.f12-switch-input {
  position: absolute;
  inset: 0;
  z-index: 1;
  -webkit-appearance: none;
  appearance: none;
  margin: 0;
  width: 100%;
  height: 100%;
  background: var(--f-panel);
  border: var(--f-stroke) solid var(--f-rule);
  border-radius: 0;
  cursor: pointer;
  display: block;
}
.f12-switch-input.f12-switch-input-compact {
  border-width: 1.5px;
}
.f12-switch-input:checked {
  background: var(--f-ink);
}
.f12-switch-input:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-switch-input:disabled {
  cursor: not-allowed;
  border-style: dashed;
  opacity: 0.6;
}
.f12-switch-track {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  pointer-events: none;
  display: inline-grid;
  align-items: center;
  overflow: hidden;
  background: var(--f-panel);
  border: var(--f-stroke) solid var(--f-rule);
  box-sizing: border-box;
}
.f12-switch-input.f12-switch-input-compact + .f12-switch-track {
  border-width: 1.5px;
}
.f12-switch-input:checked + .f12-switch-track {
  background: var(--f-ink);
}
.f12-switch-input:disabled + .f12-switch-track {
  border-style: dashed;
  opacity: 0.6;
}
.f12-switch-glyph {
  grid-area: 1 / 1;
  font-family: var(--font-f-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
  user-select: none;
}
.f12-switch-glyph-on {
  justify-self: start;
  padding-inline-start: 4px;
  padding-inline-end: 22px;
  color: var(--f-panel);
  opacity: 0;
}
.f12-switch-glyph-off {
  justify-self: end;
  padding-inline-start: 22px;
  padding-inline-end: 4px;
  color: var(--f-ink-2);
  opacity: 1;
}
.f12-switch.f12-switch-compact .f12-switch-glyph-on {
  padding-inline-start: 4px;
  padding-inline-end: 20px;
}
.f12-switch.f12-switch-compact .f12-switch-glyph-off {
  padding-inline-start: 20px;
  padding-inline-end: 4px;
}
.f12-switch-input:checked + .f12-switch-track .f12-switch-glyph-on {
  opacity: 1;
}
.f12-switch-input:checked + .f12-switch-track .f12-switch-glyph-off {
  opacity: 0;
}
.f12-switch-thumb {
  position: absolute;
  top: 2px;
  bottom: 2px;
  width: 16px;
  inset-inline-start: 2px;
  background: var(--f-ink);
  border: 1.5px solid var(--f-rule);
}
.f12-switch.f12-switch-compact .f12-switch-thumb {
  top: 2px;
  bottom: 2px;
  width: 14px;
  inset-inline-start: 2px;
}
.f12-switch-input:checked + .f12-switch-track .f12-switch-thumb {
  inset-inline-start: calc(100% - 18px);
  background: var(--f-panel);
  border-color: var(--f-panel);
}
.f12-switch.f12-switch-compact .f12-switch-input:checked + .f12-switch-track .f12-switch-thumb {
  inset-inline-start: calc(100% - 16px);
}

.f12-tabs {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
  font-family: var(--font-f-body);
  color: var(--f-ink);
}
.f12-tabs.f12-tabs-compact {
  gap: 10px;
}
.f12-tabs.f12-tabs-vertical {
  flex-direction: row;
  align-items: flex-start;
  gap: 18px;
}
.f12-tabs-list {
  display: flex;
  flex-wrap: wrap;
  border: var(--f-stroke) solid var(--f-rule);
  background: var(--f-panel);
  width: fit-content;
  max-width: 100%;
  /* Breathing room when a block scrolls its section tabs into view (breadcrumb navigation). */
  scroll-margin-block-start: var(--f-gutter-scene);
}
.f12-tabs-list.f12-tabs-list-compact {
  border-width: 1.5px;
}
.f12-tabs.f12-tabs-vertical > .f12-tabs-list {
  flex-direction: column;
  flex: none;
}
.f12-tabs-trigger {
  flex: 1 1 auto;
  cursor: pointer;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 0;
  padding: 8px 16px;
  min-height: 36px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  line-height: 1.2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.f12-tabs-trigger + .f12-tabs-trigger {
  border-inline-start: 2px solid var(--f-rule);
}
.f12-tabs.f12-tabs-vertical > .f12-tabs-list .f12-tabs-trigger + .f12-tabs-trigger {
  border-inline-start: 0;
  border-top: 2px solid var(--f-rule);
}
.f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger {
  padding: 5px 12px;
  min-height: 28px;
  font-size: 11px;
}
.f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger + .f12-tabs-trigger {
  border-inline-start-width: 1.5px;
}
.f12-tabs.f12-tabs-vertical > .f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger + .f12-tabs-trigger {
  border-inline-start-width: 0;
  border-top-width: 1.5px;
}
.f12-tabs-trigger[aria-selected="true"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-tabs-trigger:disabled {
  cursor: not-allowed;
  color: var(--f-ink-2);
  opacity: 0.55;
}
.f12-tabs-trigger:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -5px;
}
.f12-tabs-trigger[aria-selected="true"]:focus-visible {
  outline-color: var(--f-panel);
}
.f12-tabs-content {
  min-width: 0;
  flex: 1;
  width: 100%;
  --f12-autocut-display: none;
}
.f12-tabs-content[hidden] {
  display: none;
}
.f12-tabs-content .f12-cut[data-autocut] {
  display: none;
  counter-increment: none;
}
.f12-tabs-content:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}

/* ===================================================================== Alert, Notice, Toast, Skeleton, EmptyState, Breadcrumb & Pagination */
.f12-alert {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: var(--f-gutter-pair);
  padding: 14px 16px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  font-family: var(--font-f-body);
  min-width: 0;
}
.f12-alert-neutral {
  border: 1.5px solid var(--f-rule);
}
.f12-alert-info {
  border: 2px solid var(--f-rule);
}
.f12-alert-success {
  border: 2px solid var(--f-rule);
  border-inline-start: 6px solid var(--f-rule);
}
.f12-alert-warning {
  border: 2px dashed var(--f-rule);
  background-color: var(--f-panel);
  background-image: repeating-linear-gradient(
    -45deg,
    transparent 0 8px,
    var(--f-grid) 8px 9.5px
  );
}
.f12-alert-danger {
  border: 3px double var(--f-rule);
  border-inline-start: 6px solid var(--f-rule);
}
.f12-alert-glyph {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 6px;
  margin: 0;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--f-ink);
  background: var(--f-panel);
  border: 1.5px solid var(--f-rule);
}
.f12-alert-success .f12-alert-glyph {
  border-inline-start-width: 4px;
}
.f12-alert-warning .f12-alert-glyph {
  border-style: dashed;
}
.f12-alert-danger .f12-alert-glyph {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-alert-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.f12-alert-title {
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  line-height: 1.3;
  color: var(--f-ink);
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-alert-description {
  font-family: var(--font-f-body);
  font-size: 13px;
  line-height: 1.45;
  color: var(--f-ink);
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-alert-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
}
.f12-alert-dismiss {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  min-height: 28px;
  padding: 2px 6px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 1.5px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
}
.f12-alert-dismiss:hover {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-alert-dismiss:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-alert.f12-alert-compact {
  padding: 10px 12px;
}
.f12-alert.f12-alert-compact .f12-alert-title {
  font-size: 11px;
}
.f12-alert.f12-alert-compact .f12-alert-description {
  font-size: 12px;
}
.f12-alert.f12-alert-compact .f12-alert-dismiss {
  min-width: 24px;
  min-height: 24px;
}

.f12-toast-viewport {
  position: fixed;
  inset-inline-end: 20px;
  bottom: 20px;
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-pair);
  width: min(380px, calc(100vw - 24px));
  max-width: 100%;
  max-height: calc(100vh - 32px);
  max-height: calc(100dvh - 32px);
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0 6px 6px 0;
  box-sizing: border-box;
  pointer-events: auto;
  font-family: var(--font-f-body);
}
.f12-toast-viewport:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-toast-viewport:empty {
  display: none;
  pointer-events: none;
}
.f12-toast-viewport.f12-toast-viewport-compact {
  width: min(340px, calc(100vw - 24px));
}
@media (max-width: 480px) {
  .f12-toast-viewport,
  .f12-toast-viewport.f12-toast-viewport-compact {
    inset-inline-end: 12px;
    bottom: 12px;
    width: calc(100vw - 24px);
    max-height: calc(100vh - 24px);
    max-height: calc(100dvh - 24px);
  }
}
.f12-toast {
  pointer-events: auto;
  position: relative;
  flex-shrink: 0;
  display: flex;
  align-items: flex-start;
  gap: var(--f-gutter-pair);
  padding: 12px 14px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  box-shadow: 4px 4px 0 var(--f-rule);
  min-width: 0;
}
.f12-toast-neutral {
  border: 1.5px solid var(--f-rule);
}
.f12-toast-info {
  border: 2px solid var(--f-rule);
}
.f12-toast-success {
  border: 2px solid var(--f-rule);
  border-inline-start: 6px solid var(--f-rule);
}
.f12-toast-warning {
  border: 2px dashed var(--f-rule);
  background-color: var(--f-panel);
  background-image: repeating-linear-gradient(
    -45deg,
    transparent 0 8px,
    var(--f-grid) 8px 9.5px
  );
}
.f12-toast-danger {
  border: 3px double var(--f-rule);
  border-inline-start: 6px solid var(--f-rule);
}
.f12-toast-glyph {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 6px;
  margin: 0;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--f-ink);
  background: var(--f-panel);
  border: 1.5px solid var(--f-rule);
}
.f12-toast-success .f12-toast-glyph {
  border-inline-start-width: 4px;
}
.f12-toast-warning .f12-toast-glyph {
  border-style: dashed;
}
.f12-toast-danger .f12-toast-glyph {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-toast-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.f12-toast-title {
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  line-height: 1.3;
  color: var(--f-ink);
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-toast-description {
  font-family: var(--font-f-body);
  font-size: 13px;
  line-height: 1.4;
  color: var(--f-ink);
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-toast-controls {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
}
.f12-toast-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
  min-width: 28px;
  padding: 4px 10px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 1.5px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  line-height: 1.1;
  cursor: pointer;
}
.f12-toast-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  min-height: 28px;
  padding: 2px 6px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 1.5px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
}
.f12-toast-action:hover,
.f12-toast-close:hover {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-toast-action:focus-visible,
.f12-toast-close:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-toast-queue-badge {
  pointer-events: auto;
  flex-shrink: 0;
  align-self: flex-end;
  padding: 3px 8px;
  background: var(--f-ink);
  color: var(--f-panel);
  border: 1.5px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.f12-toast.f12-toast-compact {
  padding: 9px 12px;
  box-shadow: 3px 3px 0 var(--f-rule);
}
.f12-toast.f12-toast-compact .f12-toast-title {
  font-size: 11px;
}
.f12-toast.f12-toast-compact .f12-toast-description {
  font-size: 12px;
}
.f12-toast.f12-toast-compact .f12-toast-action,
.f12-toast.f12-toast-compact .f12-toast-close {
  min-height: 24px;
  min-width: 24px;
}

.f12-skeleton {
  position: relative;
  display: block;
  box-sizing: border-box;
  width: 100%;
  height: 20px;
  background-color: var(--f-panel);
  background-image: radial-gradient(circle, var(--f-tone) 1.15px, transparent 1.45px);
  background-size: 6px 6px;
  border: 1.5px dashed var(--f-rule);
  border-radius: 0;
}
.f12-skeleton-line {
  height: 14px;
  border-style: solid;
  border-width: 1px;
  border-color: var(--f-grid);
}
.f12-skeleton-circle {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  flex: none;
}
.f12-skeleton-metric {
  height: 44px;
  max-width: 180px;
  border: 2px solid var(--f-rule);
}
.f12-skeleton-panel {
  min-height: 120px;
  border: 2px dashed var(--f-rule);
}
.f12-skeleton.f12-skeleton-compact {
  height: 16px;
}
.f12-skeleton-line.f12-skeleton-compact {
  height: 12px;
}
.f12-skeleton-circle.f12-skeleton-compact {
  width: 28px;
  height: 28px;
}
.f12-skeleton-metric.f12-skeleton-compact {
  height: 32px;
}
.f12-skeleton-panel.f12-skeleton-compact {
  min-height: 88px;
}
.f12-skeleton-text {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}
.f12-skeleton-text.f12-skeleton-text-compact {
  gap: 6px;
}

.f12-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 10px;
  padding: 32px 20px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px dashed var(--f-rule);
  font-family: var(--font-f-body);
  min-width: 0;
}
.f12-empty.f12-empty-quiet {
  border: 1px solid var(--f-rule);
  padding: 24px 18px;
}
.f12-empty.f12-empty-compact {
  padding: 20px 16px;
  gap: 8px;
}
.f12-empty-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px 10px;
  font-family: var(--font-f-mono);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--f-ink);
  background-color: var(--f-panel);
  background-image: radial-gradient(circle, var(--f-tone) 1px, transparent 1.3px);
  background-size: 5px 5px;
  border: 1.5px solid var(--f-rule);
}
.f12-empty-code {
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-empty-title {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: 22px;
  line-height: 1.15;
  letter-spacing: 0.02em;
  color: var(--f-ink);
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-empty.f12-empty-compact .f12-empty-title {
  font-size: 18px;
}
.f12-empty-description {
  font-family: var(--font-f-body);
  font-size: 13px;
  line-height: 1.45;
  color: var(--f-ink-2);
  max-width: 23.2em;
  margin: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-empty.f12-empty-compact .f12-empty-description {
  font-size: 12px;
}
.f12-empty-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--f-gutter-pair);
  margin-top: 6px;
}

.f12-breadcrumb {
  display: block;
  font-family: var(--font-f-mono);
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  min-width: 0;
}
.f12-breadcrumb-list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 8px;
  list-style: none;
  padding: 0;
  margin: 0;
}
.f12-breadcrumb-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.f12-breadcrumb-link {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 2px 4px;
  color: var(--f-ink-2);
  /* Non-colour cue: actionable crumbs and plain ancestor text share --f-ink-2 (WCAG 1.4.1). */
  text-decoration: underline dotted 1px;
  text-underline-offset: 3px;
  cursor: pointer;
}
.f12-breadcrumb-link:hover {
  color: var(--f-ink);
  text-decoration-style: solid;
}
/* <BreadcrumbButton>: in-page action crumb rendered with link chrome. */
button.f12-breadcrumb-link {
  appearance: none;
  margin: 0;
  border: 0;
  border-radius: 0;
  background: none;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  text-align: inherit;
}
.f12-breadcrumb-link:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
  color: var(--f-ink);
}
.f12-breadcrumb-page {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 2px 6px;
  font-weight: 700;
  color: var(--f-ink);
  border-bottom: 2px solid var(--f-rule);
}
.f12-breadcrumb-page:not([aria-current]) {
  font-weight: 500;
  color: var(--f-ink-2);
  border-bottom: 0;
}
.f12-breadcrumb-separator {
  display: inline-flex;
  align-items: center;
  color: var(--f-ink-2);
  user-select: none;
}
.f12-breadcrumb-ellipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  min-height: 24px;
  padding: 0 4px;
  color: var(--f-ink-2);
  border: 1px dashed var(--f-rule);
}
.f12-breadcrumb.f12-breadcrumb-compact {
  font-size: 10px;
}
.f12-breadcrumb.f12-breadcrumb-compact .f12-breadcrumb-list {
  gap: 2px 6px;
}
/* Sheet header: give the path its own line above the eyebrow (the current-item rule otherwise
   lands on the eyebrow tags) and pull the first crumb's padding back onto the text edge. */
.f12-hd-text > .f12-breadcrumb:not(:last-child) {
  margin-bottom: 14px;
}
.f12-hd-text > .f12-breadcrumb .f12-breadcrumb-item:first-child > .f12-breadcrumb-link {
  margin-inline-start: -4px;
}
.f12-hd-text > .f12-breadcrumb .f12-breadcrumb-item:first-child > .f12-breadcrumb-page {
  margin-inline-start: -6px;
}

.f12-pagination {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--f-gutter-pair);
  font-family: var(--font-f-mono);
  color: var(--f-ink);
  min-width: 0;
}
.f12-pagination-summary {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: var(--f-ink-2);
}
.f12-pagination-list {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  list-style: none;
  padding: 0;
  margin: 0;
}
.f12-pagination-item {
  display: inline-flex;
  align-items: center;
}
.f12-pagination-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 34px;
  min-height: 34px;
  padding: 6px 10px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  box-sizing: border-box;
}
.f12-pagination-link:hover:not(:disabled):not([aria-disabled="true"]):not(.f12-pagination-link-active) {
  box-shadow: 2px 2px 0 var(--f-rule);
}
.f12-pagination-link:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-pagination-link-active,
.f12-pagination-link[aria-current="page"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-pagination-link:disabled,
.f12-pagination-link-disabled,
.f12-pagination-link[aria-disabled="true"] {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
  opacity: 0.6;
  box-shadow: none;
}
.f12-pagination-prev,
.f12-pagination-next {
  padding: 6px 12px;
}
.f12-pagination-arrow {
  font-size: 14px;
  line-height: 1;
}
.f12-pagination-ellipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  min-height: 34px;
  padding: 0 4px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  color: var(--f-ink-2);
  user-select: none;
}
.f12-pagination.f12-pagination-compact .f12-pagination-list {
  gap: 4px;
}
.f12-pagination-link.f12-pagination-link-compact,
.f12-pagination.f12-pagination-compact .f12-pagination-link {
  min-width: 28px;
  min-height: 28px;
  padding: 4px 8px;
  font-size: 11px;
  border-width: 1.5px;
}
.f12-pagination.f12-pagination-compact .f12-pagination-ellipsis {
  min-width: 24px;
  min-height: 28px;
  font-size: 11px;
}

/* ===================================================================== Metric, Delta & Spark */
.f12-metric {
  display: flex;
  flex-direction: column;
  flex: 1;
}
.f12-m-label {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-m-value {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: 34px;
  line-height: 1.22;
  padding-bottom: 2px;
  margin: 10px 0 0;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
  color: var(--f-ink);
}
/* Expressive hero: sized to its own column, not the sheet. --f12-m-chars (set by <Metric> from
   the final formatted value) and ~0.8em per display-font glyph keep the longest value inside
   its panel; 14cqi caps short values so they don't balloon in wide columns. */
.f12-metric.big {
  container-type: inline-size;
  min-width: min(100%, 12rem);
}
.f12-metric.big .f12-m-value {
  font-size: clamp(20px, min(14cqi, 100cqi / (var(--f12-m-chars, 8) * 0.8)), 56px);
  line-height: 1.1;
  font-variant-numeric: proportional-nums;
  overflow-wrap: anywhere;
}
.f12-metric.f12-metric-quiet .f12-m-value {
  font-family: var(--font-f-mono);
  font-weight: 700;
  font-size: 22px;
  line-height: 1.2;
  margin-top: 6px;
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
}
.f12-metric.f12-metric-quiet .f12-delta {
  margin-top: 8px;
  font-size: 11px;
}
.f12-metric.f12-metric-quiet .f12-m-note {
  font-size: 12px;
  margin-top: 4px;
}
.f12-delta {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
  font-variant-numeric: tabular-nums;
  font-family: var(--font-f-mono);
  font-size: 12px;
  margin: 14px 0 0;
  letter-spacing: 0.02em;
  color: var(--f-ink);
}
.f12-delta-sym {
  font-size: 10px;
}
.f12-delta.up .f12-delta-sym,
.f12-delta.down .f12-delta-sym {
  color: var(--f-marker-ink);
  background: var(--f-marker);
  padding: 0 3px;
}
.f12-delta-ref {
  color: var(--f-ink-2);
}
.f12-m-note {
  font-size: 13px;
  color: var(--f-ink-2);
  margin: 6px 0 0;
  max-width: 15.1em;
}

.f12-spark {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: auto;
  padding-top: 16px;
}
.f12-spark svg {
  display: block;
  width: 100%;
  border-bottom: 2px solid var(--f-rule);
  overflow: visible;
}
.f12-spark-l {
  font-family: var(--font-f-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-spark-bar {
  stroke: var(--f-ink);
  stroke-width: 1;
}

/* ===================================================================== Chart, Balloon & Data Table */
.f12-c01-hd {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: flex-end;
  gap: 12px 24px;
  margin-bottom: 4px;
}
.f12-c01-hd > .f12-metric {
  flex: 1 1 220px;
}
.f12-legend,
.f12-legend-hint {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--f-ink-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.f12-legend li {
  display: flex;
  align-items: center;
  gap: 6px;
}
.f12-legend-hint {
  max-width: 13em;
}
.f12-sw {
  display: inline-block;
  width: 14px;
  height: 0;
  border-top-width: 2px;
  border-top-style: solid;
  flex: none;
}
.f12-sw-total {
  border-color: var(--f-ink);
  border-top-width: var(--f-stroke);
}
.f12-sw-focus {
  border-color: var(--f-ink);
  border-top-style: dashed;
}

.f12-chart {
  position: relative;
  width: 100%;
  touch-action: pan-y;
}
.f12-chart-svg {
  display: block;
  width: 100%;
  overflow: visible;
}
.f12-chart-svg:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 4px;
}
.f12-chart text {
  fill: var(--f-ink-2);
  font-family: var(--font-f-mono);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}
.f12-grid {
  stroke: var(--f-grid);
}
.f12-baseline {
  stroke: var(--f-rule);
  stroke-width: 2;
}
.f12-sheet-ticks line {
  stroke: var(--f-rule);
  stroke-width: 1;
}
.f12-tone-dot {
  fill: var(--f-tone);
}
.f12-l-total {
  stroke: var(--f-ink);
  stroke-width: var(--f-stroke);
  stroke-linejoin: round;
  stroke-linecap: round;
}
.f12-l-focus {
  stroke: var(--f-ink);
  stroke-width: 2;
  stroke-dasharray: 6 4;
  stroke-linejoin: round;
}
.f12-tail {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: 2;
  stroke-linejoin: miter;
}
.f12-g-tag {
  fill: var(--f-marker);
}
.f12-peak-dot {
  fill: var(--f-marker);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.f12-balloon {
  position: absolute;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  max-width: calc(100% - 60px);
  min-width: 0;
  padding: 3px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  border-radius: 14px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-balloon-gap {
  position: absolute;
  /* Centred default (tail offset 0); <Balloon> sets the exact offset inline. */
  left: calc(50% - 5px);
  bottom: -2px;
  width: 10px;
  height: 3px;
  background: var(--f-panel);
}
.f12-balloon-standalone {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  max-width: 100%;
  min-width: 0;
}
.f12-balloon-standalone .f12-balloon {
  position: relative;
  max-width: 100%;
  min-height: 28px;
}
.f12-balloon-standalone-svg {
  display: block;
  overflow: visible;
  margin-top: -1px;
}

.f12-cross line {
  stroke: var(--f-ink);
  stroke-width: 1;
}
.f12-cross-dot {
  fill: var(--f-marker);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.f12-compare-pt,
.f12-cross-dot2 {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.f12-tip {
  position: absolute;
  z-index: 3;
  pointer-events: none;
  display: grid;
  gap: 2px;
  min-width: 160px;
  padding: 8px 10px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  background: var(--f-panel);
  border: 2px solid var(--f-rule);
  color: var(--f-ink);
  font-family: var(--font-f-mono);
  box-shadow: 4px 4px 0 var(--f-rule);
}
.f12-tip span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.f12-tbl {
  margin-top: 10px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  color: var(--f-ink);
}
.f12-tbl summary {
  cursor: pointer;
  width: fit-content;
  max-width: 100%;
  padding: 4px 0;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.f12-tbl-scroll {
  max-height: 240px;
  overflow: auto;
  margin-top: 6px;
}
.f12-tbl table {
  border-collapse: collapse;
  width: 100%;
  font-variant-numeric: tabular-nums;
}
.f12-tbl th,
.f12-tbl td {
  text-align: left;
  padding: 5px 10px 5px 0;
  white-space: nowrap;
}
.f12-tbl th {
  color: var(--f-ink-2);
  font-weight: 500;
  border-bottom: 2px solid var(--f-rule);
}
.f12-tbl td {
  border-bottom: 1px solid var(--f-grid);
}

/* ===================================================================== ToneBarList (Interventions) */
.f12-ints-hd {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: 6px 16px;
  margin-bottom: 14px;
}
.f12-ints-sub {
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
  letter-spacing: 0.04em;
  margin: 0;
}
.f12-ints-list {
  display: grid;
  list-style: none;
  padding: 0;
  margin: 0;
}
.f12-ints-list li + li {
  border-top: 1px solid var(--f-grid);
}
.f12-int-row {
  all: unset;
  box-sizing: border-box;
  cursor: pointer;
  display: grid;
  width: 100%;
  align-items: center;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 2fr) auto;
  gap: 16px;
  padding: 12px 8px;
  color: var(--f-ink);
}
.f12-int-row:hover .f12-int-name {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.f12-int-row:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -3px;
}
.f12-int-name {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex-wrap: wrap;
  font-size: 15px;
  font-weight: 700;
}
.f12-int-bar {
  position: relative;
  display: block;
  height: 16px;
  border: 2px solid var(--f-rule);
}
.f12-int-fill {
  position: absolute;
  inset: 0 auto 0 0;
  background-image: radial-gradient(circle, var(--f-tone) 1.1px, transparent 1.4px);
  background-size: 5px 5px;
  border-right: 2px solid var(--f-rule);
}
.f12-int-fill-hatch {
  background-image: repeating-linear-gradient(
    -45deg,
    var(--f-tone) 0,
    var(--f-tone) 1.25px,
    transparent 1.25px,
    transparent 5px
  );
  background-size: auto;
}
.f12-int-fill-dense {
  background-image: radial-gradient(circle, var(--f-tone) 1.55px, transparent 1.85px);
  background-size: 4px 4px;
}
.f12-ints.f12-ints-compact .f12-int-row {
  padding: 7px 6px;
  gap: 12px;
}
.f12-ints.f12-ints-compact .f12-int-name {
  font-size: 13px;
}
.f12-ints.f12-ints-compact .f12-int-bar {
  height: 12px;
  border-width: 1.5px;
}
.f12-int-row[aria-pressed="true"],
.f12-int-row[aria-current="true"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-int-row[aria-pressed="true"]:focus-visible {
  outline-color: var(--f-panel);
}
.f12-int-row[aria-pressed="true"] .f12-int-bar,
.f12-int-row[aria-current="true"] .f12-int-bar {
  border-color: var(--f-panel);
}
.f12-int-row[aria-pressed="true"] .f12-int-fill,
.f12-int-row[aria-current="true"] .f12-int-fill {
  background: var(--f-marker);
  border-right-color: var(--f-panel);
}
.f12-int-row[aria-pressed="true"] .f12-int-share,
.f12-int-row[aria-current="true"] .f12-int-share {
  color: var(--f-panel);
}
.f12-int-row[aria-pressed="true"] .f12-badge,
.f12-int-row[aria-current="true"] .f12-badge {
  border-color: var(--f-panel);
}
/* Non-interactive rows (rendered by @frame12/static): same layout, no pointer affordance. */
.f12-int-row[data-static] {
  cursor: default;
}
.f12-int-row[data-static]:hover .f12-int-name {
  text-decoration: none;
}
.f12-int-val {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  font-family: var(--font-f-mono);
  font-size: 13px;
  font-weight: 500;
}
.f12-int-share {
  min-width: 3ch;
  text-align: right;
  color: var(--f-ink-2);
}

/* ===================================================================== Adapters: Dialog, Select, Tooltip, DropdownMenu, Table */

/* Dialog */
dialog.f12-dialog {
  margin: auto;
  background: var(--f-panel);
  color: var(--f-ink);
  border: var(--f-stroke) solid var(--f-rule);
  box-shadow: 6px 6px 0 var(--f-rule);
  padding: 34px 22px 22px;
  max-width: 480px;
  width: calc(100% - 32px);
  font-family: var(--font-f-body);
}
dialog.f12-dialog:modal {
  overscroll-behavior: contain;
}
dialog.f12-dialog::backdrop {
  overflow: hidden;
  overscroll-behavior: contain;
  background-color: var(--f-backdrop);
  background-image: radial-gradient(circle, rgba(18, 18, 18, 0.35) 0.85px, transparent 1.35px);
  background-size: 8px 8px;
}
dialog.f12-dialog > .f12-cut {
  top: 8px;
  left: 22px;
  padding: 1px 6px;
  background: var(--f-sheet);
  border: 1.5px solid var(--f-rule);
}
.f12-dialog-header {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}
.f12-dialog-title {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: 24px;
  line-height: 1.1;
  color: var(--f-ink);
  margin: 0;
}
.f12-dialog-description {
  font-size: 14px;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-dialog-footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--f-gutter-pair);
  margin-top: 20px;
}

/* Select */
.f12-select {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  gap: 6px;
  min-width: 180px;
  font-family: var(--font-f-body);
}
.f12-select-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--f-gutter-pair);
  width: 100%;
  padding: 8px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: var(--f-stroke) solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
}
.f12-select-trigger:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-select.f12-select-compact {
  gap: 4px;
}
.f12-select.f12-select-compact .f12-select-trigger {
  padding: 6px 10px;
  font-size: 13px;
  line-height: 1.4;
  border-width: 1.5px;
}
.f12-select-caret {
  display: inline-block;
  padding: 1px 4px;
  font-size: 10px;
  background: var(--f-marker);
  color: var(--f-marker-ink);
  border: 1.5px solid var(--f-rule);
  line-height: 1;
}
.f12-select-content {
  z-index: 50;
  min-width: var(--radix-select-trigger-width, 180px);
  max-height: var(--radix-select-content-available-height, 300px);
  overflow-y: auto;
  background: var(--f-panel);
  color: var(--f-ink);
  border: var(--f-stroke) solid var(--f-rule);
  box-shadow: 4px 4px 0 var(--f-rule);
  list-style: none;
  margin: 0;
  padding: 0;
}
.f12-select-viewport {
  padding: 0;
}
.f12-select-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 8px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 0;
  border-bottom: 1px solid var(--f-grid);
  font-family: var(--font-f-mono);
  font-size: 12px;
  cursor: pointer;
  text-align: left;
  user-select: none;
}
.f12-select-item:last-child {
  border-bottom: 0;
}
.f12-select-item:hover,
.f12-select-item[data-highlighted],
.f12-select-item[aria-selected="true"],
.f12-select-item[data-state="checked"] {
  background: var(--f-ink);
  color: var(--f-panel);
  outline: none;
}
.f12-select-item:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -3px;
}
.f12-select-item[data-highlighted]:focus-visible,
.f12-select-item[aria-selected="true"]:focus-visible,
.f12-select-item[data-state="checked"]:focus-visible {
  outline: 2px solid var(--f-panel);
  outline-offset: -4px;
}
.f12-select-item[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}
.f12-select-check {
  background: var(--f-marker);
  color: var(--f-marker-ink);
  padding: 0 4px;
  font-size: 10px;
  font-weight: 700;
}
.f12-select-label {
  padding: 6px 12px 4px;
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-select-sep {
  height: 1px;
  background: var(--f-grid);
  margin: 4px 0;
}

/* Tooltip */
.f12-tooltip-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}
.f12-tooltip {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  z-index: 50;
  white-space: nowrap;
  padding: 5px 10px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  box-shadow: 3px 3px 0 var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 11px;
  pointer-events: none;
}

/* DropdownMenu */
.f12-menu-wrap {
  position: relative;
  display: inline-block;
}
.f12-menu {
  z-index: 50;
  min-width: 180px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: var(--f-stroke) solid var(--f-rule);
  box-shadow: 4px 4px 0 var(--f-rule);
  padding: 4px 0;
}
.f12-menu-label {
  padding: 6px 12px 4px;
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-menu-sep {
  height: 1px;
  background: var(--f-grid);
  margin: 4px 0;
}
.f12-menu-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 7px 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 0;
  font-family: var(--font-f-body);
  font-size: 13px;
  cursor: pointer;
  text-align: left;
  user-select: none;
}
.f12-menu-item:hover,
.f12-menu-item[data-highlighted],
.f12-menu-item:focus-visible {
  background: var(--f-ink);
  color: var(--f-panel);
  outline: none;
}
.f12-menu-item:focus-visible {
  outline: 2px solid var(--f-panel);
  outline-offset: -4px;
}
.f12-menu-item[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Table */
.f12-table-wrap {
  width: 100%;
  overflow-x: auto;
}
.f12-table-wrap:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--font-f-body);
  font-size: 13px;
  color: var(--f-ink);
  font-variant-numeric: tabular-nums;
}
.f12-table caption {
  caption-side: bottom;
  padding-top: 8px;
  text-align: left;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
}
.f12-table th,
.f12-table td {
  text-align: left;
  padding: 8px 12px 8px 0;
  border-bottom: 1px solid var(--f-grid);
}
.f12-table thead th {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  border-bottom: var(--f-stroke) solid var(--f-rule);
}
.f12-table tfoot td,
.f12-table tfoot th {
  font-family: var(--font-f-mono);
  font-weight: 700;
  border-top: 2px solid var(--f-rule);
  border-bottom: 0;
}
.f12-table.f12-table-compact {
  font-size: 13px;
}
.f12-table.f12-table-compact th,
.f12-table.f12-table-compact td {
  padding: 5px 10px 5px 0;
}
.f12-table.f12-table-compact thead th {
  border-bottom-width: 1.5px;
}

/* ===================================================================== Application Block & Layout Utilities */
.f12-stack-pair {
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-pair);
  min-width: 0;
}
.f12-stack-scene {
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-scene);
  min-width: 0;
}
.f12-row-pair {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--f-gutter-pair);
}
.f12-row-between {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--f-gutter-pair) var(--f-gutter-scene);
}
.f12-section-title {
  margin: 0;
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: clamp(20px, 3vw, 28px);
  line-height: 1.1;
  color: var(--f-ink);
}
.f12-body-copy {
  margin: 0;
  font-size: 15px;
  line-height: 1.55;
  color: var(--f-ink);
  max-width: 34.25em;
}
.f12-muted-copy {
  margin: 0;
  font-size: 14px;
  line-height: 1.5;
  color: var(--f-ink-2);
  max-width: 33.25em;
}
.f12-mono-note {
  margin: 0;
  font-family: var(--font-f-mono);
  font-size: 13px;
  line-height: 1.5;
  color: var(--f-ink-2);
}
.f12-code-inline {
  font-family: var(--font-f-mono);
  font-size: 0.92em;
  padding: 1px 5px;
  border: 1px solid var(--f-grid);
  background-color: var(--f-sheet);
  color: var(--f-ink);
  overflow-wrap: anywhere;
}
.f12-nowrap {
  white-space: nowrap;
}

.f12-console .f12-hd > .f12-hd-text {
  flex: 1 1 540px;
}
.f12-console .f12-sub {
  max-width: 64ch;
  font-size: 13px;
  line-height: 1.5;
  margin-top: 6px;
}
.f12-console-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--f-gutter-pair) var(--f-gutter-scene);
  min-width: 0;
}
/* Sheet-header toolbar: sit the environment Select beside the range SegmentedControl at the
   same 44px height and rule weight, packed left like the other blocks' header control rows. */
.f12-console-hd-toolbar {
  justify-content: flex-start;
}
.f12-console-hd-toolbar .f12-select-trigger {
  min-height: 44px;
}
.f12-console-filters {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: var(--f-gutter-pair);
  align-items: end;
  min-width: 0;
}
.f12-console-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--f-gutter-pair);
  min-width: 0;
}
.f12-console .f12-int-row {
  grid-template-columns: minmax(220px, 1.75fr) minmax(52px, 1fr) minmax(0, auto);
  gap: var(--f-gutter-pair);
}
.f12-console .f12-int-name {
  font-size: 13px;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.f12-console .f12-int-val {
  font-size: 13px;
  min-width: 0;
}
.f12-console-kpi-scene > .f12-panel > .f12-panel-body {
  padding: 20px 18px 16px;
}
.f12-console-kpi-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: var(--f-gutter-pair);
  height: 100%;
  min-width: 0;
}
.f12-console-kpi-card .f12-m-value {
  margin-top: 4px;
  line-height: 1.08;
}
.f12-console-kpi-card .f12-delta {
  margin-top: 8px;
  font-size: 12.5px;
}
.f12-console-kpi-spark {
  margin-top: auto;
}
.f12-console-kpi-spark .f12-spark {
  margin-top: 0;
  padding-top: 4px;
}
.f12-console-kpi-spark .f12-spark-l {
  font-size: 11px;
  line-height: 1.35;
  letter-spacing: 0.1em;
}
.f12-console-kpi-spark .f12-spark svg {
  height: 38px;
}
.f12-console-kv-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: var(--f-gutter-pair);
  margin: 0;
  min-width: 0;
}
.f12-console-kv-list.f12-console-kpi-foot {
  margin-top: auto;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.f12-console-kv-item {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
  padding: 8px 11px;
  border: 1px solid var(--f-grid);
  background: var(--f-sheet);
}
.f12-console-kpi-foot .f12-console-kv-item {
  padding: 7px 10px;
}
.f12-console-kv-label {
  font-family: var(--font-f-mono);
  font-size: 11.5px;
  line-height: 1.35;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-console-kpi-foot .f12-console-kv-label {
  font-size: 11px;
  letter-spacing: 0.06em;
}
.f12-console-kv-value {
  margin-top: 3px;
  font-family: var(--font-f-mono);
  font-size: 13.5px;
  line-height: 1.4;
  font-weight: 700;
  color: var(--f-ink);
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.f12-console-kpi-foot .f12-console-kv-value {
  font-size: 13px;
}
.f12-console-chart-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--f-gutter-pair);
  min-width: 0;
}
.f12-console-kbd-hint {
  display: inline-flex;
  align-items: center;
  gap: 0;
  padding: 3px 8px;
  border: 1px dashed var(--f-rule);
  background: var(--f-sheet);
  font-family: var(--font-f-mono);
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--f-ink);
  white-space: nowrap;
}
.f12-console-kbd-hint kbd {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  padding: 0 4px;
  margin-inline-end: 4px;
  border: 1px solid var(--f-rule);
  background: var(--f-panel);
  color: var(--f-ink);
}
.f12-console-investigate-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--f-gutter-pair);
  padding-top: 4px;
  border-top: 1px solid var(--f-grid);
  min-width: 0;
}
.f12-console-investigate-bar > .f12-mono-note {
  flex: 1 1 240px;
}
.f12-console-code {
  margin: 0;
  padding: 10px 12px;
  border: 1.5px solid var(--f-rule);
  background: var(--f-sheet);
  color: var(--f-ink);
  font-family: var(--font-f-mono);
  font-size: 12px;
  line-height: 1.5;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  overflow-x: auto;
}
.f12-console-feed {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.f12-console-feed-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--f-gutter-pair);
  padding: 8px 0;
  border-bottom: 1px solid var(--f-grid);
  font-size: 13.5px;
}
.f12-console-feed-item:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.f12-console-quiet-title {
  margin: 0;
  font-family: var(--font-f-mono);
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--f-ink);
}
.f12-console-quiet-sub {
  margin: 0;
  font-family: var(--font-f-body);
  font-size: 13.5px;
  line-height: 1.5;
  color: var(--f-ink-2);
}

.f12-settings .f12-settings-posture-panel > .f12-panel-body {
  padding: 16px 18px 14px;
}
.f12-settings .f12-settings-posture-panel .f12-m-value {
  font-size: clamp(22px, 2.8vw, 30px);
}
.f12-settings .f12-settings-posture-panel .f12-console-kv-list {
  flex: 1 1 520px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.f12-settings td code.f12-code-inline {
  white-space: nowrap;
}
.f12-settings[data-high-contrast-rules="true"] .f12-panel.f12-panel-quiet,
.f12-settings[data-high-contrast-rules="true"] .f12-console-kv-item,
.f12-settings[data-high-contrast-rules="true"] .f12-settings-bar,
.f12-settings[data-high-contrast-rules="true"] .f12-settings-specimen {
  border-width: 2px;
  border-color: var(--f-rule);
}
.f12-settings[data-high-contrast-rules="true"] .f12-settings-danger-row {
  border-bottom-width: 2px;
  border-bottom-color: var(--f-rule);
}
.f12-settings-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--f-gutter-pair) var(--f-gutter-scene);
  padding: 10px 14px;
  border: 1.5px solid var(--f-rule);
  background: var(--f-panel);
  min-width: 0;
}
.f12-settings-bar[data-dirty="true"] {
  border-inline-start: 6px solid var(--f-rule);
  background-color: var(--f-sheet);
}
.f12-settings-specimen {
  display: flex;
  flex-direction: column;
  gap: var(--f-gutter-pair);
  padding: 12px 14px;
  border: 1px dashed var(--f-rule);
  background: var(--f-sheet);
  min-width: 0;
}
.f12-settings-danger-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--f-gutter-pair) var(--f-gutter-scene);
  padding: 12px 0;
  border-bottom: 1px solid var(--f-grid);
  min-width: 0;
}
.f12-settings-danger-row > .f12-stack-pair {
  flex: 1 1 320px;
}
.f12-settings-danger-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.f12-settings .f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger {
  padding: 6px 10px;
}

@media (max-width: 960px) {
  .f12-settings .f12-tabs-list {
    flex-direction: column;
    width: 100%;
  }
  .f12-settings .f12-tabs-trigger,
  .f12-settings .f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger {
    width: 100%;
    justify-content: flex-start;
    min-height: 34px;
    padding: 6px 10px;
  }
  .f12-settings .f12-tabs-trigger + .f12-tabs-trigger,
  .f12-settings .f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger + .f12-tabs-trigger {
    border-inline-start: 0;
    border-top: 1.5px solid var(--f-rule);
  }
}

@container (max-width: 1180px) {
  .f12-console .f12-int-row {
    grid-template-columns: minmax(0, 1fr) minmax(0, auto);
    grid-template-areas:
      "name val"
      "bar bar";
    gap: 6px 12px;
  }
  .f12-console .f12-int-name {
    grid-area: name;
    white-space: normal;
  }
  .f12-console .f12-int-val {
    grid-area: val;
    white-space: normal;
    text-align: end;
  }
  .f12-console .f12-int-bar {
    grid-area: bar;
  }
}

@container (max-width: 1080px) {
  .f12-console-overview-scene.f12-scene.f12-scene-equal,
  .f12-console-kv-list.f12-console-kpi-foot {
    grid-template-columns: minmax(0, 1fr);
  }
}

@container (max-width: 900px) {
  .f12-settings .f12-tabs-list {
    flex-direction: column;
    width: 100%;
  }
  .f12-settings .f12-tabs-trigger,
  .f12-settings .f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger {
    width: 100%;
    justify-content: flex-start;
    min-height: 34px;
    padding: 6px 10px;
  }
  .f12-settings .f12-tabs-trigger + .f12-tabs-trigger,
  .f12-settings .f12-tabs-list.f12-tabs-list-compact .f12-tabs-trigger + .f12-tabs-trigger {
    border-inline-start: 0;
    border-top: 1.5px solid var(--f-rule);
  }
}

/* ===================================================================== ExposureScrubber
   An exposure sheet (X-sheet) for discrete histories. The root is a size container; layout comes
   from container width, never the viewport. Rows are CSS-grid boxes (not table-row boxes) so
   `content-visibility: auto` can skip off-screen rows; the component restores explicit ARIA table
   roles. Gutters: 12 / 20 / 32 only. Marker yellow: only as a background under --f-marker-ink. */
.f12-xs {
  container-type: inline-size;
  position: relative;
  min-width: 0;
  color: var(--f-ink);
  font-family: var(--font-f-body);
}
.f12-xs *,
.f12-xs *::before,
.f12-xs *::after {
  box-sizing: border-box;
}
.f12-xs-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas:
    "transport"
    "panel"
    "sheet";
  gap: var(--f-gutter-scene);
  align-items: start;
}
.f12-xs-transport {
  grid-area: transport;
  min-width: 0;
  margin: 0;
  padding: 12px;
  border: var(--f-stroke) solid var(--f-rule);
  background: var(--f-panel);
  display: grid;
  gap: var(--f-gutter-pair);
}
.f12-xs-quiet .f12-xs-transport {
  border-width: 1px;
}
.f12-xs-tr-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--f-gutter-pair);
  min-width: 0;
}
.f12-xs-tbtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 32px;
  min-width: 32px;
  padding: 4px 10px;
  border: 2px solid var(--f-rule);
  background: var(--f-panel);
  color: var(--f-ink);
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
}
.f12-xs-tbtn:disabled,
.f12-xs-tbtn[aria-disabled="true"] {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
}
.f12-xs-play[aria-pressed="true"] {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-xs-play-glyph {
  display: inline-block;
  min-width: 2ch;
}
.f12-xs-range {
  flex: 1 1 160px;
  min-width: 120px;
  height: 32px;
  margin: 0;
  accent-color: var(--f-ink);
  cursor: pointer;
  touch-action: none;
}
.f12-xs-range:disabled {
  cursor: not-allowed;
}
.f12-xs-one,
.f12-xs-count {
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.f12-xs-rate .f12-rng-btn {
  min-width: 44px;
  min-height: 32px;
  padding: 4px 8px;
}
.f12-xs-rate .f12-rng-n,
.f12-xs-timing .f12-rng-n {
  font-size: 13px;
}
.f12-xs-timing .f12-tempo-opt {
  min-height: 32px;
  min-width: 52px;
}
.f12-xs-timing .f12-tempo-opt[data-unavailable] {
  cursor: not-allowed;
  background-image: repeating-linear-gradient(-45deg, var(--f-grid) 0, var(--f-grid) 2px, transparent 2px, transparent 6px);
  text-decoration: line-through;
}
.f12-xs-note {
  margin: 0;
  font-family: var(--font-f-mono);
  font-size: 12px;
  line-height: 1.4;
}

/* ---- the sheet */
.f12-xs-disc {
  grid-area: sheet;
  min-width: 0;
  border: var(--f-stroke) solid var(--f-rule);
  background: var(--f-panel);
}
.f12-xs-quiet .f12-xs-disc {
  border-width: 1px;
}
.f12-xs-sum {
  min-height: 32px;
  padding: 6px 12px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
}
.f12-xs-disc[open] > .f12-xs-sum {
  border-bottom: 1px solid var(--f-rule);
}
.f12-xs-scroll {
  max-height: min(70vh, 640px);
  /* Keeps a focused row clear of the sticky header (WCAG 2.4.11). */
  scroll-padding-top: 56px;
  overflow: auto;
  overscroll-behavior: contain;
}
.f12-xs-sheet {
  --xs-cols: 6.25rem minmax(0, 1fr) 7.5rem 8.5rem;
  display: grid;
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 13px;
}
.f12-xs-sheet > thead,
.f12-xs-sheet > tbody {
  display: grid;
}
.f12-xs-cap {
  display: block;
  padding: 8px 12px;
  text-align: start;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.f12-xs-sheet > thead {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--f-panel);
  border-bottom: 2px solid var(--f-rule);
}
.f12-xs-hrow,
.f12-xs-row {
  display: grid;
  grid-template-columns: var(--xs-cols);
  align-items: stretch;
}
.f12-xs-hrow > th {
  padding: 6px 8px;
  text-align: start;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
}
.f12-xs-sc {
  display: block;
  font-weight: 400;
  letter-spacing: 0.02em;
  text-transform: none;
}
.f12-xs-row {
  content-visibility: auto;
  contain-intrinsic-size: auto 56px;
  border-bottom: 1px solid var(--f-grid);
  scroll-margin-block: 48px;
}
/* Row cells are styled by position (1 FRAME · 2 ACTION · 3 TIMING · 4 MARK) to keep rows lean. */
.f12-xs-compact .f12-xs-row {
  contain-intrinsic-size: auto 40px;
}
.f12-xs-row > td {
  min-width: 0;
  padding: 4px 8px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.f12-xs-compact .f12-xs-row > td {
  padding: 2px 6px;
}
.f12-xs-f {
  font-family: var(--font-f-mono);
  font-variant-numeric: tabular-nums;
  border-right: 2px solid var(--f-rule);
  cursor: ns-resize;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}
.f12-xs-fn {
  font-weight: 700;
  font-size: 12px;
}
.f12-xs-f > span + span {
  font-size: 10px;
  color: var(--f-ink-2);
}
.f12-xs-row > :nth-child(2) {
  overflow: hidden;
}
.f12-xs-btn {
  display: block;
  width: 100%;
  min-height: 24px;
  padding: 2px 0;
  border: 0;
  background: none;
  color: var(--f-ink);
  text-align: start;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
}
.f12-xs-k {
  display: inline-block;
  align-self: start;
  padding: 0 4px;
  border: 1px solid var(--f-rule);
  font-family: var(--font-f-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.f12-xs-d {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-size: 12px;
  color: var(--f-ink-2);
}
.f12-xs-compact .f12-xs-d {
  -webkit-line-clamp: 1;
}
.f12-xs-row > :nth-child(3) {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
/* TIMING: hold ticks (even) or a log-scaled screentone bar of the real gap (elapsed, flipbook). */
.f12-xs-row > :nth-child(3):not(:empty)::before {
  content: "";
  display: block;
  height: 10px;
  width: var(--xs-w, 4%);
  border-right: 2px solid var(--f-rule);
  background-image: radial-gradient(circle, var(--f-tone) 1.1px, transparent 1.4px);
  background-size: 5px 5px;
}
.f12-xs[data-timing="even"] .f12-xs-row > :nth-child(3)::before {
  width: calc(var(--xs-h, 1) * 6px);
  border-right: 0;
  border-left: 2px solid var(--f-rule);
  background-image: repeating-linear-gradient(90deg, transparent 0, transparent 4px, var(--f-rule) 4px, var(--f-rule) 6px);
  background-size: auto;
}
.f12-xs-row > :nth-child(4) {
  font-family: var(--font-f-mono);
  font-size: 11px;
  align-items: flex-start;
}
.f12-xs-st,
.f12-xs-mk,
.f12-xs-from {
  white-space: nowrap;
}
/* The glyph is generated content with empty alt text: seen, not read twice. */
.f12-xs-st::before {
  content: "[+] ";
  content: "[+] " / "";
}
.f12-xs-st[data-s="warn"]::before {
  content: "[!] ";
  content: "[!] " / "";
}
.f12-xs-st[data-s="error"]::before {
  content: "[×] ";
  content: "[×] " / "";
}
.f12-xs-st[data-s="pending"]::before {
  content: "[~] ";
  content: "[~] " / "";
}
.f12-xs-st[data-s="error"] {
  font-weight: 700;
  text-decoration: underline;
  text-decoration-thickness: 2px;
}
.f12-xs-st[data-s="warn"] {
  font-weight: 700;
}
.f12-xs-mk {
  padding: 0 4px;
  border: 1px solid var(--f-rule);
  font-weight: 700;
}
.f12-xs-mk-primary {
  background: var(--f-marker);
  color: var(--f-marker-ink);
  border: 2px solid var(--f-rule);
}

/* current row: outline + inked frame number + screentone exposure strip (survives forced colors) */
.f12-xs-row[aria-current="step"] {
  outline: 2px solid var(--f-rule);
  outline-offset: -2px;
  position: relative;
  z-index: 1;
}
.f12-xs-row[aria-current="step"] > .f12-xs-f {
  background: var(--f-ink);
  color: var(--f-panel);
  border-right-width: 4px;
}
.f12-xs-row[aria-current="step"] > .f12-xs-f > span + span {
  color: var(--f-panel);
}
.f12-xs-row[aria-current="step"] > :nth-child(2) {
  background-image: radial-gradient(circle, var(--f-grid) 1.1px, transparent 1.4px);
  background-size: 5px 5px;
}
.f12-xs-row[aria-current="step"] .f12-xs-btn {
  font-weight: 700;
}
.f12-xs-quiet .f12-xs-row[aria-current="step"] > :nth-child(2) {
  background-image: none;
}
.f12-xs-btn:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: -3px;
}

/* ---- the panel */
.f12-xs-panel {
  grid-area: panel;
  min-width: 0;
}
.f12-xs-cut {
  max-width: calc(100% - 32px);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.f12-xs-body,
.f12-xs-head,
.f12-xs-links {
  display: grid;
  gap: var(--f-gutter-pair);
  min-width: 0;
}
.f12-xs-content[data-swap] {
  animation: var(--f12-enter-animation, none);
}
.f12-xs-head > p {
  margin: 0;
}
.f12-xs-title:focus {
  outline: none;
}
.f12-xs-title:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-xs-pos {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--f-gutter-pair);
  font-family: var(--font-f-mono);
  font-variant-numeric: tabular-nums;
}
.f12-xs-pnum {
  font-family: var(--font-f-display);
  font-size: 22px;
  line-height: 1;
}
.f12-xs-pel {
  font-size: 12px;
}
.f12-xs-title {
  font-weight: 700;
  font-size: 16px;
  overflow-wrap: anywhere;
}
.f12-xs-pmeta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--f-gutter-pair);
  font-family: var(--font-f-mono);
  font-size: 12px;
}
.f12-xs-content {
  min-width: 0;
  overflow-wrap: anywhere;
}
.f12-xs-links-h {
  margin: 0;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.f12-xs-links-l {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: var(--f-gutter-pair);
}
.f12-xs-cause,
.f12-xs-back {
  justify-content: flex-start;
  text-align: start;
  text-transform: none;
  letter-spacing: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
}
.f12-xs-back {
  justify-self: start;
}
.f12-xs-slate {
  min-height: 120px;
  display: grid;
  align-content: center;
  justify-items: start;
  gap: var(--f-gutter-pair);
  padding: 12px;
  border: 2px dashed var(--f-rule);
}
.f12-xs-slate > p {
  margin: 0;
}
.f12-xs-slate-t {
  font-family: var(--font-f-display);
