/* ---- motion: transitions only (row highlight and panel swap), resolved through the tempo */
.f12-m-stepped .f12-xs-row > .f12-xs-f {
  transition: background-color 167ms steps(2, end), color 167ms steps(2, end);
}
.f12-m-smooth .f12-xs-row > .f12-xs-f {
  transition: background-color 160ms ease-out, color 160ms ease-out;
}
.f12-m-cut .f12-xs-row > .f12-xs-f,
.f12-xs[data-flipping] .f12-xs-row > .f12-xs-f {
  transition: none;
}
