    animation: none;
  }
}

/* ---- container layout: side by side from 640px of container width */
@container (min-width: 640px) {
  .f12-xs-grid {
    grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
    grid-template-areas:
      "transport transport"
      "sheet panel";
  }
