    display: none;
  }
  .f12-xs-disc {
    border-width: var(--f-stroke);
  }
}
@container (max-width: 420px) {
  .f12-xs-sheet {
    --xs-cols: 5.5rem minmax(0, 1fr) 4.5rem;
  }
  /* Visually hidden, still in the accessibility tree: the MARK cells wrap under ACTION. */
  .f12-xs-sheet .f12-xs-hrow > th:nth-child(4) {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }
  .f12-xs-row > :nth-child(4) {
    grid-column: 2 / -1;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: flex-start;
    gap: var(--f-gutter-pair);
    padding-top: 0;
  }
  .f12-xs-row > :nth-child(4):empty {
    display: none;
  }
}

/* ---- forced colors: current row, status, marker and focus stay distinguishable */
@media (forced-colors: active) {
