/* ===================================================================== Motion Grammar
   smooth  = continuous easing
   stepped = poses held on twos: 12 drawings/s, each pose 83.33ms
   cut     = instant, editorial hard cut */
.f12-m-smooth {
  --f12-rng-ind-transition: transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1), width 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
  --f12-switch-thumb-transition: inset-inline-start 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
  --f12-skeleton-animation: f12SkeletonSmooth 1400ms ease-in-out infinite;
  --f12-enter-animation: f12EnterSmooth 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
  --f12-pop-animation: f12PopSmooth 240ms cubic-bezier(0.2, 0.9, 0.3, 1.25);
  --f12-burst-animation: f12BurstSmooth 320ms ease-out;
}
.f12-m-stepped {
  --f12-rng-ind-transition: transform 250ms steps(3, end), width 250ms steps(3, end);
  --f12-switch-thumb-transition: inset-inline-start 250ms steps(3, end);
  --f12-skeleton-animation: f12SkeletonStep 333ms steps(4, end) infinite;
  --f12-enter-animation: f12EnterStep 250ms step-end;
  --f12-pop-animation: f12PopStep 333ms step-end;
  --f12-burst-animation: f12BurstStep 250ms step-end;
}
.f12-m-cut {
  --f12-rng-ind-transition: none;
  --f12-switch-thumb-transition: none;
  --f12-skeleton-animation: none;
  --f12-enter-animation: none;
  --f12-pop-animation: none;
  --f12-burst-animation: none;
}
/* First paint only: a stored `still` tempo (set on <html> by the first-paint script before React
   hydrates) never shows motion, even before the TempoProvider resolves it in JS. Safety
   direction only: it can turn motion off, never on. */
html[data-f12-tempo="still"],
html[data-f12-tempo="still"] .f12-m-stepped,
html[data-f12-tempo="still"] .f12-m-smooth {
  --f12-rng-ind-transition: none;
  --f12-switch-thumb-transition: none;
  --f12-skeleton-animation: none;
  --f12-enter-animation: none;
  --f12-pop-animation: none;
  --f12-burst-animation: none;
}
.f12-rng-ind {
  transition: var(--f12-rng-ind-transition, none);
}
.f12-switch-thumb {
  transition: var(--f12-switch-thumb-transition, none);
}
.f12-skeleton-animated {
  animation: var(--f12-skeleton-animation, f12SkeletonStep 333ms steps(4, end) infinite);
}
@keyframes f12SkeletonSmooth {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.55;
  }
}
@keyframes f12SkeletonStep {
  0% {
    background-position: 0 0;
    opacity: 1;
  }
  50% {
    background-position: 6px 3px;
    opacity: 0.68;
  }
  100% {
    background-position: 12px 6px;
    opacity: 1;
  }
}

.f12-enter {
  animation: var(--f12-enter-animation, none);
}
@keyframes f12EnterSmooth {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes f12EnterStep {
  0% {
    opacity: 0.35;
    transform: translateY(10px);
  }
  33% {
    opacity: 0.8;
    transform: translateY(4px);
  }
  66% {
    opacity: 1;
    transform: translateY(1px);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}

.f12-pop {
  animation: var(--f12-pop-animation, none);
}
@keyframes f12PopSmooth {
  from {
    opacity: 0;
    transform: scale(0.85);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes f12PopStep {
  0% {
    transform: scale(0.5);
  }
  25% {
    transform: scale(1.22);
  }
  50% {
    transform: scale(0.94);
  }
  75% {
    transform: scale(1);
  }
  100% {
    transform: none;
  }
}
.f12-pop .f12-burst {
  animation: var(--f12-burst-animation, none);
}
@keyframes f12BurstStep {
  0% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(0.85);
  }
  33% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1.08);
  }
  66%,
  100% {
    opacity: 0;
  }
}
@keyframes f12BurstSmooth {
  from {
    opacity: 0.9;
    transform: translate(-50%, -50%) scale(0.85);
  }
  to {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.15);
  }
}

@media (prefers-reduced-motion: reduce) {
  :root,
  .f12-m-smooth,
  .f12-m-stepped,
  .f12-m-cut {
    --f12-rng-ind-transition: none;
    --f12-switch-thumb-transition: none;
    --f12-skeleton-animation: none;
    --f12-enter-animation: none;
    --f12-pop-animation: none;
    --f12-burst-animation: none;
  }
  .f12-dash *,
  .f12-dash *::before,
  .f12-dash *::after,
  .f12-sheet *,
  .f12-sheet *::before,
  .f12-sheet *::after,
  .f12-toast-viewport *,
  .f12-toast,
  .f12-rng-ind,
  .f12-switch-thumb,
  .f12-enter,
  .f12-pop,
  .f12-pop .f12-burst,
  .f12-skeleton-animated {
    animation: none !important;
    transition: none !important;
  }
}

/* ===================================================================== Ink (line art on twos)
   InkStroke, InkReveal and InkSequence draw SVG line art with CSS alone: no requestAnimationFrame,
   no timers. Every stroke is a <path pathLength="1">; drawing animates stroke-dashoffset 1 → 0
   with steps(poses, jump-start) over poses × --f-pose, so each pose is held 83.33ms. At rest no
   dash properties apply, so a finished stroke is pixel-identical to a plain path (no dash seam at
   a closed path's start corner). Two identical keyframe names (A/B) let a replay restart. */
.f12-ink {
  fill: none;
  stroke: currentColor;
  color: var(--f-ink);
  stroke-width: var(--f-stroke-detail);
  stroke-linejoin: miter;
  stroke-linecap: butt;
}
.f12-ink-frame {
  color: var(--f-rule);
  stroke-width: var(--f-stroke);
}
.f12-ink-detail {
  color: var(--f-ink);
  stroke-width: var(--f-stroke-detail);
}
.f12-ink-pencil {
  color: var(--f-ink-2);
  stroke-width: var(--f-stroke-pencil);
  stroke-linecap: round;
  stroke-linejoin: round;
}
.f12-ink-seq {
  min-width: 0;
}
.f12-ink[data-ink],
.f12-ink-seq[data-ink] .f12-ink,
.f12-ink-seq[data-ink] .f12-ink-wipe,
.f12-ink-seq[data-ink] .f12-ink-land {
  animation-duration: calc(var(--f12-ink-poses, 6) * var(--f-pose));
  animation-delay: calc((var(--f12-ink-beat, 0) + var(--f12-ink-at, 0)) * var(--f-pose));
  animation-timing-function: steps(var(--f12-ink-poses, 6), jump-start);
  animation-fill-mode: backwards;
  animation-iteration-count: 1;
}
.f12-ink-seq[data-ink] .f12-ink-land {
  animation-duration: var(--f-pose);
  animation-timing-function: steps(1, jump-start);
}
.f12-ink.f12-m-smooth[data-ink],
.f12-ink-seq.f12-m-smooth[data-ink] .f12-ink,
.f12-ink-seq.f12-m-smooth[data-ink] .f12-ink-wipe {
  animation-timing-function: linear;
}
.f12-ink[data-ink="a"],
.f12-ink-seq[data-ink="a"] .f12-ink {
  animation-name: f12InkDrawA;
}
.f12-ink[data-ink="b"],
.f12-ink-seq[data-ink="b"] .f12-ink {
  animation-name: f12InkDrawB;
}
.f12-ink-seq[data-ink="a"] .f12-ink-wipe {
  animation-name: f12InkWipeA;
}
.f12-ink-seq[data-ink="b"] .f12-ink-wipe {
  animation-name: f12InkWipeB;
}
.f12-ink-seq[data-ink="a"] .f12-ink-land {
  animation-name: f12InkLandA;
}
.f12-ink-seq[data-ink="b"] .f12-ink-land {
  animation-name: f12InkLandB;
}
/* The sequence's clock: one no-op animation lasting every beat's poses. Its animationend is the
   last beat's end (InkSequence onEnd). It is never removed by print or forced colors. */
.f12-ink-seq[data-ink="a"] {
  animation: f12InkClockA calc(var(--f12-ink-total, 1) * var(--f-pose)) linear;
}
.f12-ink-seq[data-ink="b"] {
  animation: f12InkClockB calc(var(--f12-ink-total, 1) * var(--f-pose)) linear;
}
/* Scroll driver: poses follow the scroll position, quantized by steps() to each stroke's poses.
   Its keyframes have their own names (f12InkScrub*), so Play always starts fresh time-based
   animations instead of re-timing the scroll-linked ones.
   Native scroll only: no scroll listeners, no scroll-snap. Set --f12-ink-timeline on the sequence
   (or an ancestor) to a named view timeline; the default is each element's own view(). */
@supports (animation-timeline: view()) {
  .f12-ink-seq[data-ink-scroll] .f12-ink,
  .f12-ink-seq[data-ink-scroll] .f12-ink-wipe,
  .f12-ink-seq[data-ink-scroll] .f12-ink-land {
    animation-name: f12InkScrubDraw;
    animation-duration: auto;
    animation-delay: 0s;
    animation-fill-mode: both;
    animation-iteration-count: 1;
    animation-timing-function: steps(var(--f12-ink-poses, 6), jump-start);
    animation-timeline: var(--f12-ink-timeline, view());
    animation-range-start: contain
      calc((var(--f12-ink-beat, 0) + var(--f12-ink-at, 0)) / var(--f12-ink-total, 1) * 100%);
    animation-range-end: contain
      calc(
        (var(--f12-ink-beat, 0) + var(--f12-ink-at, 0) + var(--f12-ink-poses, 6)) /
          var(--f12-ink-total, 1) * 100%
      );
  }
  .f12-ink-seq[data-ink-scroll] .f12-ink-wipe {
    animation-name: f12InkScrubWipe;
  }
  .f12-ink-seq[data-ink-scroll] .f12-ink-land {
    animation-name: f12InkScrubLand;
    animation-timing-function: steps(1, jump-start);
    animation-range-end: contain
      calc((var(--f12-ink-beat, 0) + var(--f12-ink-at, 0) + 1) / var(--f12-ink-total, 1) * 100%);
  }
  .f12-ink-seq.f12-m-smooth[data-ink-scroll] .f12-ink,
  .f12-ink-seq.f12-m-smooth[data-ink-scroll] .f12-ink-wipe {
    animation-timing-function: linear;
  }
}
/* InkReveal: frame inks (6 poses), the cut number lands (1 pose), the content appears in one cut.
   Only the measured polygon (pathLength="1") is drawn; the SSR viewBox polygon carries
   vector-effect and is never dashed. */
.f12-ink-reveal {
  display: contents;
}
.f12-ink-reveal[data-ink] .f12-panel-frame polygon:not([vector-effect]) {
  animation-duration: calc(6 * var(--f-pose));
  animation-timing-function: steps(6, jump-start);
  animation-fill-mode: backwards;
}
.f12-ink-reveal.f12-m-smooth[data-ink] .f12-panel-frame polygon:not([vector-effect]) {
  animation-timing-function: linear;
}
.f12-ink-reveal[data-ink="a"] .f12-panel-frame polygon:not([vector-effect]) {
  animation-name: f12InkFrameA;
}
.f12-ink-reveal[data-ink="b"] .f12-panel-frame polygon:not([vector-effect]) {
  animation-name: f12InkFrameB;
}
.f12-ink-reveal[data-ink="a"][data-ink-dir="rtl"] .f12-panel-frame polygon:not([vector-effect]) {
  animation-name: f12InkFrameRtlA;
}
.f12-ink-reveal[data-ink="b"][data-ink-dir="rtl"] .f12-panel-frame polygon:not([vector-effect]) {
  animation-name: f12InkFrameRtlB;
}
.f12-ink-reveal[data-ink] .f12-cut,
.f12-ink-reveal[data-ink] .f12-panel-body {
  animation-duration: var(--f-pose);
  animation-delay: calc(6 * var(--f-pose));
  animation-timing-function: steps(1, jump-start);
  animation-fill-mode: backwards;
}
.f12-ink-reveal[data-ink] .f12-panel-body {
  animation-delay: calc(7 * var(--f-pose));
}
.f12-ink-reveal[data-ink="a"] .f12-cut,
.f12-ink-reveal[data-ink="a"] .f12-panel-body {
  animation-name: f12InkLandA;
}
.f12-ink-reveal[data-ink="b"] .f12-cut,
.f12-ink-reveal[data-ink="b"] .f12-panel-body {
  animation-name: f12InkLandB;
}
@keyframes f12InkDrawA {
  0% { stroke-dasharray: 1 1; stroke-dashoffset: 1; }
  99.99% { stroke-dasharray: 1 1; }
  100% { stroke-dasharray: none; stroke-dashoffset: 0; }
}
@keyframes f12InkDrawB {
  0% { stroke-dasharray: 1 1; stroke-dashoffset: 1; }
  99.99% { stroke-dasharray: 1 1; }
  100% { stroke-dasharray: none; stroke-dashoffset: 0; }
}
@keyframes f12InkFrameA {
  0% { stroke-dasharray: 0 1; }
  100% { stroke-dasharray: 1 0; }
}
@keyframes f12InkFrameB {
  0% { stroke-dasharray: 0 1; }
  100% { stroke-dasharray: 1 0; }
}
/* RTL: start at the top-right corner (at position a along the frame) and run right to left
   along the top edge: the dash offset runs from -a (--f12-ink-from) to 1 - a (--f12-ink-to). */
@keyframes f12InkFrameRtlA {
  0% { stroke-dasharray: 0 1; stroke-dashoffset: var(--f12-ink-from, 0); }
