/* ===================================================================== CutMorph (view transitions)
   State changes as film edits. Every rule needs BOTH a transition-scoped mode key on the
   transition root (`f12-vt-stepped` / `f12-vt-smooth`, set by useCutMorph or withCutMorphMode on
   <html>, or on the scope element of an element-scoped transition) AND a CutMorph
   view-transition-class (`f12-match` / `f12-cut`), so other libraries' and the app's own view
   transitions are never restyled. Timings are the motion grammar's: stepped 250ms steps(3, end),
   smooth 260ms cubic-bezier(0.2, 0.8, 0.2, 1). Old/new images never crossfade: one hard swap at
   the geometric midpoint (stepped: the second pose boundary, 166.67ms; smooth: 33.8ms, where the
   curve crosses 0.5). See docs/architecture/cut-morph.md for the per-engine spike. */
html:is(.f12-vt-stepped, .f12-vt-smooth) {
  view-transition-name: none;
}
:is(.f12-vt-stepped, .f12-vt-smooth)::view-transition {
  pointer-events: none;
}
:is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-group(root) {
  animation: none;
}
.f12-vt-stepped::view-transition-group(*.f12-match) {
  animation-duration: 250ms;
  animation-timing-function: steps(3, end);
}
.f12-vt-smooth::view-transition-group(*.f12-match) {
  animation-duration: 260ms;
  animation-timing-function: cubic-bezier(0.2, 0.8, 0.2, 1);
}
:is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-image-pair(*.f12-match) {
  isolation: auto;
}
:is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-old(*.f12-match),
:is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-new(*.f12-match) {
  mix-blend-mode: normal;
  animation-timing-function: steps(1, end);
  animation-fill-mode: both;
}
:is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-old(*.f12-match) {
  animation-name: f12VtOut;
}
:is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-new(*.f12-match) {
  animation-name: f12VtIn;
}
.f12-vt-stepped::view-transition-old(*.f12-match),
.f12-vt-stepped::view-transition-new(*.f12-match) {
  animation-duration: 166.667ms;
}
.f12-vt-smooth::view-transition-old(*.f12-match),
.f12-vt-smooth::view-transition-new(*.f12-match) {
  animation-duration: 33.8ms;
}
:is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-group(*.f12-cut),
:is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-new(*.f12-cut) {
  animation: none;
}
:is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-old(*.f12-cut) {
  animation: none;
  opacity: 0;
}
@keyframes f12VtOut {
  from { opacity: 1; }
  to { opacity: 0; }
}
@keyframes f12VtIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
/* Hard safety, independent of JS: reduced motion never animates a CutMorph view transition. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*.f12-match),
  ::view-transition-new(*.f12-match),
  ::view-transition-group(*.f12-cut),
  ::view-transition-new(*.f12-cut),
  :is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-group(root),
  :is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-old(root),
  :is(.f12-vt-stepped, .f12-vt-smooth)::view-transition-new(root) {
    animation: none !important;
  }
  ::view-transition-old(*.f12-match),
  ::view-transition-old(*.f12-cut) {
    animation: none !important;
    opacity: 0;
  }
}

