'use client';

import * as React from 'react';
import { useReducedMotion, useResolvedMotion } from '@/hooks/use-tempo';

export type MotionMode = 'stepped' | 'smooth' | 'cut';

export const FRAME_MS = 1000 / 12; // animating "on twos": 12 drawings per second (83.33ms per pose)

const easeOut = (t: number): number => 1 - Math.pow(1 - t, 3);

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;

export function useSize(ref: { readonly current: HTMLElement | null }): { w: number; h: number } {
  const [size, setSize] = React.useState<{ w: number; h: number }>({ w: 0, h: 0 });

  useIsoLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    // Layout size (offsetWidth/Height), not the transformed box, so scaled previews draw correctly.
    const measure = () => {
      const w = el.offsetWidth;
      const h = el.offsetHeight;
      setSize((s) => (s.w === w && s.h === h ? s : { w, h }));
    };
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [ref]);

  return size;
}

// Re-exported so existing `import { useReducedMotion } from '@/hooks/use-on-twos'` keeps working.
export { useReducedMotion };

/**
 * Progress 0..1 that replays whenever `key` changes.
 *
 * Stepped mode samples the cubic-out easing curve at 12 poses per second
 * (`FRAME_MS = 1000 / 12 = 83.33ms` per pose), like an animation exposure sheet
 * ("on twos"). Pose 1 (`k = 1`, `t = 1 / frames`) is displayed immediately at
 * `elapsed = 0` (`Math.floor(el / FRAME_MS) + 1`) so the element visibly steps
 * on the exact interaction frame rather than sitting at 0 for 83.33ms, and each
 * subsequent pose is held for a full 83.33ms interval until `frames` poses complete.
 *
 * Only changes to `key` trigger a new tween; changing `duration` or `motion`
 * alone keeps the current resting state. `motion` is resolved against the nearest
 * TempoProvider and the OS (`resolveMotion` in use-tempo.ts): `prefers-reduced-motion: reduce`
 * and a `still` tempo always cut; a change to `'cut'` mid-tween settles immediately.
 */
export function useOnTwos(
  key: unknown,
  duration = 600,
  motion: MotionMode = 'stepped',
): number {
  const effectiveMotion: MotionMode = useResolvedMotion(motion);
  const [p, setP] = React.useState<number>(1);
  const prevKeyRef = React.useRef<unknown>(key);
  const frames = Math.max(2, Math.round(duration / FRAME_MS));
  const initialP =
    effectiveMotion === 'cut' ? 1 : effectiveMotion === 'stepped' ? easeOut(1 / frames) : 0;

  useIsoLayoutEffect(() => {
    if (effectiveMotion === 'cut') {
      prevKeyRef.current = key;
      setP(1);
      return;
    }
    if (Object.is(prevKeyRef.current, key)) {
      setP(1);
      return;
    }
    prevKeyRef.current = key;
    const start = performance.now();
    const totalFrames = Math.max(2, Math.round(duration / FRAME_MS));
    let raf = 0;
    let last = -1;
    const tick = (now: number) => {
      const el = now - start;
      let t: number;
      if (effectiveMotion === 'stepped') {
        const k = Math.min(totalFrames, Math.floor(el / FRAME_MS) + 1);
        t = k / totalFrames;
      } else {
        t = Math.min(1, el / duration);
      }
      const v = easeOut(t);
      if (v !== last) {
        last = v;
        setP(v);
      }
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    setP(effectiveMotion === 'stepped' ? easeOut(1 / totalFrames) : 0);
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [key, duration, effectiveMotion]);

  const isNewKey = !Object.is(prevKeyRef.current, key);
  return isNewKey ? initialP : p;
}

export const useTween = useOnTwos;

export function useCountUp(
  value: number,
  motion: MotionMode = 'stepped',
  duration = 600,
): number {
  const prev = React.useRef<number>(value);
  const from = React.useRef<number>(value);
  const displayedRef = React.useRef<number>(value);
  if (!Object.is(prev.current, value)) {
    from.current = displayedRef.current;
    prev.current = value;
  }
  const p = useOnTwos(value, duration, motion);
  const current = from.current + (value - from.current) * p;
  displayedRef.current = current;
  return current;
}

/**
 * Becomes true after the first change of `key`, so entrance animations
 * never run on first paint (the page is complete at rest).
 */
export function useChanged(key: unknown): boolean {
  const first = React.useRef<unknown>(key);
  const [changed, setChanged] = React.useState<boolean>(false);
  React.useEffect(() => {
    if (key !== first.current) setChanged(true);
  }, [key]);
  return changed;
}

'use client';

import * as React from 'react';

// Same union as `MotionMode` in use-on-twos.ts. Declared locally (not imported) so this module has
// no dependencies: use-on-twos.ts imports from here, never the other way round.
type MotionMode = 'stepped' | 'smooth' | 'cut';

/**
 * The viewer's animation tempo.
 *
 * | Tempo   | Label | Meaning                                                              |
 * |---------|-------|----------------------------------------------------------------------|
 * | `auto`  | AUTO  | each component's own intended motion (default)                        |
 * | `twos`  | 12    | on twos: held poses, 12 per second                                    |
 * | `ones`  | 60    | smooth, continuous motion (follows the display's refresh rate)        |
 * | `still` | 0     | no non-essential motion                                               |
 */
export type Tempo = 'auto' | 'twos' | 'ones' | 'still';

export const TEMPOS: readonly Tempo[] = ['auto', 'twos', 'ones', 'still'];

export function isTempo(value: unknown): value is Tempo {
  return value === 'auto' || value === 'twos' || value === 'ones' || value === 'still';
}

/** Any invalid runtime value (a stored `"fast"`, `null`, a number) is treated as `auto`. */
export function normalizeTempo(value: unknown): Tempo {
  return isTempo(value) ? value : 'auto';
}

export interface ResolveMotionInput {
  /** The component's `motion` prop, otherwise its own default (`Metric` quiet → `'cut'`). Undefined means `'stepped'`. */
  base?: MotionMode;
  /** The nearest provider's tempo. Invalid values are treated as `auto`. */
  tempo?: Tempo;
  /** True when any provider above the nearest one is `still`. */
  ancestorStill?: boolean;
  /** The OS `prefers-reduced-motion: reduce` preference. */
  reduced?: boolean;
}

/**
 * Resolves the motion a component actually plays. Rules, in order:
 *   1. OS reduced motion → `'cut'`.
 *   2. `still` here or in any ancestor → `'cut'`.
 *   3. `base === 'cut'` → `'cut'`: tempo never turns motion on where a component, a variant or an
 *      explicit prop says none.
 *   4. `twos` → `'stepped'`; `ones` → `'smooth'`.
 *   5. `auto` → `base`.
 * Direct manipulation (pointer tracking, drag, scroll, typing, focus movement) never goes through
 * this: it is never stepped or delayed, at any tempo.
 */
export function resolveMotion({
  base,
  tempo,
  ancestorStill = false,
  reduced = false,
}: ResolveMotionInput): MotionMode {
  if (reduced) return 'cut';
  const t = normalizeTempo(tempo);
  if (t === 'still' || ancestorStill) return 'cut';
  const b: MotionMode = base === undefined ? 'stepped' : base;
  if (b === 'cut') return 'cut';
  if (t === 'twos') return 'stepped';
  if (t === 'ones') return 'smooth';
  return b;
}

export interface TempoContextValue {
  /** The nearest provider's tempo (`auto` without a provider). */
  tempo: Tempo;
  /** Sets the nearest provider's tempo. A no-op without a provider. */
  setTempo: (tempo: Tempo) => void;
  /** True when a provider above the nearest one is `still` (it cannot be undone below). */
  ancestorStill: boolean;
  /** False when no TempoProvider is above this point. */
  inProvider: boolean;
}

const NO_PROVIDER: TempoContextValue = {
  tempo: 'auto',
  setTempo: () => {},
  ancestorStill: false,
  inProvider: false,
};

export const TempoContext = React.createContext<TempoContextValue>(NO_PROVIDER);
TempoContext.displayName = 'TempoContext';

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

function subscribeReducedMotion(onStoreChange: () => void): () => void {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    return () => {};
  }
  const q = window.matchMedia(REDUCED_MOTION_QUERY);
  if (q.addEventListener) {
    q.addEventListener('change', onStoreChange);
    return () => q.removeEventListener('change', onStoreChange);
  }
  q.addListener(onStoreChange);
  return () => q.removeListener(onStoreChange);
}

function getReducedMotionSnapshot(): boolean {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    return false;
  }
  return window.matchMedia(REDUCED_MOTION_QUERY).matches;
}

function getReducedMotionServerSnapshot(): boolean {
  return false;
}

/** The OS `prefers-reduced-motion: reduce` preference. Without `matchMedia`, false. */
export function useReducedMotion(): boolean {
  return React.useSyncExternalStore(
    subscribeReducedMotion,
    getReducedMotionSnapshot,
    getReducedMotionServerSnapshot,
  );
}

export interface TempoState extends TempoContextValue {
  /** The OS reduced-motion preference. */
  reduced: boolean;
  /** What actually applies here: `still` when reduced motion or an ancestor forces it. */
  effectiveTempo: Tempo;
}

/** The tempo at this point in the tree, plus what actually applies after the OS and ancestors. */
export function useTempo(): TempoState {
  const ctx = React.useContext(TempoContext);
  const reduced = useReducedMotion();
  return React.useMemo(
    () => ({ ...ctx, reduced, effectiveTempo: reduced || ctx.ancestorStill ? 'still' : ctx.tempo }),
    [ctx, reduced],
  );
}

/** The motion a component with this `base` should play here (see `resolveMotion`). */
export function useResolvedMotion(base?: MotionMode): MotionMode {
  const { tempo, ancestorStill } = React.useContext(TempoContext);
  const reduced = useReducedMotion();
  return resolveMotion({ base, tempo, ancestorStill, reduced });
}

'use client';

import * as React from 'react';
import { FRAME_MS } from '@/hooks/use-on-twos';
import { useTempo } from '@/hooks/use-tempo';

// Bundlers statically replace `process.env.NODE_ENV`. Declared locally so consumers without
// @types/node still type-check this file.
declare const process: { env: { NODE_ENV?: string } };

/**
 * useExposure: the headless navigation and playback engine behind `ExposureScrubber` (and, later,
 * `TraceTimeline`). It owns selection (by id), the playback clock, the data-change rules, the
 * keyboard map, settle detection and announcements. It renders nothing.
 *
 * See docs/architecture/exposure-engine.md.
 */

export type ExposureStatus = 'ok' | 'warn' | 'error' | 'pending';
export type ExposureTiming = 'even' | 'elapsed' | 'flipbook';
export type ExposureRate = 0.5 | 1 | 2 | 4;
export type ExposureValueReason =
  | 'keyboard'
  | 'pointer'
  | 'row'
  | 'marker'
  | 'cause'
  | 'playback'
  | 'data';
export type ExposurePlayingReason =
  | 'user'
  | 'end'
  | 'scrub'
  | 'hidden'
  | 'data'
  | 'tempo'
  | 'rejected';

export interface ExposureFrame {
  /** Unique and stable; identity survives reorders and data changes. */
  id: string;
  /** Short action, e.g. "tool call · write_file". */
  label: string;
  /** ISO 8601. Unparseable → treated as missing. */
  at?: string;
  /** How long the step took, if known (≥ 0, finite). */
  durationMs?: number;
  /** Short tag, e.g. "tool", "approval", "test". */
  kind?: string;
  status?: ExposureStatus;
  /** A moment that matters. */
  marker?: boolean;
  /** Ids of EARLIER frames that the data says led here. Never inferred. */
  causes?: string[];
  /** Exposure weight 1–12 (integer), default 1. */
  hold?: number;
  /** Plain-text summary, used in the table and without JS. */
  detail?: string;
}

/** One frame after the input contract is applied. */
export interface ExposureEntry {
  /** Internal unique key: the id, `id#2`/`id#3` for later duplicates, `#index` for a bad id. */
  key: string;
  index: number;
  /** The frame object exactly as passed in (handed to `renderFrame`). */
  source: ExposureFrame;
  label: string;
  detail?: string;
  kind?: string;
  status?: ExposureStatus;
  marker: boolean;
  /** 1–12. */
  hold: number;
  /** Valid `durationMs`, if any. */
  durationMs?: number;
  /** Parsed `at` (epoch ms), if valid. */
  atMs?: number;
  /** `atMs` relative to the first frame with a valid `at`. */
  elapsedMs?: number;
  /** The held time used by `elapsed` timing: `durationMs`, else the `at` gap to the next frame. */
  gapMs?: number;
  /** Indices of earlier frames this one names in `causes` (only valid, backward links). */
  causes: number[];
}

export interface ExposureNormalized {
  entries: ExposureEntry[];
  /** key → index */
  keyIndex: Map<string, number>;
  /** Distinct, human-readable problems with the input (dev errors). */
  issues: string[];
  /** True when at least one frame has a usable gap for the timing column. */
  hasTiming: boolean;
  /** Largest gap, for the log-scaled timing column (0 without timing data). */
  maxGapMs: number;
}

export const EXPOSURE_RATES: readonly ExposureRate[] = [0.5, 1, 2, 4];
export const EXPOSURE_TIMINGS: readonly ExposureTiming[] = ['even', 'elapsed', 'flipbook'];
/** Supported maximum. Above it a dev error is logged; rendering is unchanged. */
export const EXPOSURE_MAX_FRAMES = 5000;
export const EXPOSURE_DEFAULT_STEP_MS = 1000;
export const EXPOSURE_MIN_STEP_MS = 250;
export const EXPOSURE_ELAPSED_MIN_MS = 250;
export const EXPOSURE_ELAPSED_MAX_MS = 3000;
/** A keyboard scrub settles this long after the last key. */
export const EXPOSURE_SETTLE_MS = 500;
/** At most one announcement per this interval. */
export const EXPOSURE_ANNOUNCE_GAP_MS = 1000;

const STATUSES: readonly ExposureStatus[] = ['ok', 'warn', 'error', 'pending'];
export const EXPOSURE_STATUS_WORDS: Record<ExposureStatus, string> = {
  ok: 'ok',
  warn: 'warning',
  error: 'error',
  pending: 'pending',
};

const isFiniteNumber = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);

/** Applies the input contract. Pure and deterministic: array order is the truth. */
export function normalizeExposureFrames(frames: readonly ExposureFrame[]): ExposureNormalized {
  const issues: string[] = [];
  const list: readonly ExposureFrame[] = Array.isArray(frames) ? frames : [];
  if (!Array.isArray(frames)) issues.push('`frames` must be an array; rendering an empty sheet.');
  if (list.length > EXPOSURE_MAX_FRAMES) {
    issues.push(
      `${list.length} frames exceeds the supported maximum of ${EXPOSURE_MAX_FRAMES}; rendering is unchanged but performance is not guaranteed.`,
    );
  }
  const keyIndex = new Map<string, number>();
  const firstById = new Map<string, number>();
  // Every real id is reserved up front, so a generated key ("a#2") never takes an id that a
  // later frame really has.
  const realIds = new Set<string>();
  for (const f of list) if (typeof f?.id === 'string' && f.id.length > 0) realIds.add(f.id);
  const dupCount = new Map<string, number>();
  const entries: ExposureEntry[] = [];

  for (let i = 0; i < list.length; i++) {
    const f = (list[i] ?? {}) as ExposureFrame;
    let key: string;
    if (typeof f.id !== 'string' || f.id.length === 0) {
      key = `#${i}`;
      issues.push(`Frame at index ${i} has an empty or non-string id; keyed "${key}".`);
    } else if (firstById.has(f.id)) {
      let n = dupCount.get(f.id) ?? 1;
      do n++;
      while (realIds.has(`${f.id}#${n}`) || keyIndex.has(`${f.id}#${n}`));
      dupCount.set(f.id, n);
      key = `${f.id}#${n}`;
      issues.push(`Duplicate frame id "${f.id}" at index ${i}; keyed "${key}". \`value\` "${f.id}" targets the first.`);
    } else {
      key = f.id;
      firstById.set(f.id, i);
    }
    // A generated key could collide with a real id further on ("a#2" passed explicitly).
    while (keyIndex.has(key)) key = `${key}#${i}`;
    keyIndex.set(key, i);

    let hold = 1;
    if (f.hold !== undefined) {
      const raw = f.hold as unknown;
      const n = typeof raw === 'number' ? Math.round(raw) : NaN;
      hold = Number.isFinite(n) ? Math.min(12, Math.max(1, n)) : 1;
      if (raw !== hold) issues.push(`Frame "${key}" hold ${String(raw)} is outside 1–12 integers; using ${hold}.`);
    }

    let durationMs: number | undefined;
    if (f.durationMs !== undefined) {
      if (isFiniteNumber(f.durationMs) && f.durationMs >= 0) durationMs = f.durationMs;
      else issues.push(`Frame "${key}" durationMs ${String(f.durationMs)} is negative or not finite; ignored.`);
    }

    let atMs: number | undefined;
    if (f.at !== undefined) {
      const parsed = typeof f.at === 'string' ? Date.parse(f.at) : NaN;
      if (Number.isFinite(parsed)) atMs = parsed;
      else issues.push(`Frame "${key}" at "${String(f.at)}" is not a parseable ISO 8601 time; treated as missing.`);
    }

    let status: ExposureStatus | undefined;
    if (f.status !== undefined) {
      if (STATUSES.includes(f.status)) status = f.status;
      else issues.push(`Frame "${key}" status "${String(f.status)}" is not ok | warn | error | pending; ignored.`);
    }

    entries.push({
      key,
      index: i,
      source: f,
      label: typeof f.label === 'string' ? f.label : String(f.label ?? ''),
      detail: typeof f.detail === 'string' && f.detail.length > 0 ? f.detail : undefined,
      kind: typeof f.kind === 'string' && f.kind.length > 0 ? f.kind : undefined,
      status,
      marker: f.marker === true,
      hold,
      durationMs,
      atMs,
      causes: [],
    });
  }

  // Causes: only links to EARLIER frames survive (by id → its first occurrence).
  for (const e of entries) {
    const causes = e.source.causes;
    if (causes === undefined) continue;
    if (!Array.isArray(causes)) {
      issues.push(`Frame "${e.key}" causes must be an array of ids; ignored.`);
      continue;
    }
    const seen = new Set<number>();
    for (const c of causes) {
      // Real ids only (first occurrence): a generated key ("#3", "a#2") is never a cause.
      const target = typeof c === 'string' ? firstById.get(c) : undefined;
      if (target === undefined) {
        issues.push(`Frame "${e.key}" names unknown cause "${String(c)}"; link dropped.`);
      } else if (target === e.index) {
        issues.push(`Frame "${e.key}" names itself as a cause; link dropped.`);
      } else if (target > e.index) {
        issues.push(`Frame "${e.key}" names a later frame "${String(c)}" as a cause; causes only point backwards, link dropped.`);
      } else if (!seen.has(target)) {
        seen.add(target);
        e.causes.push(target);
      }
    }
  }

  // Elapsed time relative to the first frame with a valid `at`, and the gap each step held.
  const firstAt = entries.find((e) => e.atMs !== undefined)?.atMs;
  let maxGapMs = 0;
  let hasTiming = false;
  for (let i = 0; i < entries.length; i++) {
    const e = entries[i];
    if (e.atMs !== undefined && firstAt !== undefined) e.elapsedMs = e.atMs - firstAt;
    let gap = e.durationMs;
    if (gap === undefined && e.atMs !== undefined) {
      const next = entries[i + 1];
      if (next?.atMs !== undefined && next.atMs - e.atMs >= 0) gap = next.atMs - e.atMs;
    }
    if (gap !== undefined) {
      e.gapMs = gap;
      hasTiming = true;
      if (gap > maxGapMs) maxGapMs = gap;
    }
  }

  return { entries, keyIndex, issues, hasTiming, maxGapMs };
}

/** `stepMs` < 250 → 250; non-finite → the default. */
export function normalizeStepMs(stepMs: unknown): number {
  if (!isFiniteNumber(stepMs)) return EXPOSURE_DEFAULT_STEP_MS;
  return Math.max(EXPOSURE_MIN_STEP_MS, stepMs);
}

export function isExposureRate(v: unknown): v is ExposureRate {
  return v === 0.5 || v === 1 || v === 2 || v === 4;
}

/**
 * How long `entry` is shown during playback.
 * - even:     stepMs × hold ÷ rate
 * - elapsed:  clamp(gap, 250, 3000) ÷ rate; a missing gap falls back to `even`
 * - flipbook: FRAME_MS × hold ÷ rate (12 poses per second at 1×)
 */
export function exposureStepDuration(
  entry: Pick<ExposureEntry, 'hold' | 'gapMs'>,
  timing: ExposureTiming,
  rate: ExposureRate,
  stepMs: number,
): number {
  if (timing === 'flipbook') return (FRAME_MS * entry.hold) / rate;
  const even = (stepMs * entry.hold) / rate;
  if (timing === 'elapsed') {
    const g = entry.gapMs;
    if (g === undefined || !(g >= 0)) return even;
    return Math.min(EXPOSURE_ELAPSED_MAX_MS, Math.max(EXPOSURE_ELAPSED_MIN_MS, g)) / rate;
  }
  return even;
}

/** `F-01` … zero-padded to the digits of the total (minimum 2). */
export function formatFrameNumber(index: number, total: number): string {
  const width = Math.max(2, String(Math.max(1, total)).length);
  return `F-${String(index + 1).padStart(width, '0')}`;
}

/** `+mm:ss.s` (deterministic, locale-free). */
export function formatElapsed(ms: number): string {
  const sign = ms < 0 ? '-' : '+';
  const tenths = Math.floor(Math.abs(ms) / 100);
  const minutes = Math.floor(tenths / 600);
  const seconds = Math.floor((tenths % 600) / 10);
  const t = tenths % 10;
  return `${sign}${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}.${t}`;
}

/** `1.2s` / `340ms` (deterministic, locale-free). */
export function formatGap(ms: number): string {
  if (ms < 1000) return `${Math.round(ms)}ms`;
  if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`;
  return `${Math.floor(ms / 60000)}m${String(Math.floor((ms % 60000) / 1000)).padStart(2, '0')}s`;
}

/** "Frame 7 of 42: tool call write_file, error" */
export function describeExposureFrame(entry: ExposureEntry, total: number): string {
  const status = entry.status ? `, ${EXPOSURE_STATUS_WORDS[entry.status]}` : '';
  const marker = entry.marker ? ', marked' : '';
  return `Frame ${entry.index + 1} of ${total}: ${entry.label}${status}${marker}`;
}

/** True for targets where single-key shortcuts must never fire. */
export function isEditableTarget(target: EventTarget | null): boolean {
  if (!target || typeof (target as Element).closest !== 'function') return false;
  const el = target as HTMLElement;
  if (el.isContentEditable) return true;
  const tag = el.tagName;
  if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
  if (tag === 'INPUT') {
    // A range input is a playhead, not a text field: j/k/p still apply there.
    const type = (el as HTMLInputElement).type;
    return type !== 'range' && type !== 'radio' && type !== 'checkbox' && type !== 'button';
  }
  return el.closest('[contenteditable=""],[contenteditable="true"],[contenteditable="plaintext-only"]') !== null;
}

export interface UseExposureOptions {
  frames: readonly ExposureFrame[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (
    id: string,
    info: { index: number; reason: ExposureValueReason },
  ) => void;
  playing?: boolean;
  onPlayingChange?: (playing: boolean, reason: ExposurePlayingReason) => void;
  timing?: ExposureTiming;
  rate?: ExposureRate;
  defaultRate?: ExposureRate;
  onRateChange?: (rate: ExposureRate) => void;
  stepMs?: number;
  loop?: boolean;
  primaryMarker?: string;
  /** Prefix for dev errors. */
  name?: string;
}

export interface ExposureState {
  entries: readonly ExposureEntry[];
  count: number;
  /** Current index (-1 when there are no frames). */
  index: number;
  current: ExposureEntry | null;
  playing: boolean;
  /** The timing actually used (flipbook falls back to even when motion is unavailable). */
  timing: ExposureTiming;
  /** The timing the viewer (or the `timing` prop) asked for. */
  requestedTiming: ExposureTiming;
  setTiming: (timing: ExposureTiming) => void;
  /** False when the effective tempo is `still` (OS reduced motion, still tempo or ancestor). */
  flipbookAvailable: boolean;
  /** Playing in flipbook timing: the panel shows a slate instead of updating. */
  flipping: boolean;
  /** The index the panel shows: frozen at the flip's start while flipping. */
  panelIndex: number;
  rate: ExposureRate;
  setRate: (rate: ExposureRate) => void;
  /** Pointer drag in progress, or a keyboard scrub that has not settled yet. */
  scrubbing: boolean;
  /** Not scrubbing and not flipping. */
  settled: boolean;
  hasTiming: boolean;
  maxGapMs: number;
  /** Indices of marker frames, in order. */
  markers: readonly number[];
  /** Index of the marker that gets marker yellow (-1 without markers). */
  primaryMarkerIndex: number;
  /** One-level history: where "Back" returns to after following a cause. */
  back: ExposureEntry | null;
  /** Polite live-region text. */
  announcement: string;
  select: (index: number, reason: ExposureValueReason) => void;
  step: (delta: number, reason: ExposureValueReason) => void;
  /** `via: 'pointer'` (a click) announces at once instead of starting a keyboard scrub. */
  stepMarker: (direction: 1 | -1, via?: 'keyboard' | 'pointer') => void;
  followCause: (index: number) => void;
  goBack: () => void;
  play: () => void;
  pause: (reason: ExposurePlayingReason) => void;
  toggle: () => void;
  /** Call on pointer drag start / end. */
  beginPointerScrub: () => void;
  endPointerScrub: () => void;
  /** Call after a keyboard navigation (starts / restarts the 500 ms settle timer). */
  noteKeyScrub: () => void;
  /** Announce the (new) current frame once it has rendered: a click is already settled. */
  announceSettled: () => void;
  /** The single-key shortcuts (`j`/`k`/`[`/`]`/`p`). Returns true when the key was handled. */
  handleShortcut: (event: {
    key: string;
    target: EventTarget | null;
    ctrlKey?: boolean;
    metaKey?: boolean;
    altKey?: boolean;
  }) => boolean;
  /** Roving-row keys (`↑/↓/Home/End`): the index to move to, or null. */
  rowKeyTarget: (key: string, fromIndex: number) => number | null;
}

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;

const isDev = (): boolean => {
  try {
    return process.env.NODE_ENV !== 'production';
  } catch {
    return false;
  }
};

/** One dev-only console.error per distinct message per instance. */
function useDevErrors(name: string): (msg: string) => void {
  const seen = React.useRef<Set<string>>(new Set());
  return React.useCallback(
    (msg: string) => {
      if (!isDev() || seen.current.has(msg)) return;
      seen.current.add(msg);
      console.error(`[FRAME/12 ${name}] ${msg}`);
    },
    [name],
  );
}

function resolveIndex(
  requested: string | undefined,
  keyIndex: Map<string, number>,
  count: number,
  prev: { key: string; index: number } | null,
): number {
  if (count === 0) return -1;
  if (requested !== undefined) {
    const i = keyIndex.get(requested);
    if (i !== undefined) return i;
  }
  // The frame that was showing was removed: stay at its position (clamped).
  if (prev && requested === prev.key) return Math.min(prev.index, count - 1);
  return 0;
}

export function useExposure(options: UseExposureOptions): ExposureState {
  const {
    frames,
    value,
    defaultValue,
    onValueChange,
    playing: playingProp,
    onPlayingChange,
    timing: timingProp = 'even',
    rate: rateProp,
    defaultRate,
    onRateChange,
    stepMs: stepMsProp,
    loop = false,
    primaryMarker,
    name = 'useExposure',
  } = options;
  const devError = useDevErrors(name);

  // ------------------------------------------------------------------ input contract
  const normalized = React.useMemo(() => normalizeExposureFrames(frames), [frames]);
  const { entries, keyIndex } = normalized;
  const count = entries.length;
  const stepMs = normalizeStepMs(stepMsProp);

  React.useEffect(() => {
    for (const issue of normalized.issues) devError(issue);
  }, [normalized, devError]);
  React.useEffect(() => {
    if (stepMsProp === undefined) return;
    if (!isFiniteNumber(stepMsProp)) devError(`stepMs ${String(stepMsProp)} is not finite; using ${EXPOSURE_DEFAULT_STEP_MS}.`);
    else if (stepMsProp < EXPOSURE_MIN_STEP_MS) devError(`stepMs ${stepMsProp} is below ${EXPOSURE_MIN_STEP_MS}; clamped to ${EXPOSURE_MIN_STEP_MS}.`);
  }, [stepMsProp, devError]);

  // ------------------------------------------------------------------ controlled modes
  const valueControlled = React.useRef(value !== undefined).current;
  const playingControlled = React.useRef(playingProp !== undefined).current;
  const rateControlled = React.useRef(rateProp !== undefined).current;
  React.useEffect(() => {
    if ((value !== undefined) !== valueControlled) {
      devError(
        `\`value\` switched from ${valueControlled ? 'controlled to uncontrolled' : 'uncontrolled to controlled'}; the first mode wins. Keep \`value\` defined (controlled) or undefined (uncontrolled) for the lifetime of the component.`,
      );
    }
    if ((playingProp !== undefined) !== playingControlled) {
      devError(`\`playing\` switched between controlled and uncontrolled; the first mode wins.`);
    }
    if ((rateProp !== undefined) !== rateControlled) {
      devError(`\`rate\` switched between controlled and uncontrolled; the first mode wins.`);
    }
  }, [value, playingProp, rateProp, valueControlled, playingControlled, rateControlled, devError]);

  // ------------------------------------------------------------------ selection
  const [innerKey, setInnerKey] = React.useState<string | undefined>(defaultValue);
  const requested = valueControlled ? value : innerKey;
  const prevRef = React.useRef<{ key: string; index: number } | null>(null);
  const index = resolveIndex(requested, keyIndex, count, prevRef.current);
  const current = index >= 0 ? entries[index] : null;

  // ------------------------------------------------------------------ playing
  const [innerPlaying, setInnerPlaying] = React.useState(false);
  const rawPlaying = playingControlled ? playingProp === true : innerPlaying;
  const playing = rawPlaying && count > 1;

  // ------------------------------------------------------------------ rate & timing
  const [innerRate, setInnerRate] = React.useState<ExposureRate>(
    isExposureRate(defaultRate) ? defaultRate : 1,
  );
  const rawRate = rateControlled ? rateProp : innerRate;
  const rate: ExposureRate = isExposureRate(rawRate) ? rawRate : 1;
  React.useEffect(() => {
    if (rawRate !== undefined && !isExposureRate(rawRate)) devError(`rate ${String(rawRate)} is not 0.5 | 1 | 2 | 4; using 1.`);
    if (defaultRate !== undefined && !isExposureRate(defaultRate)) devError(`defaultRate ${String(defaultRate)} is not 0.5 | 1 | 2 | 4; using 1.`);
  }, [rawRate, defaultRate, devError]);

  const validTimingProp: ExposureTiming = EXPOSURE_TIMINGS.includes(timingProp) ? timingProp : 'even';
  const [timingState, setTimingState] = React.useState<{ prop: ExposureTiming; value: ExposureTiming }>(
    () => ({ prop: validTimingProp, value: validTimingProp }),
  );
  // A new `timing` prop value resets the viewer's choice (derived state, no effect round-trip).
  let requestedTiming = timingState.value;
  if (timingState.prop !== validTimingProp) {
    requestedTiming = validTimingProp;
    setTimingState({ prop: validTimingProp, value: validTimingProp });
  }
  React.useEffect(() => {
    if (!EXPOSURE_TIMINGS.includes(timingProp)) devError(`timing "${String(timingProp)}" is not even | elapsed | flipbook; using even.`);
  }, [timingProp, devError]);

  const { effectiveTempo } = useTempo();
  const flipbookAvailable = effectiveTempo !== 'still';
  const timing: ExposureTiming =
    requestedTiming === 'flipbook' && !flipbookAvailable ? 'even' : requestedTiming;
  const flipping = playing && timing === 'flipbook';

  // ------------------------------------------------------------------ markers
  const markers = React.useMemo(() => entries.filter((e) => e.marker).map((e) => e.index), [entries]);
  const primaryMarkerIndex = React.useMemo(() => {
    if (markers.length === 0) return -1;
    if (primaryMarker !== undefined) {
      const i = keyIndex.get(primaryMarker);
      if (i !== undefined && entries[i].marker) return i;
    }
    return markers[0];
  }, [markers, primaryMarker, keyIndex, entries]);
  React.useEffect(() => {
    if (!valueControlled && defaultValue !== undefined && count > 0 && !keyIndex.has(defaultValue)) {
      devError(`defaultValue "${defaultValue}" is not a frame id; showing the first frame.`);
    }
    // Initial value only.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  React.useEffect(() => {
    if (primaryMarker === undefined) return;
    const i = keyIndex.get(primaryMarker);
    if (i === undefined || !entries[i].marker) {
      devError(`primaryMarker "${primaryMarker}" is not a marked frame; the first marker gets marker yellow.`);
    }
  }, [primaryMarker, keyIndex, entries, devError]);

  // ------------------------------------------------------------------ latest-value refs
  const latest = React.useRef({
    entries,
    index,
    count,
    playing,
    rawPlaying,
    loop,
    valueControlled,
    playingControlled,
    onValueChange,
    onPlayingChange,
    timing,
  });
  latest.current = {
    entries,
    index,
    count,
    playing,
    rawPlaying,
    loop,
    valueControlled,
    playingControlled,
    onValueChange,
    onPlayingChange,
    timing,
  };

  // ------------------------------------------------------------------ announcements
  const [announcement, setAnnouncement] = React.useState('');
  const announcer = React.useRef<{ lastAt: number; timer: ReturnType<typeof setTimeout> | null; pending: string | null; last: string }>(
    { lastAt: -Infinity, timer: null, pending: null, last: '' },
  );
  // Nothing announces after unmount (a queued microtask or timer may still fire once).
  const mounted = React.useRef(false);
  React.useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  const announce = React.useCallback((text: string) => {
    if (!mounted.current) return;
    const a = announcer.current;
    const emit = (t: string) => {
      // Identical consecutive text would not be re-read; alternate a trailing no-break space.
      const next = t === a.last.replace(/\u00a0$/, '') && !a.last.endsWith('\u00a0') ? `${t}\u00a0` : t;
      if (!mounted.current) return;
      a.last = next;
      a.lastAt = performance.now();
      setAnnouncement(next);
    };
    const now = performance.now();
    if (now - a.lastAt >= EXPOSURE_ANNOUNCE_GAP_MS && a.timer === null) {
      emit(text);
      return;
    }
    a.pending = text;
    if (a.timer === null) {
      a.timer = setTimeout(() => {
        a.timer = null;
        const p = a.pending;
        a.pending = null;
        if (p !== null) emit(p);
      }, Math.max(0, a.lastAt + EXPOSURE_ANNOUNCE_GAP_MS - now));
    }
  }, []);

  // ------------------------------------------------------------------ playing transitions
  const setPlaying = React.useCallback(
    (next: boolean, reason: ExposurePlayingReason, atIndex?: number) => {
      const l = latest.current;
      // Compare with the raw state: with fewer than 2 frames `playing` reads false while the
      // underlying state may still be on, and that must be switched off (never resume later).
      if (next === l.rawPlaying) return;
      // Reflect the request at once so a second call in the same tick is a no-op.
      l.rawPlaying = next;
      l.playing = next && l.count > 1;
      if (!l.playingControlled) setInnerPlaying(next);
      l.onPlayingChange?.(next, reason);
      if (next) {
        announce('Playing');
      } else {
        const i = atIndex ?? l.index;
        const where = `Paused at frame ${i + 1} of ${l.count}`;
        announce(
          reason === 'tempo'
            ? `${where}. Flipbook needs motion; reduced motion or a still tempo is on.`
            : where,
        );
      }
    },
    [announce],
  );
  const pause = React.useCallback((reason: ExposurePlayingReason) => setPlaying(false, reason), [setPlaying]);

  // ------------------------------------------------------------------ selection transitions
  const commit = React.useCallback((target: number, reason: ExposureValueReason) => {
    const l = latest.current;
    const entry = l.entries[target];
    if (!entry || target === l.index) return;
    if (!l.valueControlled) setInnerKey(entry.key);
    l.onValueChange?.(entry.key, { index: target, reason });
  }, []);

  const [pointerScrub, setPointerScrub] = React.useState(false);
  const [keyScrub, setKeyScrub] = React.useState(false);
  const settleTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const announceCurrent = React.useCallback(() => {
    const l = latest.current;
    const e = l.entries[l.index];
    if (e) announce(describeExposureFrame(e, l.count));
  }, [announce]);

  const select = React.useCallback(
    (target: number, reason: ExposureValueReason) => {
      const l = latest.current;
      if (l.count === 0) return;
      const t = Math.min(l.count - 1, Math.max(0, Math.round(target)));
      if (reason !== 'playback' && reason !== 'data' && l.playing) setPlaying(false, 'scrub');
      commit(t, reason);
    },
    [commit, setPlaying],
  );

  const noteKeyScrub = React.useCallback(() => {
    setKeyScrub(true);
    if (settleTimer.current !== null) clearTimeout(settleTimer.current);
    settleTimer.current = setTimeout(() => {
      settleTimer.current = null;
      setKeyScrub(false);
      announceCurrent();
    }, EXPOSURE_SETTLE_MS);
  }, [announceCurrent]);

  const settleAnnounceTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const announceSettled = React.useCallback(() => {
    // After React applies the selection (it commits before the next task). Tracked, so unmount
    // cancels it.
    if (settleAnnounceTimer.current !== null) clearTimeout(settleAnnounceTimer.current);
    settleAnnounceTimer.current = setTimeout(() => {
      settleAnnounceTimer.current = null;
      announceCurrent();
    }, 0);
  }, [announceCurrent]);

  const pointerScrubRef = React.useRef(false);
  const beginPointerScrub = React.useCallback(() => {
    if (pointerScrubRef.current) return;
    pointerScrubRef.current = true;
    setPointerScrub(true);
    if (latest.current.playing) setPlaying(false, 'scrub');
  }, [setPlaying]);
  const endPointerScrub = React.useCallback(() => {
    if (!pointerScrubRef.current) return;
    pointerScrubRef.current = false;
    setPointerScrub(false);
    // Read the frame after React has applied the last move.
    queueMicrotask(announceCurrent);
  }, [announceCurrent]);

  const step = React.useCallback(
    (delta: number, reason: ExposureValueReason) => {
      const l = latest.current;
      if (l.count === 0) return;
      select(Math.min(l.count - 1, Math.max(0, l.index + delta)), reason);
    },
    [select],
  );

  const stepMarker = React.useCallback(
    (direction: 1 | -1, via: 'keyboard' | 'pointer' = 'keyboard') => {
      const l = latest.current;
      let target = -1;
      for (const e of direction > 0 ? l.entries : [...l.entries].reverse()) {
        if (e.marker && (direction > 0 ? e.index > l.index : e.index < l.index)) {
          target = e.index;
          break;
        }
      }
      if (target >= 0) {
        select(target, 'marker');
        // A click is already settled; only key presses count as a scrub.
        if (via === 'keyboard') noteKeyScrub();
        else announceSettled();
      }
    },
    [select, noteKeyScrub, announceSettled],
  );

  const [back, setBack] = React.useState<{ key: string; index: number } | null>(null);
  const followCause = React.useCallback(
    (target: number) => {
      const l = latest.current;
      const from = l.entries[l.index];
      if (!from || !l.entries[target]) return;
      setBack({ key: from.key, index: from.index });
      select(target, 'cause');
      announce(describeExposureFrame(l.entries[target], l.count));
    },
    [select, announce],
  );
  const goBack = React.useCallback(() => {
    const l = latest.current;
    if (!back) return;
    const i = keyIndex.get(back.key);
    setBack(null);
    if (i === undefined) return;
    select(i, 'cause');
    const e = l.entries[i];
    if (e) announce(describeExposureFrame(e, l.count));
  }, [back, keyIndex, select, announce]);
  // "Back" exists only while its frame still exists and is not the frame being shown (a reader
  // who returns there another way no longer needs it). One rule for the button and goBack.
  const backIndex = back ? keyIndex.get(back.key) : undefined;
  const backEntry = backIndex !== undefined && backIndex !== index ? entries[backIndex] : null;
  // Clear only when the reader MOVES to the back target (or it is gone), never merely because they
  // are equal: a controlled parent that applies the cause jump later (a transition, router
  // search params) commits once with `back` set and the old index first.
  const prevIndexForBack = React.useRef(index);
  React.useEffect(() => {
    const moved = prevIndexForBack.current !== index;
    prevIndexForBack.current = index;
    if (back && (backIndex === undefined || (moved && backIndex === index))) setBack(null);
  }, [back, backIndex, index]);

  // ------------------------------------------------------------------ play / pause
  const clock = React.useRef<{ deadline: number; pending: string | null }>({ deadline: 0, pending: null });
  const [flipAnchor, setFlipAnchor] = React.useState(-1);
  const play = React.useCallback(() => {
    const l = latest.current;
    if (l.count < 2 || l.playing) return;
    // Play at the end restarts from the first frame.
    if (l.index >= l.count - 1) commit(0, 'playback');
    setPlaying(true, 'user');
  }, [commit, setPlaying]);
  const toggle = React.useCallback(() => {
    if (latest.current.playing) pause('user');
    else play();
  }, [play, pause]);

  // ------------------------------------------------------------------ data changes
  const lastDataFire = React.useRef<string | null>(null);
  useIsoLayoutEffect(() => {
    const l = latest.current;
    // Too few frames to play (shrunk by data): stop, so growing back never resumes on its own.
    if (l.rawPlaying && count < 2) setPlaying(false, 'data', Math.max(0, index));
    if (!current) return;
    const prev = prevRef.current;
    if (requested !== current.key) {
      const removed = prev !== null && requested === prev.key && !keyIndex.has(prev.key);
      if (!valueControlled) setInnerKey(current.key);
      const sig = `${String(requested)}→${current.key}`;
      const fire = valueControlled ? lastDataFire.current !== sig : removed;
      if (fire) {
        lastDataFire.current = sig;
        onValueChange?.(current.key, { index, reason: 'data' });
      }
      if (removed && l.playing) setPlaying(false, 'data', index);
      // Controlled: until the parent applies the survivor, keep resolving the removed id to the
      // same position (instead of falling back to the first frame and firing again).
      if (valueControlled && requested !== undefined && prev !== null && requested === prev.key) {
        prevRef.current = { key: requested, index };
        return;
      }
    } else {
      lastDataFire.current = null;
    }
    prevRef.current = { key: current.key, index };
  });

  // ------------------------------------------------------------------ the clock
  // Whenever playback starts (play(), or a controlled `playing` the parent turned on), the first
  // deadline is measured from now.
  React.useEffect(() => {
    if (!playing) return;
    clock.current = { deadline: performance.now(), pending: null };
    setFlipAnchor(latest.current.index);
  }, [playing]);
  const currentKey = current?.key;
  const stepDuration = current ? exposureStepDuration(current, timing, rate, stepMs) : 0;
  React.useEffect(() => {
    if (!playing || currentKey === undefined) return;
    const c = clock.current;
    if (c.pending !== null && c.pending === currentKey) c.pending = null;
    let timer: ReturnType<typeof setTimeout> | null = null;
    const schedule = (dur: number) => {
      const now = performance.now();
      let deadline = c.deadline + dur;
      // After a stall (a long task, a throttled tab), rebase instead of catching up.
      if (deadline < now) deadline = now;
      timer = setTimeout(() => tick(deadline), Math.max(0, deadline - now));
    };
    const tick = (deadline: number) => {
      timer = null;
      const l = latest.current;
      c.deadline = deadline;
      if (c.pending !== null && l.entries[l.index]?.key === c.pending) c.pending = null; // applied; effect not re-run yet
      if (c.pending !== null) {
        // The controlled parent did not apply the previous advance by this deadline.
        c.pending = null;
        setPlaying(false, 'rejected');
        return;
      }
      let target = l.index + 1;
      if (target >= l.count) {
        if (!l.loop) {
          setPlaying(false, 'end');
          return;
        }
        target = 0;
      }
      const t = l.entries[target];
      if (!t) return;
      c.pending = t.key;
      commit(target, 'playback');
      // Never more than one frame per tick: the next tick is the check (or the next advance if
      // this component re-renders first, which cancels this timer).
      schedule(exposureStepDuration(t, l.timing, rate, stepMs));
    };
    schedule(stepDuration);
    return () => {
      if (timer !== null) clearTimeout(timer);
    };
  }, [playing, currentKey, stepDuration, rate, stepMs, commit, setPlaying]);

  // Hidden tab pauses; no auto-resume. Listener only exists while playing.
  React.useEffect(() => {
    if (!playing || typeof document === 'undefined') return;
    const onVis = () => {
      if (document.hidden) setPlaying(false, 'hidden');
    };
    document.addEventListener('visibilitychange', onVis);
    return () => document.removeEventListener('visibilitychange', onVis);
  }, [playing, setPlaying]);

  // A flipbook in progress pauses when motion becomes unavailable.
  // Only on the transition (available → unavailable): with flipbook selected under a still tempo,
  // Play still plays (in even timing) instead of pausing at once.
  const wasAvailable = React.useRef(flipbookAvailable);
  React.useEffect(() => {
    const was = wasAvailable.current;
    wasAvailable.current = flipbookAvailable;
    if (was && !flipbookAvailable && latest.current.playing && requestedTiming === 'flipbook') setPlaying(false, 'tempo');
  }, [flipbookAvailable, requestedTiming, setPlaying]);

  // Unmount: cancel every timer.
  React.useEffect(
    () => () => {
      if (settleTimer.current !== null) clearTimeout(settleTimer.current);
      if (settleAnnounceTimer.current !== null) clearTimeout(settleAnnounceTimer.current);
      if (announcer.current.timer !== null) clearTimeout(announcer.current.timer);
      settleTimer.current = null;
      settleAnnounceTimer.current = null;
      announcer.current.timer = null;
    },
    [],
  );

  const setRate = React.useCallback(
    (r: ExposureRate) => {
      if (!isExposureRate(r)) return;
      if (!rateControlled) setInnerRate(r);
      onRateChange?.(r);
    },
    [rateControlled, onRateChange],
  );
  const setTiming = React.useCallback(
    (t: ExposureTiming) => {
      if (!EXPOSURE_TIMINGS.includes(t)) return;
      if (t === 'flipbook' && !flipbookAvailable) return;
      if (t === 'flipbook' && latest.current.playing) setFlipAnchor(latest.current.index);
      setTimingState((s) => ({ ...s, value: t }));
    },
    [flipbookAvailable],
  );

  const handleShortcut = React.useCallback<ExposureState['handleShortcut']>(
    (e) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return false;
      if (isEditableTarget(e.target)) return false;
      switch (e.key) {
        case 'j':
          step(1, 'keyboard');
          noteKeyScrub();
          return true;
        case 'k':
          step(-1, 'keyboard');
          noteKeyScrub();
          return true;
        case ']':
          stepMarker(1);
          return true;
        case '[':
          stepMarker(-1);
          return true;
        case 'p':
          toggle();
          return true;
        default:
          return false;
      }
    },
    [step, stepMarker, toggle, noteKeyScrub],
  );

  const rowKeyTarget = React.useCallback((key: string, from: number): number | null => {
    const n = latest.current.count;
    if (n === 0) return null;
    if (key === 'ArrowDown') return Math.min(n - 1, from + 1);
    if (key === 'ArrowUp') return Math.max(0, from - 1);
    if (key === 'Home') return 0;
    if (key === 'End') return n - 1;
    return null;
  }, []);

  const scrubbing = pointerScrub || keyScrub;
  const panelIndex = flipping ? (flipAnchor >= 0 && flipAnchor < count ? flipAnchor : index) : index;

  return {
    entries,
    count,
    index,
    current,
    playing,
    timing,
    requestedTiming,
    setTiming,
    flipbookAvailable,
    flipping,
    panelIndex,
    rate,
    setRate,
    scrubbing,
    settled: !scrubbing && !flipping,
    hasTiming: normalized.hasTiming,
    maxGapMs: normalized.maxGapMs,
    markers,
    primaryMarkerIndex,
    back: backEntry,
    announcement,
    select,
    step,
    stepMarker,
    followCause,
    goBack,
    play,
    pause,
    toggle,
    beginPointerScrub,
    endPointerScrub,
    noteKeyScrub,
    announceSettled,
    handleShortcut,
    rowKeyTarget,
  };
}

'use client';

import * as React from 'react';
import { type MotionMode } from '@/hooks/use-on-twos';
import { useResolvedMotion } from '@/hooks/use-tempo';

export interface SheetProps extends React.HTMLAttributes<HTMLDivElement> {
  pegs?: boolean;
  autoCut?: boolean;
  motion?: MotionMode;
  theme?: 'light' | 'dark';
  sheetClassName?: string;
  children?: React.ReactNode;
}

export function Pegs() {
  return (
    <div className="f12-pegs" aria-hidden="true">
      <span className="f12-peg slot" />
      <span className="f12-peg round" />
      <span className="f12-peg slot" />
    </div>
  );
}

export const Sheet = React.forwardRef<HTMLDivElement, SheetProps>(function Sheet(
  {
    pegs = true,
    autoCut = false,
    motion = 'stepped',
    theme,
    className = '',
    sheetClassName = '',
    children,
    ...rest
  },
  ref,
) {
  // Emits the resolved mode (OS reduced motion, the nearest TempoProvider, then `motion`), so
  // CSS-only consumers inside follow it through the f12-m-* variable cascade.
  const effectiveMotion: MotionMode = useResolvedMotion(motion);
  const themeClass = theme ? ` f12-theme-${theme}` : '';
  const outerClass = `f12-dash f12-frame f12-m-${effectiveMotion}${themeClass}${className ? ` ${className}` : ''}`;
  const innerClass = `f12-sheet${sheetClassName ? ` ${sheetClassName}` : ''}`;
  const innerStyle = {
    '--f12-autocut-display': autoCut ? 'block' : 'none',
  } as React.CSSProperties;

  return (
    <div ref={ref} className={outerClass} data-theme={theme} {...rest}>
      <div
        className={innerClass}
        data-autocut={autoCut ? '' : undefined}
        style={innerStyle}
      >
        {pegs && <Pegs />}
        {children}
      </div>
    </div>
  );
});

'use client';

import * as React from 'react';

// Bundlers (Next.js, webpack, Vite) statically replace `process.env.NODE_ENV`. Declared locally so
// consumers without @types/node (e.g. Vite's react-ts template) still type-check this file.
declare const process: { env: { NODE_ENV?: string } };

export type SceneGutter = 'pair' | 'scene' | 'change';
export type SceneLayout = 'split' | 'stack' | 'equal' | 'three' | 'areas';

export const GUTTERS: Record<SceneGutter, number> = {
  pair: 12,
  scene: 20,
  change: 32,
};

export interface SceneProps extends React.HTMLAttributes<HTMLDivElement> {
  gutter?: SceneGutter;
  layout?: SceneLayout;
  areas?: string[];
  columns?: number;
  breakpoint?: number | string;
  children?: React.ReactNode;
}

export interface SceneAreaProps extends React.HTMLAttributes<HTMLDivElement> {
  area: string;
  children?: React.ReactNode;
}

export function resolveAreaProps(
  area: string | undefined,
  style: React.CSSProperties | undefined,
): { 'data-area': string | undefined; style: React.CSSProperties | undefined } {
  const safeArea = typeof area === 'string' && area.trim() ? area.trim() : undefined;
  const mergedStyle: React.CSSProperties | undefined = safeArea
    ? ({
        '--f12-area': safeArea,
        ...style,
      } as React.CSSProperties)
    : style;
  return { 'data-area': safeArea, style: mergedStyle };
}

export const SceneArea = React.forwardRef<HTMLDivElement, SceneAreaProps>(function SceneArea(
  { area, className = '', style, children, ...rest },
  ref,
) {
  const areaProps = resolveAreaProps(area, style);

  return (
    <div
      ref={ref}
      className={`f12-scene-area${className ? ` ${className}` : ''}`}
      data-area={areaProps['data-area']}
      style={areaProps.style}
      {...rest}
    >
      {children}
    </div>
  );
});

export const Scene = React.forwardRef<HTMLDivElement, SceneProps>(function Scene(
  {
    gutter = 'scene',
    layout = 'split',
    areas,
    columns,
    breakpoint = '860px',
    className = '',
    style,
    children,
    ...rest
  },
  ref,
) {
  const reactId = React.useId();
  const warnedAreasRef = React.useRef<string | null>(null);
  const warnedColsRef = React.useRef<string | null>(null);
  const warnedBpRef = React.useRef<string | null>(null);
  const safeGutter: SceneGutter =
    gutter === 'pair' || gutter === 'scene' || gutter === 'change' ? gutter : 'scene';
  const hasAreas = Array.isArray(areas) && areas.length > 0;
  const safeLayout: SceneLayout = hasAreas
    ? 'areas'
    : layout === 'split' ||
        layout === 'stack' ||
        layout === 'equal' ||
        layout === 'three' ||
        layout === 'areas'
      ? layout
      : 'split';

  const cleanedRows = hasAreas
    ? areas.map((row) => row.trim().replace(/^["']+|["']+$/g, '').trim())
    : [];
  const rowTokenCounts = cleanedRows.map((row) => (row ? row.split(/\s+/).length : 0));
  const firstRowCount = rowTokenCounts[0] ?? 0;

  const formattedAreas = hasAreas
    ? cleanedRows.map((row) => `"${row}"`).join(' ')
    : undefined;

  if (
    process.env.NODE_ENV !== 'production' &&
    hasAreas &&
    rowTokenCounts.length > 1 &&
    rowTokenCounts.some((count) => count !== firstRowCount) &&
    warnedAreasRef.current !== formattedAreas
  ) {
    warnedAreasRef.current = formattedAreas ?? null;
    console.warn(
      `[FRAME/12 Scene] Mismatched column counts across areas rows (${rowTokenCounts.join(', ')}). Every row in areas should have ${firstRowCount} column token(s).`,
    );
  }

  const explicitCols =
    typeof columns === 'number' && Number.isFinite(columns) && columns > 0
      ? Math.floor(columns)
      : undefined;

  if (
    process.env.NODE_ENV !== 'production' &&
    hasAreas &&
    explicitCols !== undefined &&
    explicitCols !== firstRowCount &&
    warnedColsRef.current !== `${explicitCols}:${firstRowCount}`
  ) {
    warnedColsRef.current = `${explicitCols}:${firstRowCount}`;
    console.warn(
      `[FRAME/12 Scene] Explicit columns (${explicitCols}) does not match the areas row token count (${firstRowCount}). Deriving ${firstRowCount} column(s) from areas.`,
    );
  }

  const safeColumns = firstRowCount > 0 ? firstRowCount : (explicitCols ?? 12);

  const hasExplicitBreakpoint =
    breakpoint !== undefined &&
    (typeof breakpoint !== 'string' || breakpoint.trim().length > 0);
  const rawBp =
    typeof breakpoint === 'number' && Number.isFinite(breakpoint) && breakpoint > 0
      ? `${breakpoint}px`
      : typeof breakpoint === 'string' && breakpoint.trim()
        ? /^\d+(\.\d+)?$/.test(breakpoint.trim())
          ? `${breakpoint.trim()}px`
          : breakpoint.trim()
        : '860px';
  const isValidBreakpoint =
    !hasExplicitBreakpoint ||
    (typeof breakpoint === 'number'
      ? Number.isFinite(breakpoint) && breakpoint > 0
      : /^\d+(\.\d+)?(px|rem|em)$/i.test(rawBp));

  if (
    process.env.NODE_ENV !== 'production' &&
    hasExplicitBreakpoint &&
    !isValidBreakpoint &&
    warnedBpRef.current !== String(breakpoint)
  ) {
    warnedBpRef.current = String(breakpoint);
    console.warn(
      `[FRAME/12 Scene] Invalid breakpoint "${String(breakpoint)}". Expected a positive number or px/rem/em length (e.g. "960px", "60rem"). Falling back to 860px.`,
    );
  }

  const normalizedBreakpoint = isValidBreakpoint ? rawBp : '860px';
  const isCustomBreakpoint = normalizedBreakpoint !== '860px';
  const bpSlug = normalizedBreakpoint.replace(/[^a-zA-Z0-9_-]/g, '-');
  const bpScope = `bp-${bpSlug}-${reactId.replace(/[^a-zA-Z0-9_-]/g, '')}`;

  const mergedStyle: React.CSSProperties | undefined = hasAreas
    ? ({
        '--f12-scene-cols': String(safeColumns),
        '--f12-scene-areas': formattedAreas,
        ...style,
      } as React.CSSProperties)
    : style;

  const classes = `f12-scene f12-scene-${safeLayout} f12-scene-${safeGutter}${className ? ` ${className}` : ''}`;

  return (
    <div
      ref={ref}
      className={classes}
      data-gutter={GUTTERS[safeGutter]}
      data-layout={safeLayout}
      data-columns={hasAreas ? safeColumns : undefined}
      data-breakpoint={hasAreas ? normalizedBreakpoint : undefined}
      data-scene-bp={hasAreas && isCustomBreakpoint ? bpScope : undefined}
      style={mergedStyle}
      {...rest}
    >
      {hasAreas && isCustomBreakpoint ? (
        <style>{`@media (min-width: ${normalizedBreakpoint}) { .f12-scene.f12-scene-areas[data-scene-bp="${bpScope}"] { grid-template-columns: repeat(var(--f12-scene-cols, 12), minmax(0, 1fr)); grid-template-areas: var(--f12-scene-areas); } .f12-scene.f12-scene-areas[data-scene-bp="${bpScope}"] > [data-area] { grid-area: var(--f12-area); } } @container (max-width: 760px) { .f12-scene.f12-scene-areas[data-scene-bp="${bpScope}"] { grid-template-columns: minmax(0, 1fr); grid-template-areas: none; } .f12-scene.f12-scene-areas[data-scene-bp="${bpScope}"] > [data-area] { grid-area: auto; } }`}</style>
      ) : null}
      {children}
    </div>
  );
});

'use client';

import * as React from 'react';
import { useSize } from '@/hooks/use-on-twos';
import { resolveAreaProps } from './scene';

// Bundlers (Next.js, webpack, Vite) statically replace `process.env.NODE_ENV`. Declared locally so
// consumers without @types/node (e.g. Vite's react-ts template) still type-check this file.
declare const process: { env: { NODE_ENV?: string } };

export type PanelShape = 'rect' | 'slant-bottom' | 'slant-top';
export type PanelVariant = 'expressive' | 'quiet';

export interface PanelProps extends React.HTMLAttributes<HTMLElement> {
  cut?: string | false;
  shape?: PanelShape;
  variant?: PanelVariant;
  label?: string;
  area?: string;
  children?: React.ReactNode;
}

const INACTIVE_SIZE_REF: { readonly current: HTMLElement | null } = { current: null };

const PANEL_VARIANT_CTX_KEY = Symbol.for('frame12.PanelVariantContext');
const globalRegistry = globalThis as unknown as Record<
  symbol,
  React.Context<PanelVariant | undefined> | undefined
>;
const PanelVariantContext = (globalRegistry[PANEL_VARIANT_CTX_KEY] ??= React.createContext<
  PanelVariant | undefined
>(undefined));

export function usePanelVariantContext(): PanelVariant | undefined {
  return React.useContext(PanelVariantContext);
}

export const Panel = React.forwardRef<HTMLElement, PanelProps>(function Panel(
  { cut, shape = 'rect', variant, className = '', label, area, style, children, ...rest },
  forwardedRef,
) {
  const inheritedVariant = React.useContext(PanelVariantContext);
  const resolvedVariant: PanelVariant = variant ?? inheritedVariant ?? 'expressive';
  const innerRef = React.useRef<HTMLElement | null>(null);
  const warnedCutRef = React.useRef<string | null>(null);
  const isQuiet = resolvedVariant === 'quiet';
  const showSvgFrame = !isQuiet || shape !== 'rect';
  const setRefs = React.useCallback(
    (node: HTMLElement | null) => {
      innerRef.current = node;
      if (typeof forwardedRef === 'function') {
        forwardedRef(node);
      } else if (forwardedRef) {
        (forwardedRef as React.MutableRefObject<HTMLElement | null>).current = node;
      }
    },
    [forwardedRef],
  );

  React.useEffect(() => {
    if (process.env.NODE_ENV !== 'production') {
      if (typeof cut === 'string' && cut.length > 0 && warnedCutRef.current !== cut) {
        const sheet = innerRef.current?.closest('.f12-sheet');
        if (sheet && sheet.hasAttribute('data-autocut')) {
          warnedCutRef.current = cut;
          console.warn(
            `[FRAME/12 Panel] Explicit cut "${cut}" used inside <Sheet autoCut>. Cut numbers are automatic inside <Sheet autoCut>; remove the cut prop or use cut={false}.`,
          );
        }
      }
    }
  }, [cut]);

  const { w, h } = useSize(showSvgFrame ? innerRef : INACTIVE_SIZE_REF);
  const s = 1.25; // half of 2.5px stroke
  const d = 16; // slant rise in px
  let pts: string;
  if (shape === 'slant-bottom') {
    pts = `${s},${s} ${w - s},${s} ${w - s},${h - s - d} ${s},${h - s}`;
  } else if (shape === 'slant-top') {
    pts = `${s},${s + d} ${w - s},${s} ${w - s},${h - s} ${s},${h - s}`;
  } else {
    pts = `${s},${s} ${w - s},${s} ${w - s},${h - s} ${s},${h - s}`;
  }

  const ssrPts =
    shape === 'slant-bottom'
      ? '0.35,0.35 99.65,0.35 99.65,93.2 0.35,99.65'
      : shape === 'slant-top'
        ? '0.35,6.8 99.65,0.35 99.65,99.65 0.35,99.65'
        : '0.35,0.35 99.65,0.35 99.65,99.65 0.35,99.65';

  const variantClass = isQuiet ? ' f12-panel-quiet' : '';
  const areaProps = resolveAreaProps(area, style);

  return (
    <section
      ref={setRefs}
      className={`f12-panel f12-${shape}${variantClass}${className ? ` ${className}` : ''}`}
      data-variant={isQuiet ? 'quiet' : undefined}
      data-area={areaProps['data-area']}
      aria-label={label}
      style={areaProps.style}
      {...rest}
    >
      {showSvgFrame &&
        (w > 0 ? (
          <svg className="f12-panel-frame" width={w} height={h} aria-hidden="true">
            <polygon points={pts} pathLength={1} />
          </svg>
        ) : (
          <svg
            className="f12-panel-frame"
            viewBox="0 0 100 100"
            preserveAspectRatio="none"
            aria-hidden="true"
          >
            <polygon vectorEffect="non-scaling-stroke" points={ssrPts} />
          </svg>
        ))}
      {typeof cut === 'string' && cut.length > 0 ? (
        <span className="f12-cut" aria-hidden="true">
          {cut}
        </span>
      ) : cut === undefined && !isQuiet ? (
        <span className="f12-cut" data-autocut="" aria-hidden="true" />
      ) : null}
      <div className="f12-panel-body">{children}</div>
    </section>
  );
});

'use client';

import * as React from 'react';
import { Panel, usePanelVariantContext, type PanelProps, type PanelVariant } from './panel';
import { resolveAreaProps } from './scene';

// Bundlers (Next.js, webpack, Vite) statically replace `process.env.NODE_ENV`. Declared locally so
// consumers without @types/node (e.g. Vite's react-ts template) still type-check this file.
declare const process: { env: { NODE_ENV?: string } };

export interface PanelPairProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: PanelVariant;
  area?: string;
  top?: Omit<PanelProps, 'shape'>;
  bottom?: Omit<PanelProps, 'shape'>;
  topCut?: string | false;
  bottomCut?: string | false;
  topLabel?: string;
  bottomLabel?: string;
  children?: React.ReactNode;
}

export const PanelPair = React.forwardRef<HTMLDivElement, PanelPairProps>(function PanelPair(
  {
    variant,
    area,
    top,
    bottom,
    topCut,
    bottomCut,
    topLabel,
    bottomLabel,
    className = '',
    style,
    children,
    ...rest
  },
  ref,
) {
  const inheritedVariant = usePanelVariantContext();
  const effectivePairVariant: PanelVariant = variant ?? inheritedVariant ?? 'expressive';
  const classes = `f12-pair${className ? ` ${className}` : ''}`;
  const areaProps = resolveAreaProps(area, style);

  if (top && bottom) {
    const topVariant = top.variant ?? effectivePairVariant;
    const bottomVariant = bottom.variant ?? effectivePairVariant;
    return (
      <div
        ref={ref}
        className={classes}
        data-area={areaProps['data-area']}
        style={areaProps.style}
        {...rest}
      >
        <Panel
          {...top}
          cut={top.cut ?? topCut}
          label={top.label ?? topLabel}
          variant={topVariant}
          shape={topVariant === 'quiet' ? 'rect' : 'slant-bottom'}
        />
        <Panel
          {...bottom}
          cut={bottom.cut ?? bottomCut}
          label={bottom.label ?? bottomLabel}
          variant={bottomVariant}
          shape={bottomVariant === 'quiet' ? 'rect' : 'slant-top'}
        />
      </div>
    );
  }

  const items = React.Children.toArray(children);
  if (process.env.NODE_ENV !== 'production' && items.length > 2) {
    console.warn(
      `[FRAME/12 PanelPair] Expected at most 2 children (top and bottom panels), received ${items.length}. Extra children will not be rendered.`,
    );
  }
  const first = items[0];
  const second = items[1];

  const renderSlot = (
    node: React.ReactNode,
    slantShape: 'slant-bottom' | 'slant-top',
    fallbackCut?: string | false,
    fallbackLabel?: string,
  ) => {
    if (React.isValidElement<PanelProps>(node) && node.type === Panel) {
      const slotVariant = node.props.variant ?? effectivePairVariant;
      const defaultShape = slotVariant === 'quiet' ? 'rect' : slantShape;
      return React.cloneElement(node, {
        variant: slotVariant,
        shape: node.props.shape && node.props.shape !== 'rect' ? node.props.shape : defaultShape,
        cut: node.props.cut ?? fallbackCut,
        label: node.props.label ?? fallbackLabel,
      });
    }
    const slotVariant = effectivePairVariant;
    return (
      <Panel
        variant={slotVariant}
        shape={slotVariant === 'quiet' ? 'rect' : slantShape}
        cut={fallbackCut}
        label={fallbackLabel}
      >
        {node}
      </Panel>
    );
  };

  return (
    <div
      ref={ref}
      className={classes}
      data-area={areaProps['data-area']}
      style={areaProps.style}
      {...rest}
    >
      {first !== undefined && renderSlot(first, 'slant-bottom', topCut, topLabel)}
      {second !== undefined && renderSlot(second, 'slant-top', bottomCut, bottomLabel)}
    </div>
  );
});

'use client';

import * as React from 'react';

export interface SegmentedOption<T extends string | number = string | number> {
  value: T;
  label: string;
  unit?: string;
}

export interface SegmentedControlProps<T extends string | number = string | number> {
  options: Array<SegmentedOption<T>>;
  value: T;
  onChange: (value: T) => void;
  ariaLabel?: string;
  idPrefix?: string;
  className?: string;
}

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;

export function SegmentedControl<T extends string | number = string | number>({
  options,
  value,
  onChange,
  ariaLabel = 'Options',
  idPrefix,
  className = '',
}: SegmentedControlProps<T>) {
  const autoId = React.useId().replace(/:/g, '');
  const resolvedPrefix = idPrefix ?? `seg-${autoId}`;
  const wrap = React.useRef<HTMLDivElement | null>(null);
  const [ind, setInd] = React.useState<{ x: number; w: number } | null>(null);
  // The indicator only animates once it has been painted. Values restored while the page starts
  // up (a saved theme, filter, or tab applied right after hydration) snap into place instead of
  // sliding across from the server-rendered default; later changes animate as usual.
  const [settled, setSettled] = React.useState(false);
  React.useEffect(() => {
    if (!ind || settled) return;
    let inner = 0;
    const outer = requestAnimationFrame(() => {
      inner = requestAnimationFrame(() => setSettled(true));
    });
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [ind, settled]);
  const [focusedValue, setFocusedValue] = React.useState<T>(value);

  React.useEffect(() => {
    if (typeof document !== 'undefined' && wrap.current?.contains(document.activeElement)) {
      return;
    }
    setFocusedValue(value);
  }, [value]);

  const activeFocusValue = options.some((o) => o.value === focusedValue)
    ? focusedValue
    : (options.find((o) => o.value === value)?.value ?? options[0]?.value);

  useIsoLayoutEffect(() => {
    const el = wrap.current?.querySelector<HTMLElement>('[aria-pressed="true"]');
    if (!el) return;
    const x = el.offsetLeft + el.clientLeft;
    const w = el.clientWidth;
    setInd((s) => (s && s.x === x && s.w === w ? s : { x, w }));
  });

  // Re-measure when fonts finish loading or the control resizes.
  const [, bump] = React.useState(0);
  React.useEffect(() => {
    const el = wrap.current;
    if (!el || typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(() => bump((n) => n + 1));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return (
    <div
      className={`f12-rng${className ? ` ${className}` : ''}`}
      ref={wrap}
      role="group"
      aria-label={ariaLabel}
      onBlur={(e) => {
        if (!wrap.current?.contains(e.relatedTarget as Node | null)) {
          setFocusedValue(value);
        }
      }}
    >
      {ind && (
        <span
          className="f12-rng-ind"
          aria-hidden="true"
          style={{
            transform: `translateX(${ind.x}px)`,
            width: ind.w,
            transition: settled ? undefined : 'none',
          }}
        />
      )}
      {options.map((opt, idx) => (
        <button
          key={String(opt.value)}
          id={`${resolvedPrefix}-${opt.value}`}
          type="button"
          className="f12-rng-btn"
          aria-pressed={value === opt.value}
          aria-keyshortcuts="ArrowLeft ArrowRight ArrowUp ArrowDown Home End"
          tabIndex={opt.value === activeFocusValue ? 0 : -1}
          onFocus={() => setFocusedValue(opt.value)}
          onClick={() => onChange(opt.value)}
          onKeyDown={(e) => {
            if (e.altKey || e.ctrlKey || e.metaKey || e.shiftKey || options.length === 0) return;
            let nextIdx = -1;
            if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
              nextIdx = (idx + 1) % options.length;
            } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
              nextIdx = (idx - 1 + options.length) % options.length;
            } else if (e.key === 'Home') {
              nextIdx = 0;
            } else if (e.key === 'End') {
              nextIdx = options.length - 1;
            }
            if (nextIdx !== -1) {
              e.preventDefault();
              const nextOpt = options[nextIdx];
              setFocusedValue(nextOpt.value);
              const buttons = wrap.current?.querySelectorAll<HTMLButtonElement>('.f12-rng-btn');
              buttons?.[nextIdx]?.focus();
            }
          }}
        >
          <span className="f12-rng-n">{opt.label}</span>
          {opt.unit && <span className="f12-rng-u">{opt.unit}</span>}
        </button>
      ))}
    </div>
  );
}

