  const resolvedSrLabel =
    srLabel === false
      ? undefined
      : srLabel !== undefined
        ? srLabel
        : status
          ? STATUS_SR_LABELS[status]
          : undefined;
  const childText = extractTextContent(children).trim();
  const showSrLabel =
