'use client';

import * as React from 'react';
import { type MotionMode, useCountUp } from '@/hooks/use-on-twos';

export const fmtPct = (v: number): string => (Math.abs(v) * 100).toFixed(1) + '%';
export const fmtPPAbs = (v: number): string => Math.abs(v).toFixed(2) + ' pp';
export const fmtMoney = (v: number): string => '$' + Math.round(v).toLocaleString('en-US');

export interface DeltaProps {
  value: number;
  kind?: 'pct' | 'pp';
  comparisonLabel?: string;
  range?: number | string;
}

export function Delta({ value, kind = 'pct', comparisonLabel, range }: DeltaProps) {
  const flat = kind === 'pp' ? Math.abs(value) < 0.005 : Math.abs(value) < 0.0005;
  const up = value > 0;
  const text = flat
    ? kind === 'pp'
      ? '0.00 pp change'
      : '0.0% change'
    : kind === 'pp'
      ? fmtPPAbs(value)
      : fmtPct(value);
  const dir = flat ? 'flat' : up ? 'up' : 'down';
  const sym = flat ? '=' : up ? '▲' : '▼';
  const refLabel = comparisonLabel ?? (range != null ? `vs prior ${range} days` : undefined);

  return (
    <p className={`f12-delta ${dir}`}>
      <span className="f12-delta-sym" aria-hidden="true">
        {sym}
      </span>
      <span className="f12-sr-only">{flat ? '' : up ? 'Up ' : 'Down '}</span>
      {text}
      {refLabel && <span className="f12-delta-ref"> {refLabel}</span>}
    </p>
  );
}

export type MetricHeadingLevel = 'h2' | 'h3' | 'h4' | 'div' | 'p';
export type MetricVariant = 'expressive' | 'quiet';

export interface MetricProps {
  label: string;
  value: number;
  format?: (value: number) => string;
  delta?: number;
  deltaKind?: 'pct' | 'pp';
  comparisonLabel?: string;
  range?: number | string;
  note?: string;
  big?: boolean;
  variant?: MetricVariant;
  motion?: MotionMode;
  spark?: React.ReactNode;
  headingLevel?: MetricHeadingLevel;
  className?: string;
}

export function Metric({
  label,
  value,
  format = fmtMoney,
  delta,
  deltaKind = 'pct',
  comparisonLabel,
  range,
  note,
  big = false,
  variant = 'expressive',
  motion,
  spark,
  headingLevel: HeadingTag = 'h2',
  className = '',
}: MetricProps) {
  const effectiveMotion: MotionMode = motion ?? (variant === 'quiet' ? 'cut' : 'stepped');
  const shown = useCountUp(value, effectiveMotion);
  const variantClass = variant === 'quiet' ? ' f12-metric-quiet' : '';
  const finalText = format(value);
  const shownText = format(shown);
  // Hero values size themselves to their column from the glyph count. Counting up, the settled
  // value is the longest string, so the size holds still; counting down (e.g. to 0) the frame in
  // flight can be longer, so it wins until the animation settles and the value never overflows.
  const heroStyle = big
    ? ({
        '--f12-m-chars': Math.max(finalText.length, shownText.length, 4),
      } as React.CSSProperties)
    : undefined;

  return (
    <div
      className={`f12-metric${big ? ' big' : ''}${variantClass}${className ? ` ${className}` : ''}`}
      data-variant={variant === 'quiet' ? 'quiet' : undefined}
      style={heroStyle}
    >
      <HeadingTag className="f12-m-label">{label}</HeadingTag>
      <p className="f12-m-value" aria-live="polite">
        <span className="f12-sr-only">{finalText}</span>
        <span aria-hidden="true">{shownText}</span>
      </p>
      {delta != null && (
        <Delta value={delta} kind={deltaKind} comparisonLabel={comparisonLabel} range={range} />
      )}
      {note && <p className="f12-m-note">{note}</p>}
      {spark}
    </div>
  );
}

'use client';

import * as React from 'react';

export interface BalloonProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Tail horizontal offset in pixels relative to the balloon center (-36 to +36) */
  tailOffset?: number;
  /** Whether to show the marker-yellow target dot at the tip of the tail */
  showDot?: boolean;
  children?: React.ReactNode;
}

/**
 * Standalone speech-balloon annotation with mitered tail and seam cover.
 * Uses the same geometry as ToneAreaChart's peak callout.
 */
export function Balloon({
  tailOffset = 0,
  showDot = true,
  className = '',
  children,
  ...rest
}: BalloonProps) {
  const clamped = Math.max(-36, Math.min(36, tailOffset));
  const svgW = 120;
  const svgH = 26;
  const tailX = svgW / 2 + clamped * 0.4;
  const px = svgW / 2 + clamped;
  const py = svgH - 5;

  return (
    <div className={`f12-balloon-standalone${className ? ` ${className}` : ''}`} {...rest}>
      <div className="f12-balloon">
        <span
          className="f12-balloon-gap"
          aria-hidden="true"
          style={{ left: `calc(50% + ${clamped * 0.4 - 5}px)` }}
        />
        {children}
      </div>
      <svg
        width={svgW}
        height={svgH}
        className="f12-balloon-standalone-svg"
        aria-hidden="true"
      >
        <path
          className="f12-tail"
          d={`M${tailX - 6},0 L${px - (px - tailX) * 0.15},${py - 7} L${tailX + 6},0`}
        />
        {showDot && <circle className="f12-peak-dot" cx={px} cy={py} r="4" />}
      </svg>
    </div>
  );
}

'use client';

import * as React from 'react';
import { useOnTwos, type MotionMode } from '@/hooks/use-on-twos';
import { useResolvedMotion } from '@/hooks/use-tempo';
import { extractTextContent } from './tag';

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;
let ghostWireMaskCounter = 0;

export type GhostWireOrientation = 'auto' | 'horizontal' | 'vertical';

export interface GhostWireProps extends React.HTMLAttributes<HTMLDivElement> {
  from: React.ReactNode;
  to: React.ReactNode;
  label?: string;
  strength?: number;
  orientation?: GhostWireOrientation;
  motion?: MotionMode;
}

export const GhostWire = React.forwardRef<HTMLDivElement, GhostWireProps>(function GhostWire(
  {
    from,
    to,
    label,
    strength = 0.5,
    orientation = 'auto',
    motion = 'stepped',
    className = '',
    ...rest
  },
  ref,
) {
  const innerRef = React.useRef<HTMLDivElement | null>(null);
  const setRefs = React.useCallback(
    (node: HTMLDivElement | null) => {
      innerRef.current = node;
      if (typeof ref === 'function') {
        ref(node);
      } else if (ref) {
        (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
      }
    },
    [ref],
  );

  const clampedStrength =
    typeof strength === 'number' && Number.isFinite(strength)
      ? Math.max(0, Math.min(1, strength))
      : 0.5;
  const safeOrientation: GhostWireOrientation =
    orientation === 'horizontal' || orientation === 'vertical' || orientation === 'auto'
      ? orientation
      : 'auto';

  const fromText = extractTextContent(from).trim() || 'source';
  const toText = extractTextContent(to).trim() || 'target';
  const reactId = React.useId();
  const baseSlug = (rest.id || `${fromText}-${toText}`)
    .replace(/[^a-zA-Z0-9_-]/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 32);
  const baseMaskId = `f12-gw-mask-${baseSlug ? `${baseSlug}-` : ''}${reactId.replace(/[^a-zA-Z0-9_-]/g, '')}`;
  const [maskSuffix, setMaskSuffix] = React.useState<string>('');
  const maskId = `${baseMaskId}${maskSuffix}`;
  const [autoVertical, setAutoVertical] = React.useState<boolean>(false);

  useIsoLayoutEffect(() => {
    const el = innerRef.current;
    if (!el || typeof document === 'undefined') return;
    const ownMask = el.querySelector('mask');
    const matching = document.querySelectorAll(`mask[id="${baseMaskId}"]`);
    if (matching.length > 1 && matching[0] !== ownMask) {
      ghostWireMaskCounter += 1;
      setMaskSuffix(`-r${ghostWireMaskCounter}`);
    }
  }, [baseMaskId]);

  useIsoLayoutEffect(() => {
    if (safeOrientation !== 'auto' || typeof window === 'undefined') {
      setAutoVertical(false);
      return;
    }
    const el = innerRef.current;
    const mql = window.matchMedia ? window.matchMedia('(max-width: 519.98px)') : null;
    const evaluate = (inlineWidth?: number) => {
      const measured =
        typeof inlineWidth === 'number' && inlineWidth > 0
          ? inlineWidth
          : el && el.clientWidth > 0
            ? el.clientWidth
            : 0;
      if (measured > 0) {
        setAutoVertical(measured < 520);
      } else if (mql) {
        setAutoVertical(mql.matches);
      }
    };
    evaluate();

    let ro: ResizeObserver | null = null;
    if (el && typeof ResizeObserver !== 'undefined') {
      ro = new ResizeObserver((entries) => {
        const w = entries[0]?.contentRect?.width;
        evaluate(w);
      });
      ro.observe(el);
    }

    const onMqlChange = () => evaluate();
    if (mql) {
      if (mql.addEventListener) {
        mql.addEventListener('change', onMqlChange);
      } else {
        mql.addListener(onMqlChange);
      }
    }

    return () => {
      if (ro) ro.disconnect();
      if (mql) {
        if (mql.removeEventListener) {
          mql.removeEventListener('change', onMqlChange);
        } else {
          mql.removeListener(onMqlChange);
        }
      }
    };
  }, [safeOrientation]);

  const resolvedOrientation: 'horizontal' | 'vertical' =
    safeOrientation === 'auto' ? (autoVertical ? 'vertical' : 'horizontal') : safeOrientation;

  const defaultAccessibleLabel = `${fromText} usually changes with ${toText}, which was not changed`;
  const groupAriaLabel =
    rest['aria-label'] ?? (label && label.trim() ? label.trim() : defaultAccessibleLabel);

  const resolvedMotion = useResolvedMotion(motion);
  const targetKey = `${fromText}|${toText}|${label ?? ''}|${clampedStrength.toFixed(3)}`;
  const [hydratedKey, setHydratedKey] = React.useState<string>('ssr');

  // The draw-on replays only when the key changes while animated. The key tracks the target even
  // while cut (reduced motion, a `still` tempo, `motion="cut"`), so a later switch to an animated
  // mode keeps the resting state instead of replaying an old draw-on.
  useIsoLayoutEffect(() => {
    setHydratedKey(targetKey);
  }, [targetKey]);

  const progress = useOnTwos(hydratedKey, 500, resolvedMotion);
  const dash = Math.round(3 + clampedStrength * 9);
  const gap = Math.round(10 - clampedStrength * 7);
  const dashArray = `${dash} ${gap}`;
  const dashOffset = progress >= 1 ? 0 : Number(((1 - progress) * 100).toFixed(2));
  const isVertical = resolvedOrientation === 'vertical';

  return (
    <div
      {...rest}
      ref={setRefs}
      role="group"
      aria-label={groupAriaLabel}
      className={`f12-ghost-wire f12-ghost-wire-${safeOrientation}${className ? ` ${className}` : ''}`}
      data-orientation={resolvedOrientation}
      data-strength={clampedStrength.toFixed(2)}
    >
      <span className="f12-ghost-wire-endpoint f12-ghost-wire-from" data-endpoint="from">
        {from}
      </span>
      <span className="f12-ghost-wire-connector">
        <svg
          className="f12-ghost-wire-svg"
          viewBox={isVertical ? '0 0 12 100' : '0 0 100 12'}
          preserveAspectRatio="none"
          aria-hidden="true"
          focusable="false"
        >
          <defs>
            <mask
              id={maskId}
              maskUnits="userSpaceOnUse"
              x="0"
              y="0"
              width={isVertical ? 12 : 100}
              height={isVertical ? 100 : 12}
            >
              <line
                className="f12-ghost-wire-reveal"
                x1={isVertical ? 6 : 0}
                y1={isVertical ? 0 : 6}
                x2={isVertical ? 6 : 100}
                y2={isVertical ? 100 : 6}
                strokeDasharray="100 100"
                strokeDashoffset={dashOffset}
              />
            </mask>
          </defs>
          <line
            className="f12-ghost-wire-line"
            x1={isVertical ? 6 : 0}
            y1={isVertical ? 0 : 6}
            x2={isVertical ? 6 : 100}
            y2={isVertical ? 100 : 6}
            vectorEffect="non-scaling-stroke"
            strokeDasharray={dashArray}
            mask={`url(#${maskId})`}
          />
        </svg>
        {label ? <span className="f12-ghost-wire-label">{label}</span> : null}
      </span>
      <span className="f12-ghost-wire-endpoint f12-ghost-wire-to" data-endpoint="to">
        {to}
      </span>
    </div>
  );
});

'use client';

import * as React from 'react';

export type ReceiptKind = 'commit' | 'file' | 'link';
export type ReceiptOrigin = 'human' | 'agent' | 'bot';

export const RECEIPT_ORIGIN_META: Record<ReceiptOrigin, { glyph: string; srLabel: string }> = {
  human: { glyph: '[H]', srLabel: 'Origin: human' },
  agent: { glyph: '[A]', srLabel: 'Origin: agent' },
  bot: { glyph: '[B]', srLabel: 'Origin: bot' },
};

function getSafeHttpHref(href: string | undefined): string | null {
  if (typeof href !== 'string') return null;
  const trimmed = href.trim();
  if (!trimmed || /[\u0000-\u001F\u007F]/.test(trimmed)) return null;
  if (trimmed.startsWith('#')) {
    return trimmed;
  }
  if (trimmed.startsWith('/')) {
    if (trimmed.startsWith('//') || trimmed.startsWith('/\\')) {
      return null;
    }
    return trimmed;
  }
  try {
    const parsed = new URL(trimmed);
    if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
      return trimmed;
    }
    return null;
  } catch {
    return null;
  }
}

export interface ReceiptProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, 'title'> {
  kind: ReceiptKind;
  value: string;
  href?: string;
  title?: string;
  date?: string;
  origin?: ReceiptOrigin;
}

export interface ReceiptListProps extends React.HTMLAttributes<HTMLUListElement> {
  ariaLabel?: string;
  children?: React.ReactNode;
}

export const Receipt = React.forwardRef<HTMLSpanElement, ReceiptProps>(function Receipt(
  { kind, value, href, title, date, origin, className = '', ...rest },
  ref,
) {
  const safeKind: ReceiptKind =
    kind === 'commit' || kind === 'file' || kind === 'link' ? kind : 'file';
  const safeOrigin: ReceiptOrigin | undefined =
    origin === 'human' || origin === 'agent' || origin === 'bot' ? origin : undefined;
  const rawValue = typeof value === 'string' ? value : '';
  const trimmedRaw = rawValue.trim();
  const isCommit = safeKind === 'commit';
  const rawDisplayValue = isCommit ? trimmedRaw.slice(0, 7) : trimmedRaw ? rawValue : '';
  const fullCommitTitle = isCommit && trimmedRaw ? trimmedRaw : undefined;
  const hasTruncatedCommit = isCommit && trimmedRaw.length > rawDisplayValue.length;
  const safeHref = getSafeHttpHref(href);
  const trimmedTitle = typeof title === 'string' && title.trim() ? title.trim() : undefined;
  const displayValue =
    rawDisplayValue || (safeHref ? (trimmedTitle ?? safeHref) : (trimmedTitle ?? ''));
  const showTitleChip = Boolean(title && (rawDisplayValue || displayValue !== trimmedTitle));
  const originMeta = safeOrigin ? RECEIPT_ORIGIN_META[safeOrigin] : undefined;

  return (
    <span
      ref={ref}
      className={`f12-receipt f12-receipt-${safeKind}${className ? ` ${className}` : ''}`}
      data-kind={safeKind}
      data-origin={safeOrigin}
      {...rest}
    >
      {originMeta ? (
        <span className={`f12-receipt-origin f12-receipt-origin-${safeOrigin}`}>
          <span className="f12-status-glyph" aria-hidden="true">
            {originMeta.glyph}
          </span>
          <span className="f12-sr-only">{`${originMeta.srLabel}: `}</span>
        </span>
      ) : null}
      {safeHref && displayValue ? (
        <a
          className="f12-receipt-value f12-receipt-link"
          href={safeHref}
          title={fullCommitTitle}
        >
          {isCommit ? (
            <code className="f12-receipt-code" title={fullCommitTitle}>
              {displayValue}
            </code>
          ) : (
            displayValue
          )}
        </a>
      ) : isCommit ? (
        <code className="f12-receipt-value f12-receipt-code" title={fullCommitTitle}>
          {displayValue}
        </code>
      ) : (
        <span className="f12-receipt-value">{displayValue}</span>
      )}
      {hasTruncatedCommit ? (
        <span className="f12-sr-only f12-receipt-sha-sr">{` (${trimmedRaw})`}</span>
      ) : null}
      {showTitleChip ? <span className="f12-receipt-title">{title}</span> : null}
      {date ? <span className="f12-receipt-date">{date}</span> : null}
    </span>
  );
});

export const ReceiptList = React.forwardRef<HTMLUListElement, ReceiptListProps>(
  function ReceiptList({ ariaLabel, className = '', children, ...rest }, ref) {
    const items = React.Children.toArray(children);

    return (
      <ul
        role="list"
        {...rest}
        ref={ref}
        className={`f12-receipt-list${className ? ` ${className}` : ''}`}
        aria-label={ariaLabel ?? rest['aria-label'] ?? 'Evidence receipts'}
      >
        {items.map((child, idx) => {
          if (React.isValidElement(child) && child.type === 'li') {
            return child;
          }
          const key = React.isValidElement(child) && child.key != null ? child.key : idx;
          return (
            <li key={key} className="f12-receipt-item">
              {child}
            </li>
          );
        })}
      </ul>
    );
  },
);

'use client';

import * as React from 'react';
import { type MotionMode, useOnTwos, useSize } from '@/hooks/use-on-twos';

export interface ToneAreaDatum {
  label: string;
  longLabel?: string;
  value: number;
  compareValue?: number;
}

export interface ToneAreaAnnotation {
  index: number;
  text: string;
}

export interface ToneAreaChartProps {
  data: ToneAreaDatum[];
  seriesLabel?: string;
  compareLabel?: string;
  labelColumnHeader?: string;
  formatValue?: (v: number) => string;
  formatShort?: (v: number) => string;
  annotation?: ToneAreaAnnotation | null;
  motion?: MotionMode;
  height?: number;
  tableSummary?: string;
  showTable?: boolean;
  ariaLabel?: string;
  className?: string;
}

export function defaultFormatValue(v: number): string {
  const safe = Number.isFinite(v) ? v : 0;
  return Math.round(safe).toLocaleString('en-US');
}

export function defaultFormatShort(v: number): string {
  const safe = Number.isFinite(v) ? v : 0;
  if (Math.abs(safe) >= 1000) {
    const k = safe / 1000;
    return (Number.isInteger(k) ? k.toFixed(0) : k.toFixed(1)) + 'k';
  }
  return String(Math.round(safe));
}

export function fmtCurrency(v: number): string {
  const safe = Number.isFinite(v) ? v : 0;
  const sign = safe < 0 ? '-' : '';
  return sign + '$' + Math.round(Math.abs(safe)).toLocaleString('en-US');
}

export function fmtCurrencyShort(v: number): string {
  const safe = Number.isFinite(v) ? v : 0;
  const sign = safe < 0 ? '-' : '';
  const abs = Math.abs(safe);
  if (abs >= 1000) {
    const k = abs / 1000;
    return sign + '$' + (Number.isInteger(k) ? k.toFixed(0) : k.toFixed(1)) + 'k';
  }
  return sign + '$' + Math.round(abs);
}

function niceStep(span: number, count: number): number {
  if (!Number.isFinite(span) || span <= 0) return 1;
  const raw = span / count;
  const mag = Math.pow(10, Math.floor(Math.log10(raw)));
  const n = raw / mag;
  const step = n <= 1 ? 1 : n <= 2 ? 2 : n <= 2.5 ? 2.5 : n <= 5 ? 5 : 10;
  return step * mag;
}

const TONE_BAND_RADII = [1.25, 1.05, 0.85, 0.62] as const;

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;

export function ToneAreaChart({
  data,
  seriesLabel = 'Value',
  compareLabel,
  labelColumnHeader = 'Label',
  formatValue = defaultFormatValue,
  formatShort = defaultFormatShort,
  annotation,
  motion = 'stepped',
  height = 260,
  tableSummary = 'Show data table',
  showTable = true,
  ariaLabel,
  className = '',
}: ToneAreaChartProps) {
  const wrap = React.useRef<HTMLDivElement | null>(null);
  const { w } = useSize(wrap);
  const rawId = React.useId();
  const uid = React.useMemo(() => 'c-' + rawId.replace(/:/g, ''), [rawId]);

  const safeData = React.useMemo<ToneAreaDatum[]>(
    () =>
      data.map((d) => ({
        ...d,
        value: Number.isFinite(d.value) ? d.value : 0,
        compareValue:
          d.compareValue != null && Number.isFinite(d.compareValue) ? d.compareValue : undefined,
      })),
    [data],
  );

  const n = safeData.length;
  const hasCompare = Boolean(compareLabel) && safeData.some((d) => d.compareValue != null);
  const tweenKey = `${n}|${safeData[0]?.label ?? ''}|${safeData[n - 1]?.value ?? ''}|${compareLabel ?? ''}`;
  const p = useOnTwos(tweenKey, 750, motion);
  const [hover, setHover] = React.useState<number | null>(null);
  const balloon = React.useRef<HTMLDivElement | null>(null);
  const [bw, setBw] = React.useState<number>(0);

  const pad = { l: 46, r: 14, t: 46, b: 28 };
  const isMeasured = w > 0;
  const W = isMeasured ? w : 680;
  const H = height;
  const iw = Math.max(1, W - pad.l - pad.r);
  const ih = Math.max(1, H - pad.t - pad.b);

  const allValues: number[] = [];
  for (const d of safeData) {
    allValues.push(d.value);
    if (hasCompare && d.compareValue != null) {
      allValues.push(d.compareValue);
    }
  }
  const rawMax = allValues.length > 0 ? Math.max(...allValues) : 0;
  const rawMin = allValues.length > 0 ? Math.min(...allValues) : 0;
  const domainMax = Math.max(0, rawMax);
  const domainMin = Math.min(0, rawMin);
  const span = Math.max(1, domainMax - domainMin);
  const step = niceStep(span, 4);
  const top = domainMax > 0 ? Math.ceil(domainMax / step) * step : domainMin === 0 ? step : 0;
  const bottom = domainMin < 0 ? -Math.ceil(Math.abs(domainMin) / step) * step : 0;
  const totalSpan = Math.max(step, top - bottom);

  const x = (i: number) => pad.l + (n <= 1 ? iw / 2 : (i / (n - 1)) * iw);
  const y = (v: number) => pad.t + ih - ((v - bottom) / totalSpan) * ih;
  const zeroY = y(0);

  const line = (get: (d: ToneAreaDatum) => number) =>
    safeData.map((d, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(get(d)).toFixed(1)}`).join('');

  const totalPath = n > 0 ? line((d) => d.value) : '';
  const areaPath =
    n > 0
      ? `${totalPath}L${x(n - 1).toFixed(1)},${zeroY.toFixed(1)}L${x(0).toFixed(1)},${zeroY.toFixed(1)}Z`
      : '';
  const focusPath = hasCompare && n > 0 ? line((d) => d.compareValue ?? 0) : null;

  const ticks: number[] = [];
  for (let v = bottom; v <= top + 1e-6; v += step) {
    ticks.push(Math.abs(v) < 1e-9 ? 0 : v);
  }

  const pxPerDay = n > 1 ? iw / (n - 1) : iw;
  const baseEvery = n <= 7 ? 1 : n <= 30 ? 7 : 14;
  const labelEvery = Math.max(baseEvery, Math.ceil(84 / pxPerDay / baseEvery) * baseEvery);
  const xLabels: number[] = [];
  for (let i = n - 1; i >= 0; i -= labelEvery) xLabels.push(i);

  const resolvedAnnotation = React.useMemo<ToneAreaAnnotation | null>(() => {
    if (annotation === null || n === 0) return null;
    if (annotation !== undefined) {
      const idx = Math.max(0, Math.min(n - 1, annotation.index));
      return { index: idx, text: annotation.text };
    }
    let peakI = 0;
    for (let i = 1; i < n; i++) {
      if (safeData[i].value > safeData[peakI].value) peakI = i;
    }
    const pk = safeData[peakI];
    return {
      index: peakI,
      text: `Peak ${pk.label} · ${formatValue(pk.value)}`,
    };
  }, [annotation, safeData, formatValue, n]);

  const peakI = resolvedAnnotation ? resolvedAnnotation.index : 0;
  const peakPoint = safeData[peakI];
  const px = peakPoint ? x(peakI) : 0;
  const py = peakPoint ? y(peakPoint.value) : 0;

  useIsoLayoutEffect(() => {
    if (balloon.current) setBw(balloon.current.offsetWidth);
  });

  const onMove = (e: React.PointerEvent<SVGSVGElement>) => {
    if (!wrap.current || n === 0) return;
    const r = wrap.current.getBoundingClientRect();
    const mx = e.clientX - r.left;
    const i = n <= 1 ? 0 : Math.round(((mx - pad.l) / iw) * (n - 1));
    setHover(Math.max(0, Math.min(n - 1, i)));
  };

  const onKey = (e: React.KeyboardEvent<SVGSVGElement>) => {
    if (n === 0) return;
    if (e.key === 'ArrowRight') {
      setHover((h) => Math.min(n - 1, h == null ? n - 1 : h + 1));
      e.preventDefault();
    } else if (e.key === 'ArrowLeft') {
      setHover((h) => Math.max(0, h == null ? n - 1 : h - 1));
      e.preventDefault();
    } else if (e.key === 'Escape') {
      setHover(null);
    }
  };

  const clipW = pad.l + iw * p + 5;
  const hd = hover != null && safeData[hover] ? safeData[hover] : null;
  const bLeft = W ? Math.max(pad.l, Math.min(px - bw / 2, W - pad.r - bw)) : 0;
  const tailX = Math.min(Math.max(px, bLeft + 14), Math.max(bLeft + 14, bLeft + bw - 14));
  const bTop = 6;
  const bH = 28;
  const showPeak = p >= 0.999 && hover == null && resolvedAnnotation != null;

  const computedAriaLabel =
    ariaLabel ??
    `${seriesLabel}, ${n} points.${
      peakPoint
        ? ` Peak ${peakPoint.longLabel ?? peakPoint.label}, ${formatValue(peakPoint.value)}.`
        : ''
    }`;

  return (
    <div className={`f12-tone-area-chart${className ? ` ${className}` : ''}`}>
      <div className="f12-chart" ref={wrap} style={{ height: H }}>
        {n > 0 && (
          <svg
            width={isMeasured ? W : '100%'}
            height={H}
            viewBox={`0 0 ${W} ${H}`}
            preserveAspectRatio={isMeasured ? undefined : 'none'}
            className="f12-chart-svg"
            role="img"
            aria-label={computedAriaLabel}
            tabIndex={0}
            onPointerMove={onMove}
            onPointerLeave={() => setHover(null)}
            onKeyDown={onKey}
            onBlur={() => setHover(null)}
          >
            <defs>
              <clipPath id={`${uid}-clip`}>
                <rect x="0" y="0" width={clipW} height={H} />
              </clipPath>
              {TONE_BAND_RADII.map((radius, b) => (
                <React.Fragment key={b}>
                  <pattern
                    id={`${uid}-tone-${b}`}
                    width="5"
                    height="5"
                    patternUnits="userSpaceOnUse"
                    patternTransform="rotate(45)"
                  >
                    <circle cx="2.5" cy="2.5" r={radius} className="f12-tone-dot" />
                  </pattern>
                  <clipPath id={`${uid}-band-${b}`}>
                    <rect
                      x="0"
                      y={pad.t + (ih * b) / TONE_BAND_RADII.length}
                      width={W}
                      height={ih / TONE_BAND_RADII.length + 0.5}
                    />
                  </clipPath>
                </React.Fragment>
              ))}
            </defs>

            {ticks.map((v) => (
              <g key={v} className="f12-ytick">
                <line
                  x1={pad.l}
                  x2={W - pad.r}
                  y1={y(v)}
                  y2={y(v)}
                  className={v === 0 ? 'f12-baseline' : 'f12-grid'}
                />
                <text x={pad.l - 8} y={y(v)} dy="0.35em" textAnchor="end">
                  {formatShort(v)}
                </text>
              </g>
            ))}

            <g className="f12-sheet-ticks" aria-hidden="true">
              {safeData.map(
                (_, i) =>
                  (n <= 30 || i % 3 === 0) && (
                    <line
                      key={i}
                      x1={x(i)}
                      x2={x(i)}
                      y1={y(bottom)}
                      y2={y(bottom) + (xLabels.includes(i) ? 7 : 3.5)}
                    />
                  ),
              )}
            </g>

            {xLabels.map((i) => (
              <text
                key={i}
                className="f12-xlab"
                x={x(i)}
                y={H - 8}
                textAnchor={i === n - 1 ? 'end' : i === 0 ? 'start' : 'middle'}
              >
                {safeData[i].label}
              </text>
            ))}

            <g clipPath={`url(#${uid}-clip)`}>
              {TONE_BAND_RADII.map((_, b) => (
                <path
                  key={b}
                  d={areaPath}
                  fill={`url(#${uid}-tone-${b})`}
                  clipPath={`url(#${uid}-band-${b})`}
                />
              ))}
              <path d={totalPath} className="f12-l-total" fill="none" />
              {focusPath && (
                <>
                  <path d={focusPath} className="f12-l-focus" fill="none" />
                  {xLabels.map((i) => {
                    const cv = safeData[i]?.compareValue;
                    if (cv == null) return null;
                    const cx = x(i);
                    const cy = y(cv);
                    return (
                      <polygon
                        key={`cmp-pt-${i}`}
                        className="f12-compare-pt"
                        points={`${cx.toFixed(1)},${(cy - 3.5).toFixed(1)} ${(cx + 3.5).toFixed(1)},${cy.toFixed(1)} ${cx.toFixed(1)},${(cy + 3.5).toFixed(1)} ${(cx - 3.5).toFixed(1)},${cy.toFixed(1)}`}
                      />
                    );
                  })}
                </>
              )}
            </g>

            {showPeak && resolvedAnnotation && (
              <>
                {isMeasured && (
                  <path
                    className="f12-tail"
                    d={`M${tailX - 6},${bTop + bH - 1} L${px - (px - tailX) * 0.15},${py - 7} L${tailX + 6},${bTop + bH - 1}`}
                  />
                )}
                <circle className="f12-peak-dot" cx={px} cy={py} r="4" />
              </>
            )}

            {hd && hover != null && (
              <g className="f12-cross" aria-hidden="true">
                <line x1={x(hover)} x2={x(hover)} y1={pad.t - 4} y2={y(bottom)} />
                <circle cx={x(hover)} cy={y(hd.value)} r="4.5" className="f12-cross-dot" />
                {hasCompare && hd.compareValue != null && (
                  <polygon
                    className="f12-cross-dot2"
                    points={`${x(hover).toFixed(1)},${(y(hd.compareValue) - 4.5).toFixed(1)} ${(x(hover) + 4.5).toFixed(1)},${y(hd.compareValue).toFixed(1)} ${x(hover).toFixed(1)},${(y(hd.compareValue) + 4.5).toFixed(1)} ${(x(hover) - 4.5).toFixed(1)},${y(hd.compareValue).toFixed(1)}`}
                  />
                )}
              </g>
            )}
          </svg>
        )}

        {showPeak && resolvedAnnotation && (
          <div
            ref={balloon}
            className="f12-balloon"
            style={
              isMeasured
                ? { left: bLeft, top: bTop, minHeight: bH }
                : {
                    left: `${Math.max(10, Math.min(80, (px / W) * 100))}%`,
                    transform: 'translateX(-50%)',
                    top: bTop,
                    minHeight: bH,
                  }
            }
            aria-hidden="true"
          >
            {isMeasured && <span className="f12-balloon-gap" style={{ left: tailX - bLeft - 5 }} />}
            {resolvedAnnotation.text}
          </div>
        )}

        {hd && hover != null && (
          <div
            className="f12-tip"
            role="status"
            style={{ left: Math.min(Math.max(x(hover) - 80, 4), Math.max(4, W - 164)), top: 4 }}
          >
            <strong>{hd.longLabel ?? hd.label}</strong>
            <span>
              <i className="f12-sw f12-sw-total" aria-hidden="true" />
              {seriesLabel} {formatValue(hd.value)}
            </span>
            {hasCompare && hd.compareValue != null && (
              <span>
                <i className="f12-sw f12-sw-focus" aria-hidden="true" />
                {compareLabel} {formatValue(hd.compareValue)}
              </span>
            )}
          </div>
        )}
      </div>

      {showTable && (
        <details className="f12-tbl">
          <summary>{tableSummary}</summary>
          <div className="f12-tbl-scroll">
            <table>
              <thead>
                <tr>
                  <th scope="col">{labelColumnHeader}</th>
                  <th scope="col">{seriesLabel}</th>
                  {hasCompare && <th scope="col">{compareLabel}</th>}
                </tr>
              </thead>
              <tbody>
                {safeData
                  .slice()
                  .reverse()
                  .map((d, idx) => (
                    <tr key={`${d.label}-${idx}`}>
                      <td>{d.longLabel ?? d.label}</td>
                      <td>{formatValue(d.value)}</td>
                      {hasCompare && <td>{formatValue(d.compareValue ?? 0)}</td>}
                    </tr>
                  ))}
              </tbody>
            </table>
          </div>
        </details>
      )}
    </div>
  );
}

'use client';

import * as React from 'react';
import { type MotionMode } from '@/hooks/use-on-twos';
import { Badge } from './badge';

export type ToneBarPattern = 'dots' | 'hatch' | 'dense';
export type ToneBarDensity = 'comfortable' | 'compact';

export interface ToneBarItem {
  id: string;
  name: string;
  value: number;
  formattedValue?: string;
  share?: number;
  badge?: string;
  pattern?: ToneBarPattern;
}

export interface ToneBarListProps {
  title?: string;
  subtitle?: string;
  items: ToneBarItem[];
  selectedId?: string | null;
  onSelect?: (id: string | null) => void;
  motion?: MotionMode;
  changed?: boolean;
  density?: ToneBarDensity;
  idPrefix?: string;
  className?: string;
}

export function ToneBarList({
  title,
  subtitle,
  items,
  selectedId = null,
  onSelect,
  changed = false,
  density = 'comfortable',
  idPrefix,
  className = '',
}: ToneBarListProps) {
  const autoId = React.useId().replace(/:/g, '');
  const resolvedPrefix = idPrefix ?? `f12-${autoId}`;
  const max = Math.max(1, ...items.map((r) => (Number.isFinite(r.value) ? r.value : 0)));
  const listKey = items.map((r) => `${r.id}:${r.value}`).join('|');
  const isCompact = density === 'compact';

  return (
    <div
      className={`f12-ints${isCompact ? ' f12-ints-compact' : ''}${className ? ` ${className}` : ''}`}
      data-density={isCompact ? 'compact' : undefined}
    >
      {(title || subtitle) && (
        <div className="f12-ints-hd">
          {title && <h3 className="f12-m-label">{title}</h3>}
          {subtitle && <p className="f12-ints-sub">{subtitle}</p>}
        </div>
      )}
      <ul className={`f12-ints-list${changed ? ' f12-enter enter' : ''}`} key={listKey}>
        {items.map((r) => {
          const on = selectedId === r.id;
          const safeVal = Number.isFinite(r.value) ? r.value : 0;
          const formatted = r.formattedValue ?? '$' + Math.round(safeVal).toLocaleString('en-US');
          const patternClass =
            r.pattern && r.pattern !== 'dots' ? ` f12-int-fill-${r.pattern}` : '';
          return (
            <li key={r.id}>
              <button
                type="button"
                id={resolvedPrefix ? `int-${resolvedPrefix}-${r.id}` : `int-${r.id}`}
                className="f12-int-row"
                aria-pressed={on}
                onClick={() => onSelect?.(on ? null : r.id)}
              >
                <span className="f12-int-name">
                  {r.name}
                  {r.badge && (
                    <Badge pop={changed} burst>
                      {r.badge}
                    </Badge>
                  )}
                </span>
                <span className="f12-int-bar" aria-hidden="true">
                  <span
                    className={`f12-int-fill${patternClass}`}
                    data-pattern={r.pattern ?? 'dots'}
                    style={{ width: `${Math.max(0, (safeVal / max) * 100)}%` }}
                  />
                </span>
                <span className="f12-int-val">
                  {formatted}
                  {r.share != null && (
                    <span className="f12-int-share">{(r.share * 100).toFixed(0)}%</span>
                  )}
                </span>
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

'use client';

import * as React from 'react';
import { type MotionMode, useOnTwos, useSize } from '@/hooks/use-on-twos';

export interface ToneSparkProps {
  values: number[];
  label: string;
  ariaLabel?: string;
  rangeKey?: string | number;
  motion?: MotionMode;
  height?: number;
  className?: string;
}

export function ToneSpark({
  values,
  label,
  ariaLabel,
  rangeKey,
  motion = 'stepped',
  height = 40,
  className = '',
}: ToneSparkProps) {
  const ref = React.useRef<HTMLDivElement | null>(null);
  const { w } = useSize(ref);
  const p = useOnTwos(rangeKey ?? values.length, 600, motion);
  const rawId = React.useId();
  const uid = React.useMemo(() => 's-' + rawId.replace(/:/g, ''), [rawId]);

  const safeValues = React.useMemo(
    () => values.map((v) => (Number.isFinite(v) ? Math.max(0, v) : 0)),
    [values],
  );
  const H = height;
  const max = Math.max(1, ...safeValues);
  const n = safeValues.length;
  const gap = n > 40 ? 1 : 2;
  const isMeasured = w > 0;
  const W = isMeasured ? w : 280;
  const bw = n > 0 ? Math.max(1, (W - gap * (n - 1)) / n) : 0;
  const shownCount = Math.ceil(n * p);
  const computedAriaLabel = ariaLabel ?? `${label}, last ${n} days, one bar per day`;

  return (
    <div className={`f12-spark${className ? ` ${className}` : ''}`} ref={ref}>
      <p className="f12-spark-l">{label}</p>
      {n > 0 && (
        <svg
          width={isMeasured ? W : '100%'}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          preserveAspectRatio={isMeasured ? undefined : 'none'}
          role="img"
          aria-label={computedAriaLabel}
        >
          <defs>
            <pattern
              id={`${uid}-st`}
              width="4"
              height="4"
              patternUnits="userSpaceOnUse"
              patternTransform="rotate(45)"
            >
              <circle cx="2" cy="2" r="1.05" className="f12-tone-dot" />
            </pattern>
          </defs>
          {safeValues.map((v, i) =>
            i < shownCount ? (
              <rect
                key={i}
                className="f12-spark-bar"
                vectorEffect="non-scaling-stroke"
                fill={`url(#${uid}-st)`}
                x={i * (bw + gap)}
                y={H - (v / max) * H}
                width={bw}
                height={(v / max) * H}
              />
            ) : null,
          )}
        </svg>
      )}
    </div>
  );
}

'use client';

import * as React from 'react';
import { Button, type ButtonProps } from './button';

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;

const openDialogStack: HTMLDialogElement[] = [];
let dialogObserver: MutationObserver | null = null;

function pushOpenDialog(el: HTMLDialogElement) {
  const idx = openDialogStack.indexOf(el);
  if (idx !== -1) openDialogStack.splice(idx, 1);
  openDialogStack.push(el);
}

function removeOpenDialog(el: HTMLDialogElement) {
  const idx = openDialogStack.indexOf(el);
  if (idx !== -1) openDialogStack.splice(idx, 1);
}

function processDialogMutations(records: MutationRecord[]) {
  for (const rec of records) {
    if (rec.type === 'attributes' && rec.attributeName === 'open') {
      const target = rec.target;
      if (typeof HTMLDialogElement !== 'undefined' && target instanceof HTMLDialogElement) {
        if (target.open && target.isConnected) {
          pushOpenDialog(target);
        } else {
          removeOpenDialog(target);
        }
      }
    }
  }
}

function ensureDialogObserver() {
  if (dialogObserver || typeof document === 'undefined' || typeof MutationObserver === 'undefined') {
    return;
  }
  for (const d of document.querySelectorAll<HTMLDialogElement>('dialog[open]')) {
    pushOpenDialog(d);
  }
  dialogObserver = new MutationObserver(processDialogMutations);
  if (document.documentElement) {
    dialogObserver.observe(document.documentElement, {
      subtree: true,
      attributes: true,
      attributeFilter: ['open'],
    });
  }
}

function isModalDialog(d: HTMLDialogElement): boolean {
  if (!d.isConnected || !d.open) return false;
  try {
    if (d.matches(':modal')) return true;
    // In environments where showModal() is supported, non-modal .show() dialogs do not match :modal
    if (typeof d.showModal === 'function' && document.querySelector('dialog:modal')) {
      return false;
    }
  } catch {
    // Fallback if :modal selector is unsupported
  }
  return true;
}

function getTopmostOpenDialog(): HTMLDialogElement | undefined {
  ensureDialogObserver();
  if (dialogObserver) {
    processDialogMutations(dialogObserver.takeRecords());
  }
  for (let i = openDialogStack.length - 1; i >= 0; i--) {
    const d = openDialogStack[i];
    if (isModalDialog(d)) return d;
    if (!d.isConnected || !d.open) {
      openDialogStack.splice(i, 1);
    }
  }
  const fallback = document.querySelectorAll<HTMLDialogElement>('dialog[open]');
  for (let i = fallback.length - 1; i >= 0; i--) {
    if (isModalDialog(fallback[i])) return fallback[i];
  }
  return undefined;
}

function mergeRefs<T>(
  ...refs: Array<React.Ref<T> | undefined>
): React.RefCallback<T> {
  let activeCleanups: Array<() => void> = [];
  const runCleanups = () => {
    const toRun = activeCleanups;
    activeCleanups = [];
    for (const cleanup of toRun) {
      cleanup();
    }
  };
  return (value: T | null) => {
    runCleanups();
    if (value === null) {
      return;
    }
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === 'function') {
        const cleanup = ref(value);
        if (typeof cleanup === 'function') {
          cleanups.push(cleanup);
        } else {
          cleanups.push(() => {
            ref(null);
          });
        }
      } else if (ref != null) {
        (ref as React.MutableRefObject<T | null>).current = value;
        cleanups.push(() => {
          (ref as React.MutableRefObject<T | null>).current = null;
        });
      }
    }
    activeCleanups = cleanups;
  };
}

interface DialogContextValue {
  open: boolean;
  setOpen: (next: boolean) => void;
  titleId: string;
  descId: string;
  hasDescription: boolean;
  setHasDescription: (present: boolean) => void;
  dialogRef: React.RefObject<HTMLDialogElement | null>;
  returnFocusRef: React.MutableRefObject<HTMLElement | null>;
  captureTrigger: (triggerEl: HTMLElement) => void;
  restoreFocus: () => void;
}

const DialogContext = React.createContext<DialogContextValue | null>(null);

function useDialogContext() {
  const ctx = React.useContext(DialogContext);
  if (!ctx) throw new Error('Dialog subcomponents must be used within <Dialog>');
  return ctx;
}

export interface DialogProps {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  children?: React.ReactNode;
}

export function Dialog({
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  children,
}: DialogProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState<boolean>(defaultOpen);
  const [hasDescription, setHasDescription] = React.useState<boolean>(false);
  const isControlled = controlledOpen !== undefined;
  const open = isControlled ? controlledOpen : uncontrolledOpen;
  const openRef = React.useRef<boolean>(open);
  openRef.current = open;
  const onOpenChangeRef = React.useRef(onOpenChange);
  onOpenChangeRef.current = onOpenChange;

  const dialogRef = React.useRef<HTMLDialogElement | null>(null);
  const returnFocusRef = React.useRef<HTMLElement | null>(null);
  const preOpenActiveRef = React.useRef<Element | null>(null);
  const triggerPreClickActiveRef = React.useRef<Element | null>(null);
  const clearPendingTriggerListenersRef = React.useRef<(() => void) | null>(null);
  const rawId = React.useId().replace(/:/g, '');
  const titleId = `f12-dlg-title-${rawId}`;
  const descId = `f12-dlg-desc-${rawId}`;

  const captureTrigger = React.useCallback((triggerEl: HTMLElement) => {
    clearPendingTriggerListenersRef.current?.();
    returnFocusRef.current = triggerEl;
    triggerPreClickActiveRef.current =
      typeof document !== 'undefined' ? document.activeElement : null;
    if (typeof document === 'undefined') return;
    const onOtherInteraction = (ev: Event) => {
      if (dialogRef.current?.open) {
        cleanup();
        return;
      }
      const target = ev.target as Node | null;
      if (target && !triggerEl.contains(target)) {
        if (returnFocusRef.current === triggerEl) {
          returnFocusRef.current = null;
          triggerPreClickActiveRef.current = null;
        }
        cleanup();
      }
    };
    const cleanup = () => {
      document.removeEventListener('pointerdown', onOtherInteraction, true);
      document.removeEventListener('keydown', onOtherInteraction, true);
      document.removeEventListener('focusin', onOtherInteraction, true);
      if (clearPendingTriggerListenersRef.current === cleanup) {
        clearPendingTriggerListenersRef.current = null;
      }
    };
    clearPendingTriggerListenersRef.current = cleanup;
    document.addEventListener('pointerdown', onOtherInteraction, true);
    document.addEventListener('keydown', onOtherInteraction, true);
    document.addEventListener('focusin', onOtherInteraction, true);
  }, []);

  React.useEffect(() => {
    return () => {
      clearPendingTriggerListenersRef.current?.();
    };
  }, []);

  const restoreFocus = React.useCallback(() => {
    clearPendingTriggerListenersRef.current?.();
    const opener = returnFocusRef.current;
    const preOpenActive = preOpenActiveRef.current;
    returnFocusRef.current = null;
    preOpenActiveRef.current = null;
    triggerPreClickActiveRef.current = null;
    if (!opener || !opener.isConnected || typeof opener.focus !== 'function') return;
    const active = typeof document !== 'undefined' ? document.activeElement : null;
    const el = dialogRef.current;
    // Note: In WebKit, pointer-clicking a <button> does not focus it, so native el.close()
    // restores whichever element was focused prior to opening (`preOpenActive`). Treating
    // `active === preOpenActive` as unhandled restores focus to `DialogTrigger` per WAI-ARIA
    // modal dialog guidance (if a consumer intentionally wants focus on `preOpenActive` on
    // close, they can focus it in a microtask/requestAnimationFrame after onOpenChange(false)).
    if (
      !active ||
      active === document.body ||
      active === document.documentElement ||
      active === preOpenActive ||
      (el && el.contains(active))
    ) {
      opener.focus({ preventScroll: true });
    }
  }, []);

  const setOpen = React.useCallback(
    (next: boolean) => {
      if (openRef.current === next) return;
      if (next && typeof document !== 'undefined') {
        preOpenActiveRef.current = document.activeElement;
        if (
          !returnFocusRef.current &&
          document.activeElement instanceof HTMLElement &&
          document.activeElement !== document.body &&
          document.activeElement !== document.documentElement &&
          (!dialogRef.current || !dialogRef.current.contains(document.activeElement))
        ) {
          returnFocusRef.current = document.activeElement;
        }
      }
      if (!isControlled) {
        openRef.current = next;
        setUncontrolledOpen(next);
      }
      onOpenChangeRef.current?.(next);
    },
    [isControlled],
  );

  React.useEffect(() => {
    ensureDialogObserver();
    const el = dialogRef.current;
    if (!el) {
      if (!open) restoreFocus();
      return;
    }
    if (open && !el.open) {
      clearPendingTriggerListenersRef.current?.();
      if (typeof document !== 'undefined') {
        const currentActive = document.activeElement;
        // Unconditionally capture document.activeElement immediately before showModal()
        // so controlled dialogs that open asynchronously always record the exact element
        // that native HTMLDialogElement.showModal() saves as its pre-open focus target.
        preOpenActiveRef.current = currentActive;
        if (
          returnFocusRef.current &&
          currentActive !== returnFocusRef.current &&
          currentActive !== triggerPreClickActiveRef.current
        ) {
          returnFocusRef.current = null;
          triggerPreClickActiveRef.current = null;
        }
        if (
          !returnFocusRef.current &&
          currentActive instanceof HTMLElement &&
          currentActive !== document.body &&
          currentActive !== document.documentElement &&
          !el.contains(currentActive)
        ) {
          returnFocusRef.current = currentActive;
        }
      }
      if (typeof el.showModal === 'function') el.showModal();
      else el.setAttribute('open', '');
      pushOpenDialog(el);
    } else if (open && el.open) {
      pushOpenDialog(el);
    } else if (!open && el.open) {
      removeOpenDialog(el);
      if (typeof el.close === 'function') el.close();
      else el.removeAttribute('open');
      restoreFocus();
    } else {
      removeOpenDialog(el);
    }
  }, [open, restoreFocus]);

  return (
    <DialogContext.Provider
      value={{
        open,
        setOpen,
        titleId,
        descId,
        hasDescription,
        setHasDescription,
        dialogRef,
        returnFocusRef,
        captureTrigger,
        restoreFocus,
      }}
    >
      {children}
    </DialogContext.Provider>
  );
}

export interface DialogTriggerProps extends ButtonProps {
  asChild?: boolean;
}

function getElementRef(element: React.ReactElement): React.Ref<unknown> | undefined {
  const propsObj = (element.props || {}) as Record<string, unknown>;
  let getter = Object.getOwnPropertyDescriptor(propsObj, 'ref')?.get;
  let mayWarn =
    getter && 'isReactWarning' in getter && (getter as { isReactWarning?: boolean }).isReactWarning;
  if (mayWarn) {
    return (element as unknown as { ref?: React.Ref<unknown> }).ref;
  }
  getter = Object.getOwnPropertyDescriptor(element, 'ref')?.get;
  mayWarn =
    getter && 'isReactWarning' in getter && (getter as { isReactWarning?: boolean }).isReactWarning;
  if (mayWarn) {
    return (propsObj as { ref?: React.Ref<unknown> }).ref;
  }
  return (
    (propsObj as { ref?: React.Ref<unknown> }).ref ||
    (element as unknown as { ref?: React.Ref<unknown> }).ref
  );
}

export const DialogTrigger = React.forwardRef<HTMLButtonElement, DialogTriggerProps>(
  function DialogTrigger(
    { asChild = false, onClick, className = '', children, ...rest },
    forwardedRef,
  ) {
    const { setOpen, captureTrigger } = useDialogContext();
    const childRef = React.isValidElement(children) ? getElementRef(children) : undefined;
    const composedRef = React.useMemo(
      () => mergeRefs(forwardedRef, childRef),
      [forwardedRef, childRef],
    );
    if (asChild && React.isValidElement(children)) {
      const child = children as React.ReactElement<Record<string, unknown>>;
      const childProps = child.props || {};
      const mergedClassName =
        [childProps.className, className].filter(Boolean).join(' ') || undefined;
      return React.cloneElement(child, {
        ...rest,
        ...childProps,
        className: mergedClassName,
        ref: composedRef,
        onClick: (e: React.MouseEvent<HTMLButtonElement>) => {
          onClick?.(e);
          if (typeof childProps.onClick === 'function') {
            (childProps.onClick as (ev: React.MouseEvent<HTMLButtonElement>) => void)(e);
          }
          if (!e.defaultPrevented) {
            if (e.currentTarget instanceof HTMLElement) {
              captureTrigger(e.currentTarget);
            }
            setOpen(true);
          }
        },
      });
    }
    return (
      <Button
        ref={forwardedRef}
        className={className}
        onClick={(e) => {
          onClick?.(e);
          if (!e.defaultPrevented) {
            if (e.currentTarget instanceof HTMLElement) {
              captureTrigger(e.currentTarget);
            }
            setOpen(true);
          }
        }}
        {...rest}
      >
        {children}
      </Button>
    );
  },
);

export interface DialogContentProps extends React.DialogHTMLAttributes<HTMLDialogElement> {
  cut?: string;
}

export const DialogContent = React.forwardRef<HTMLDialogElement, DialogContentProps>(
  function DialogContent(
    {
      cut,
      className = '',
      onPointerDown,
      onPointerUp,
      onCancel,
      onKeyDown,
      'aria-describedby': userDescribedBy,
      children,
      ...rest
    },
    forwardedRef,
  ) {
    const { setOpen, titleId, descId, hasDescription, dialogRef, restoreFocus } =
      useDialogContext();
    const pressedOutside = React.useRef<boolean>(false);
    const childPopupOpenOnEscapeRef = React.useRef<boolean>(false);

    React.useEffect(() => {
      const el = dialogRef.current;
      if (!el) return;
      const onClose = () => {
        removeOpenDialog(el);
        setOpen(false);
        restoreFocus();
      };
      // Capture Escape keydown at document capture phase BEFORE Radix DismissableLayer
      // unmounts the open listbox/menu, so we know whether Escape was consumed by a child popup.
      const onDocKeyDownCapture = (e: KeyboardEvent) => {
        if (e.key !== 'Escape') return;
        if (el.querySelector('[role="listbox"], [role="menu"]')) {
          childPopupOpenOnEscapeRef.current = true;
          setTimeout(() => {
            childPopupOpenOnEscapeRef.current = false;
          }, 0);
        }
      };
      const onDocKeyDown = (e: KeyboardEvent) => {
        if (e.key !== 'Escape' || !el.open) return;
        if (getTopmostOpenDialog() !== el) {
          return;
        }
        if (
          e.defaultPrevented ||
          childPopupOpenOnEscapeRef.current ||
          el.querySelector('[role="listbox"], [role="menu"]')
        ) {
          return;
        }
        e.preventDefault();
        const cancelEvent = new Event('cancel', { bubbles: false, cancelable: true });
        const shouldClose = el.dispatchEvent(cancelEvent);
        if (!shouldClose || cancelEvent.defaultPrevented) {
          return;
        }
        removeOpenDialog(el);
        el.close();
        setOpen(false);
        restoreFocus();
      };
      el.addEventListener('close', onClose);
      document.addEventListener('keydown', onDocKeyDownCapture, true);
      document.addEventListener('keydown', onDocKeyDown);
      return () => {
        if (!el.open || !el.isConnected) {
          removeOpenDialog(el);
        }
        el.removeEventListener('close', onClose);
        document.removeEventListener('keydown', onDocKeyDownCapture, true);
        document.removeEventListener('keydown', onDocKeyDown);
      };
    }, [dialogRef, setOpen, restoreFocus]);

    // Fallback for browsers where <dialog closedby="any"> is not yet supported:
    // test pointer coordinates against the dialog bounding box on pointerdown + pointerup.
    const isOutside = (e: React.PointerEvent<HTMLDialogElement>, dialog: HTMLDialogElement) => {
      const r = dialog.getBoundingClientRect();
      return (
        e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom
      );
    };

    const resolvedDescribedBy = userDescribedBy ?? (hasDescription ? descId : undefined);
    const composedDialogRef = React.useMemo(
      () => mergeRefs(dialogRef, forwardedRef),
      [dialogRef, forwardedRef],
    );

    return (
      <dialog
        ref={composedDialogRef}
        className={`f12-dialog${className ? ` ${className}` : ''}`}
        aria-labelledby={titleId}
        aria-describedby={resolvedDescribedBy}
        onKeyDown={(e) => {
          onKeyDown?.(e);
          if (e.key === 'Escape' && childPopupOpenOnEscapeRef.current) {
            e.preventDefault();
          }
        }}
        onCancel={(e) => {
          onCancel?.(e);
          if (
            childPopupOpenOnEscapeRef.current ||
            dialogRef.current?.querySelector('[role="listbox"], [role="menu"]')
          ) {
            e.preventDefault();
            childPopupOpenOnEscapeRef.current = false;
          }
        }}
        onPointerDown={(e) => {
          onPointerDown?.(e);
          if (e.defaultPrevented) return;
          const el = dialogRef.current;
          if (!el || el.querySelector('[role="listbox"], [role="menu"]')) {
            pressedOutside.current = false;
            return;
          }
          pressedOutside.current = e.target === el && isOutside(e, el);
        }}
        onPointerUp={(e) => {
          onPointerUp?.(e);
          if (e.defaultPrevented) {
            pressedOutside.current = false;
            return;
          }
          const el = dialogRef.current;
          if (el && pressedOutside.current && e.target === el && isOutside(e, el)) {
            el.close();
            setOpen(false);
            restoreFocus();
          }
          pressedOutside.current = false;
        }}
        {...rest}
      >
        {cut && (
          <span className="f12-cut" aria-hidden="true">
            {cut}
          </span>
        )}
        {children}
      </dialog>
    );
  },
);

export function DialogHeader({
  className = '',
  children,
  ...rest
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={`f12-dialog-header${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  );
}

export function DialogTitle({
  className = '',
  children,
  ...rest
}: React.HTMLAttributes<HTMLHeadingElement>) {
  const { titleId } = useDialogContext();
  return (
    <h2 id={titleId} className={`f12-dialog-title${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </h2>
  );
}

export function DialogDescription({
  className = '',
  children,
  ...rest
}: React.HTMLAttributes<HTMLParagraphElement>) {
  const { descId, setHasDescription } = useDialogContext();
  useIsoLayoutEffect(() => {
    setHasDescription(true);
    return () => setHasDescription(false);
  }, [setHasDescription]);

  return (
    <p
      id={descId}
      className={`f12-dialog-description${className ? ` ${className}` : ''}`}
      {...rest}
    >
      {children}
    </p>
  );
}

export function DialogFooter({
  className = '',
  children,
  ...rest
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={`f12-dialog-footer${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  );
}

export function DialogClose({ onClick, children, ...rest }: ButtonProps) {
  const { setOpen } = useDialogContext();
  return (
    <Button
      onClick={(e) => {
        onClick?.(e);
        if (!e.defaultPrevented) {
          setOpen(false);
        }
      }}
      {...rest}
    >
      {children}
    </Button>
  );
}

'use client';

import * as React from 'react';
import * as SelectPrimitive from '@radix-ui/react-select';

interface SelectFieldContextValue {
  instanceId: string;
  triggerId: string;
  containerEl: HTMLDivElement | null;
  describedBy?: string;
  invalid?: boolean;
}

const SelectFieldContext = React.createContext<SelectFieldContextValue | null>(null);

interface OuterFieldContextShape {
  id: string;
  labelId?: string;
  describedBy?: string;
  invalid?: boolean;
  disabled?: boolean;
  required?: boolean;
  density: 'comfortable' | 'compact';
  isControlGroup?: boolean;
  registerControlId?: (instanceId: string, explicitId?: string) => (() => void) | void;
}

const FIELD_CTX_KEY = Symbol.for('frame12.FieldContext');
const globalFieldRegistry = globalThis as unknown as Record<
  symbol,
  React.Context<OuterFieldContextShape | null> | undefined
>;
const OuterFieldContext = (globalFieldRegistry[FIELD_CTX_KEY] ??=
  React.createContext<OuterFieldContextShape | null>(null));

export type SelectDensity = 'comfortable' | 'compact';

export interface SelectProps
  extends React.ComponentPropsWithoutRef<typeof SelectPrimitive.Root> {
  label?: string;
  id?: string;
  density?: SelectDensity;
  className?: string;
}

export function Select({
  value,
  defaultValue,
  onValueChange,
  open,
  defaultOpen,
  onOpenChange,
  dir,
  name,
  autoComplete,
  disabled,
  required,
  form,
  label,
  id,
  density,
  className = '',
  children,
}: SelectProps) {
  const outerField = React.useContext(OuterFieldContext);
  const [containerEl, setContainerEl] = React.useState<HTMLDivElement | null>(null);
  const rawId = React.useId().replace(/:/g, '');
  const triggerId =
    id || (!outerField?.isControlGroup ? outerField?.id : undefined) || `f12-select-${rawId}`;
  const effectiveDensity: SelectDensity = density ?? outerField?.density ?? 'comfortable';
  const isCompact = effectiveDensity === 'compact';
  const effectiveDisabled = disabled ?? outerField?.disabled;
  const effectiveRequired = required ?? outerField?.required;
  const showOwnLabel = Boolean(label && (!outerField?.labelId || outerField?.isControlGroup));

  const registerControlId = outerField?.registerControlId;
  React.useEffect(() => {
    const cleanup = registerControlId?.(rawId, id);
    return typeof cleanup === 'function' ? cleanup : undefined;
  }, [registerControlId, rawId, id]);

  const ctxValue = React.useMemo(
    () => ({
      instanceId: rawId,
      triggerId,
      containerEl,
      describedBy: outerField?.describedBy,
      invalid: outerField?.invalid,
    }),
    [rawId, triggerId, containerEl, outerField?.describedBy, outerField?.invalid],
  );

  return (
    <SelectFieldContext.Provider value={ctxValue}>
      <div
        ref={setContainerEl}
        className={`f12-select${isCompact ? ' f12-select-compact' : ''}${className ? ` ${className}` : ''}`}
        data-density={isCompact ? 'compact' : undefined}
      >
        {showOwnLabel && (
          <label htmlFor={triggerId} className="f12-label">
            {label}
          </label>
        )}
        <SelectPrimitive.Root
          value={value}
          defaultValue={defaultValue}
          onValueChange={onValueChange}
          open={open}
          defaultOpen={defaultOpen}
          onOpenChange={onOpenChange}
          dir={dir}
          name={name}
          autoComplete={autoComplete}
          disabled={effectiveDisabled}
          required={effectiveRequired}
          form={form}
        >
          {children}
        </SelectPrimitive.Root>
      </div>
    </SelectFieldContext.Provider>
  );
}

