export interface TempoProviderProps {
  /** Controlled tempo. Pair with `onChange`. Wins over `defaultValue` (with a development warning). */
  value?: Tempo;
  /** Called with the new tempo whenever a TempoControl (or `setTempo`) inside changes it. */
  onChange?: (tempo: Tempo) => void;
  /** Uncontrolled starting tempo. Server render and first client render use it (or `auto`). */
  defaultValue?: Tempo;
  /** Uncontrolled only: persists the tempo in `localStorage` under this key and syncs across tabs. */
  storageKey?: string;
  /** Puts the `data-f12-tempo` attribute and motion class on the single child element instead of a wrapper. */
  asChild?: boolean;
  children?: React.ReactNode;
}

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;

// Bundlers (Next.js, webpack, Vite) statically replace `process.env.NODE_ENV`. Declared locally so
// browser-only TypeScript consumers without @types/node still compile (as in panel.tsx).
declare const process: { env: { NODE_ENV?: string } };

const isDev = (): boolean => {
  try {
    return process.env.NODE_ENV !== 'production';
  } catch {
    return false;
  }
};

function readStored(key: string | undefined): Tempo | undefined {
  if (!key) return undefined;
  try {
    const raw = window.localStorage.getItem(key);
    return isTempo(raw) ? raw : undefined;
  } catch {
    return undefined;
  }
}

function writeStored(key: string | undefined, tempo: Tempo): void {
  if (!key) return;
  try {
    window.localStorage.setItem(key, tempo);
  } catch {
    // Storage can be full, disabled or blocked: the choice still applies for this page.
  }
}

/** Keeps `<html data-f12-tempo>` (set before first paint by the first-paint script) current. */
function syncDocumentTempo(tempo: Tempo): void {
  if (typeof document === 'undefined') return;
  const root = document.documentElement;
  if (root.hasAttribute('data-f12-tempo') && root.getAttribute('data-f12-tempo') !== tempo) {
    root.setAttribute('data-f12-tempo', tempo);
  }
}

/**
 * Provides the viewer's animation tempo to every FRAME/12 animation below it.
 *
 * - The nearest provider sets `twos`/`ones`/`auto` for its subtree; `still` from any ancestor
 *   propagates down and cannot be undone by a nested provider. OS reduced motion always applies.
 * - Renders a layout-neutral `<div style="display: contents">` (or, with `asChild`, decorates its
 *   one child) carrying `data-f12-tempo` and, when the tempo forces a mode, the matching
 *   `f12-m-*` class so CSS-only consumers follow it.
 */
export function TempoProvider({
  value,
  onChange,
  defaultValue,
  storageKey,
  asChild = false,
  children,
}: TempoProviderProps) {
  const parent = React.useContext(TempoContext);
  const reduced = useReducedMotion();
  const controlled = value !== undefined;

  const warnedRef = React.useRef(false);
  if (controlled && defaultValue !== undefined && !warnedRef.current && isDev()) {
    warnedRef.current = true;
    console.warn(
      'TempoProvider: both `value` and `defaultValue` were given. `value` wins; remove `defaultValue` (or `value` to make it uncontrolled).',
    );
  }

  const [internal, setInternal] = React.useState<Tempo>(() => normalizeTempo(defaultValue));
  // True once the persisted value has been read (set in the same batch as `internal`).
  const [loaded, setLoaded] = React.useState(false);

  // The server and the hydrating client render `defaultValue` (or `auto`); the stored choice is
  // read before the first paint, so there is no hydration mismatch and no flash of the default.
  useIsoLayoutEffect(() => {
    if (controlled || !storageKey) return;
    const stored = readStored(storageKey);
    if (stored) setInternal(stored);
    setLoaded(true);
    const onStorage = (e: StorageEvent) => {
      if (e.key !== null && e.key !== storageKey) return;
      setInternal(readStored(storageKey) ?? normalizeTempo(defaultValue));
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, [controlled, storageKey, defaultValue]);

  const tempo: Tempo = controlled ? normalizeTempo(value) : internal;

  // Only the outermost persisted provider owns the page-wide <html data-f12-tempo> (a nested
  // provider must not turn motion off for the whole page). It syncs only once the stored value has
  // been read: before that `tempo` still holds the default, and syncing would briefly flip a stored
  // `still` (already written by the first-paint script) back to `auto`.
  const ownsDocument = Boolean(storageKey) && !controlled && !parent.inProvider;
  useIsoLayoutEffect(() => {
    if (ownsDocument && loaded) syncDocumentTempo(tempo);
  }, [ownsDocument, loaded, tempo]);

  const onChangeRef = React.useRef(onChange);
  onChangeRef.current = onChange;

  const setTempo = React.useCallback(
    (next: Tempo) => {
      const t = normalizeTempo(next);
      if (!controlled) {
        setInternal(t);
        writeStored(storageKey, t);
      }
      onChangeRef.current?.(t);
    },
    [controlled, storageKey],
  );

  const ancestorStill = parent.ancestorStill || (parent.inProvider && parent.tempo === 'still');

  const ctx = React.useMemo<TempoContextValue>(
    () => ({ tempo, setTempo, ancestorStill, inProvider: true }),
    [tempo, setTempo, ancestorStill],
  );

  // The resolved mode for a context with no component base: `auto` adds no class.
  const forced =
    reduced || ancestorStill || tempo === 'still'
      ? 'cut'
      : tempo === 'twos'
        ? 'stepped'
        : tempo === 'ones'
          ? 'smooth'
          : null;
  const motionClass = forced ? `f12-m-${forced}` : '';

  let content: React.ReactElement;
  if (asChild) {
    const child = React.Children.only(children) as React.ReactElement<{
      className?: string;
      'data-f12-tempo'?: string;
    }>;
    const childClass = child.props.className ?? '';
    content = React.cloneElement(child, {
      className: [childClass, motionClass].filter(Boolean).join(' ') || undefined,
      'data-f12-tempo': tempo,
    });
  } else {
    content = (
      <div style={{ display: 'contents' }} data-f12-tempo={tempo} className={motionClass || undefined}>
        {children}
      </div>
    );
  }

  return <TempoContext.Provider value={ctx}>{content}</TempoContext.Provider>;
}

'use client';

import * as React from 'react';
import { TEMPOS, useTempo, type Tempo } from '@/hooks/use-tempo';

export interface TempoControlProps {
  /** Group label. Visually hidden unless `showLegend` is set. */
  legend?: string;
  /** Shows the legend visibly above the options. */
  showLegend?: boolean;
  /** Prefix for the radio ids (`${idPrefix}-auto`, `${idPrefix}-twos`, …). */
  idPrefix?: string;
  className?: string;
}

export const TEMPO_OPTIONS: ReadonlyArray<{ value: Tempo; label: string; unit: string; meaning: string }> = [
  { value: 'auto', label: 'AUTO', unit: 'own', meaning: "each component's own motion" },
  { value: 'twos', label: '12', unit: 'twos', meaning: 'on twos' },
  { value: 'ones', label: '60', unit: 'smooth', meaning: 'smooth' },
  { value: 'still', label: '0', unit: 'still', meaning: 'no motion' },
];

// Bundlers (Next.js, webpack, Vite) statically replace `process.env.NODE_ENV`. Declared locally so
// browser-only TypeScript consumers without @types/node still compile (as in panel.tsx).
declare const process: { env: { NODE_ENV?: string } };

const isDev = (): boolean => {
  try {
    return process.env.NODE_ENV !== 'production';
  } catch {
    return false;
  }
};

/**
 * The viewer's animation tempo as one native radio group: a `<fieldset>` + `<legend>` with four
 * radio inputs in the segmented appearance. Arrow keys move and select; Tab enters and leaves
 * the group as one stop. Must sit inside a TempoProvider; without one it renders disabled.
 */
export function TempoControl({
  legend = 'Animation tempo',
  showLegend = false,
  idPrefix,
  className = '',
}: TempoControlProps) {
  const { tempo, setTempo, inProvider, reduced, ancestorStill } = useTempo();
  const autoId = React.useId().replace(/:/g, '');
  const prefix = idPrefix ?? `f12-tempo-${autoId}`;
  const noteId = `${prefix}-note`;

  React.useEffect(() => {
    if (!inProvider && isDev()) {
      console.warn(
        'TempoControl: no TempoProvider above this control, so it is disabled. Wrap your app (or this section) in <TempoProvider>.',
      );
    }
  }, [inProvider]);

  // The OS (or an outer `still`) wins: show the effective state, keep the stored choice editable.
  // The reduced-motion note is always rendered inside a provider and shown by a
  // `prefers-reduced-motion` media query, so its space exists from first paint (the server cannot
  // know the OS setting; inserting it after hydration would shift the layout).
  const REDUCED_NOTE = '0 · your system setting. Your choice applies when your system allows motion.';
  const note = !inProvider
    ? 'Unavailable: no tempo provider on this page.'
    : ancestorStill && !reduced
      ? '0 · set for this whole page. Your choice applies when that allows motion.'
      : null;
  const describedBy = note || reduced ? noteId : undefined;

  return (
    <fieldset
      className={`f12-tempo${className ? ` ${className}` : ''}`}
      disabled={!inProvider}
      data-tempo={tempo}
      data-effective={!inProvider ? undefined : reduced || ancestorStill ? 'still' : tempo}
    >
      <legend className={showLegend ? 'f12-tempo-legend' : 'f12-sr-only'}>{legend}</legend>
      <div className="f12-rng f12-tempo-rng">
        {TEMPOS.map((value) => {
          const opt = TEMPO_OPTIONS.find((o) => o.value === value)!;
          const id = `${prefix}-${value}`;
          return (
            <label key={value} className="f12-rng-btn f12-tempo-opt" htmlFor={id}>
              <input
                id={id}
                className="f12-tempo-input"
                type="radio"
                name={prefix}
                value={value}
                checked={tempo === value}
                onChange={() => setTempo(value)}
                aria-describedby={describedBy}
              />
              <span className="f12-rng-n" aria-hidden="true">
                {opt.label}
              </span>
              <span className="f12-rng-u" aria-hidden="true">
                {opt.unit}
              </span>
              <span className="f12-sr-only">{`${opt.label}, ${opt.meaning}`}</span>
            </label>
          );
        })}
      </div>
      {note ? (
        <p className="f12-tempo-note" id={noteId}>
          {note}
        </p>
      ) : (
        <p className="f12-tempo-note f12-tempo-note-reduced" id={noteId}>
          {REDUCED_NOTE}
        </p>
      )}
    </fieldset>
  );
}

'use client';

import * as React from 'react';
import { flushSync } from 'react-dom';
import { useResolvedMotion } from '@/hooks/use-tempo';
import { useChanged } from '@/hooks/use-on-twos';
import {
  EXPOSURE_RATES,
  EXPOSURE_STATUS_WORDS,
  describeExposureFrame,
  formatElapsed,
  formatFrameNumber,
  formatGap,
  useExposure,
  type ExposureEntry,
  type ExposureFrame,
  type ExposurePlayingReason,
  type ExposureRate,
  type ExposureStatus,
  type ExposureTiming,
  type ExposureValueReason,
} from '@/hooks/use-exposure';
import { Panel } from './panel';
import { SegmentedControl } from './segmented-control';

export type {
  ExposureFrame,
  ExposureStatus,
  ExposureTiming,
  ExposureRate,
  ExposureValueReason,
  ExposurePlayingReason,
};
export type ExposureScrubberDensity = 'comfortable' | 'compact';
export type ExposureScrubberVariant = 'expressive' | 'quiet';

export interface ExposureScrubberProps {
  frames: readonly ExposureFrame[];
  label: string;
  renderFrame: (frame: ExposureFrame, index: number, ctx: { scrubbing: boolean; settled: boolean }) => React.ReactNode;
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string, info: { index: number; reason: 'keyboard' | 'pointer' | 'row' | 'marker' | 'cause' | 'playback' | 'data' }) => void;
  playing?: boolean;
  onPlayingChange?: (playing: boolean, reason: 'user' | 'end' | 'scrub' | 'hidden' | 'data' | 'tempo' | 'rejected') => void;
  timing?: 'even' | 'elapsed' | 'flipbook';
  rate?: 0.5 | 1 | 2 | 4;
  defaultRate?: 0.5 | 1 | 2 | 4;
  onRateChange?: (r: 0.5 | 1 | 2 | 4) => void;
  stepMs?: number;
  loop?: boolean;
  primaryMarker?: string;
  emptyState?: React.ReactNode;
  idPrefix?: string;
  density?: 'comfortable' | 'compact';
  variant?: 'expressive' | 'quiet';
  className?: string;
}

const TIMING_OPTIONS: ReadonlyArray<{ value: ExposureTiming; label: string; unit: string; meaning: string }> = [
  { value: 'even', label: 'EVEN', unit: 'read', meaning: 'one readable step per frame' },
  { value: 'elapsed', label: 'REAL', unit: 'rhythm', meaning: "the run's real rhythm" },
  { value: 'flipbook', label: 'FLIP', unit: '12/s', meaning: 'flipbook, 12 poses per second' },
];

const RATE_OPTIONS = EXPOSURE_RATES.map((r) => ({ value: r, label: `${r}×` }));

/** Shows "This frame couldn't be rendered" instead of a consumer `renderFrame` that throws. */
class FrameBoundary extends React.Component<
  { frameId: string; children: React.ReactNode },
  { failed: boolean }
> {
  state = { failed: false };
  static getDerivedStateFromError() {
    return { failed: true };
  }
  render() {
    if (this.state.failed) {
      return (
        <p className="f12-xs-error" role="note">
          This frame couldn&apos;t be rendered <span className="f12-xs-mono">({this.props.frameId})</span>
        </p>
      );
    }
    return this.props.children;
  }
}

/** Calls `renderFrame` inside the boundary (so a throw is caught there, not in the scrubber). */
function FrameSlot({
  render,
  frame,
  index,
  scrubbing,
  settled,
}: {
  render: ExposureScrubberProps['renderFrame'];
  frame: ExposureFrame;
  index: number;
  scrubbing: boolean;
  settled: boolean;
}) {
  return <>{render(frame, index, { scrubbing, settled })}</>;
}

/** The TIMING cell: hold ticks (even) or a log-scaled screentone bar (drawn by CSS ::before). */
function timingCell(entry: ExposureEntry, timing: ExposureTiming, maxGapMs: number): { style?: React.CSSProperties; text: string } {
  if (timing === 'even') return { style: { '--xs-h': entry.hold } as React.CSSProperties, text: `×${entry.hold}` };
  if (entry.gapMs === undefined || maxGapMs <= 0) return { text: '' };
  const w = Math.max(4, Math.round((Math.log1p(entry.gapMs) / Math.log1p(maxGapMs)) * 100));
  return { style: { '--xs-w': `${w}%` } as React.CSSProperties, text: formatGap(entry.gapMs) };
}

/** Status as a word; its glyph is CSS generated content with empty alt text (never color alone). */
function StatusWord({ status }: { status: ExposureStatus }) {
  return (
    <span className="f12-xs-st" data-s={status}>
      {EXPOSURE_STATUS_WORDS[status]}
    </span>
  );
}

interface RowProps {
  entry: ExposureEntry;
  total: number;
  current: boolean;
  primary: boolean;
  timing: ExposureTiming;
  maxGapMs: number;
  causeLabel: string | null;
}

/** One X-sheet row. Memoized and keyed by id: a frame change re-renders two rows. */
const ExposureRow = React.memo(function ExposureRow({
  entry,
  total,
  current,
  primary,
  timing,
  maxGapMs,
  causeLabel,
}: RowProps) {
  // Lean markup (≤ 400 bytes per row): cells are styled by position, not class.
  const t = timingCell(entry, timing, maxGapMs);
  return (
    <tr role="row" className="f12-xs-row" aria-current={current ? 'step' : undefined}>
      <td role="cell" className="f12-xs-f">
        <span className="f12-xs-fn">{formatFrameNumber(entry.index, total)}</span>
        {entry.elapsedMs !== undefined && <span>{formatElapsed(entry.elapsedMs)}</span>}
      </td>
      <td role="cell">
        <button
          type="button"
          className="f12-xs-btn"
          tabIndex={current ? 0 : -1}
          aria-current={current ? 'step' : undefined}
          data-i={entry.index}
        >
          {entry.label}
        </button>
        {entry.kind && <span className="f12-xs-k">{entry.kind}</span>}
        {entry.detail && <span className="f12-xs-d">{entry.detail}</span>}
      </td>
      <td role="cell" style={t.style}>
        {t.text}
      </td>
      <td role="cell">
        {entry.status && <StatusWord status={entry.status} />}
        {entry.marker && (
          <span className={primary ? 'f12-xs-mk f12-xs-mk-primary' : 'f12-xs-mk'}>
            <span aria-hidden="true">{primary ? '◆ ' : '◇ '}</span>
            {primary ? 'MARK' : 'mark'}
          </span>
        )}
        {causeLabel && (
          <span className="f12-xs-from">
            <span aria-hidden="true">↖ </span>
            <span className="f12-sr-only">led here from </span>
            {causeLabel}
          </span>
        )}
      </td>
    </tr>
  );
});

/** Rows per memoized chunk: a frame change reconciles at most two chunks, not the whole sheet. */
const CHUNK = 64;

interface ChunkProps {
  rows: readonly ExposureEntry[];
  total: number;
  /** The current index if it falls in this chunk, else -1 (so other chunks skip re-rendering). */
  current: number;
  primary: number;
  timing: ExposureTiming;
  maxGapMs: number;
}

const causeLabelOf = (entry: ExposureEntry, total: number): string | null => {
  if (entry.causes.length === 0) return null;
  const first = formatFrameNumber(entry.causes[0], total);
  return entry.causes.length > 1 ? `${first} +${entry.causes.length - 1}` : first;
};

/** A run of rows rendered as a fragment (no wrapper element: the table DOM is unchanged). */
const ExposureRowChunk = React.memo(function ExposureRowChunk({ rows, total, current, primary, timing, maxGapMs }: ChunkProps) {
  return (
    <>
      {rows.map((entry) => (
        <ExposureRow
          key={entry.key}
          entry={entry}
          total={total}
          current={entry.index === current}
          primary={entry.index === primary}
          timing={timing}
          maxGapMs={maxGapMs}
          causeLabel={causeLabelOf(entry, total)}
        />
      ))}
    </>
  );
});

/**
 * ExposureScrubber: reads a discrete history (an agent run, a CI pipeline, an incident) like an
 * animator's exposure sheet. A semantic X-sheet table (FRAME · ACTION · TIMING · MARK), a detail
 * panel for the current frame, and a native-range transport with three timing modes. Never
 * autoplays. Built on `useExposure`.
 */
export function ExposureScrubber({
  frames,
  label,
  renderFrame,
  value,
  defaultValue,
  onValueChange,
  playing,
  onPlayingChange,
  timing = 'even',
  rate,
  defaultRate,
  onRateChange,
  stepMs = 1000,
  loop = false,
  primaryMarker,
  emptyState,
  idPrefix,
  density = 'comfortable',
  variant = 'expressive',
  className = '',
}: ExposureScrubberProps) {
  const autoId = React.useId().replace(/:/g, '');
  const prefix = idPrefix ?? `f12-xs-${autoId}`;
  const ex = useExposure({
    frames,
    value,
    defaultValue,
    onValueChange,
    playing,
    onPlayingChange,
    timing,
    rate,
    defaultRate,
    onRateChange,
    stepMs,
    loop,
    primaryMarker,
    name: 'ExposureScrubber',
  });
  // Motion governs transitions only (row highlight, panel swap), never reading speed.
  const motion = useResolvedMotion('stepped');

  // Server render and first client render are identical (transport disabled with a note);
  // the transport comes alive after hydration.
  const [hydrated, setHydrated] = React.useState(false);
  React.useEffect(() => setHydrated(true), []);

  const tbodyRef = React.useRef<HTMLTableSectionElement | null>(null);
  const scrollRef = React.useRef<HTMLDivElement | null>(null);
  const [sheetOpen, setSheetOpen] = React.useState(true);

  const { count, index, entries } = ex;
  const chunks = React.useMemo(() => {
    const out: ExposureEntry[][] = [];
    for (let i = 0; i < entries.length; i += CHUNK) out.push(entries.slice(i, i + CHUNK));
    return out;
  }, [entries]);
  const n = count;
  const panelEntry = ex.panelIndex >= 0 ? entries[ex.panelIndex] : null;
  // The panel swap animates only after the first change: nothing moves on first paint.
  const swapped = useChanged(panelEntry?.key);
  const ready = hydrated && n > 0;
  const multi = ready && n > 1;
  const frameWord = n === 1 ? 'frame' : 'frames';

  // Keep the current row inside the sheet's own scroll box (never scrolls the page, never moves
  // focus). While flipping, page by whole screens so the sheet does not crawl.
  React.useEffect(() => {
    const box = scrollRef.current;
    if (!box || ex.scrubbing) return;
    const flipping = ex.flipping;
    // Off-screen rows use content-visibility placeholder heights; once rows near the target
    // render, real heights shift it. Re-check for a few frames (then stop: nothing runs idle).
    let raf = 0;
    let tries = 0;
    const fit = () => {
      const row = tbodyRef.current?.rows[index];
      if (!row) return;
      const head = box.querySelector('thead')?.getBoundingClientRect().height ?? 0;
      const r = row.getBoundingClientRect();
      const top = r.top - box.getBoundingClientRect().top + box.scrollTop;
      const bottom = top + r.height;
      let next = box.scrollTop;
      if (top - head < box.scrollTop) next = Math.max(0, top - head);
      else if (bottom > box.scrollTop + box.clientHeight) next = flipping ? top - head : bottom - box.clientHeight;
      if (Math.abs(next - box.scrollTop) >= 1) box.scrollTop = next;
      // rAF runs before the frame renders newly relevant rows, so keep checking a few frames.
      if (++tries < 6) raf = requestAnimationFrame(fit);
    };
    fit();
    return () => cancelAnimationFrame(raf);
  }, [index, ex.flipping, ex.scrubbing]);

  // ------------------------------------------------------------------ pointer drag (FRAME column)
  const dragRef = React.useRef<{ id: number } | null>(null);
  const indexAtY = (y: number): number => {
    const rows = tbodyRef.current?.rows;
    if (!rows || rows.length === 0) return -1;
    if (y < rows[0].getBoundingClientRect().top) return 0;
    let lo = 0;
    let hi = rows.length - 1;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (rows[mid].getBoundingClientRect().top <= y) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  };
  const endDrag = () => {
    if (!dragRef.current) return;
    dragRef.current = null;
    ex.endPointerScrub();
  };

  const onBodyPointerDown = (e: React.PointerEvent<HTMLTableSectionElement>) => {
    if (!ready || e.button !== 0) return;
    const cell = (e.target as Element).closest('.f12-xs-f');
    if (!cell) return;
    e.preventDefault();
    try {
      e.currentTarget.setPointerCapture(e.pointerId);
    } catch {
      /* capture is best-effort */
    }
    dragRef.current = { id: e.pointerId };
    ex.beginPointerScrub();
    const i = indexAtY(e.clientY);
    if (i >= 0) ex.select(i, 'pointer');
  };
  const onBodyPointerMove = (e: React.PointerEvent<HTMLTableSectionElement>) => {
    if (!dragRef.current || dragRef.current.id !== e.pointerId) return;
    const i = indexAtY(e.clientY);
    // Immediate: the frame changes in the same task as the input event.
    if (i >= 0) flushSync(() => ex.select(i, 'pointer'));
  };

  const onBodyClick = (e: React.MouseEvent<HTMLTableSectionElement>) => {
    const btn = (e.target as Element).closest<HTMLButtonElement>('.f12-xs-btn');
    if (!btn || !ready) return;
    const i = Number(btn.dataset.i);
    // A click that follows a key (Enter/Space) is a keyboard selection.
    ex.select(i, e.detail === 0 ? 'keyboard' : 'row');
    ex.announceSettled();
  };
  const onBodyKeyDown = (e: React.KeyboardEvent<HTMLTableSectionElement>) => {
    if (!ready || e.altKey || e.ctrlKey || e.metaKey || e.shiftKey) return;
    const btn = (e.target as Element).closest<HTMLButtonElement>('.f12-xs-btn');
    if (!btn) return;
    // From the live current frame (j/k or playback may have moved it away from the focused row).
    const target = ex.rowKeyTarget(e.key, index);
    if (target === null) return;
    e.preventDefault();
    ex.select(target, 'keyboard');
    ex.noteKeyScrub();
    tbodyRef.current?.rows[target]?.querySelector<HTMLButtonElement>('.f12-xs-btn')?.focus();
  };

  // ------------------------------------------------------------------ range
  const rangePointer = React.useRef(false);
  const onRangeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const v = Number(e.currentTarget.value) - 1;
    if (rangePointer.current) {
      ex.select(v, 'pointer');
      return;
    }
    // Keys move relative to the live playhead (while flipping, the range shows the frozen
    // start frame, so an absolute value would jump back to it).
    ex.select(index + (v - displayIndex), 'keyboard');
    ex.noteKeyScrub();
  };
  // Native ranges page by 10% of the range in some engines; the contract is ±10 frames.
  const onRangeKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.altKey || e.ctrlKey || e.metaKey || e.shiftKey) return;
    // Home/End are absolute (also while flipping, when the range shows the frozen start frame).
    if (e.key === 'Home' || e.key === 'End') {
      e.preventDefault();
      ex.select(e.key === 'Home' ? 0 : n - 1, 'keyboard');
      ex.noteKeyScrub();
      return;
    }
    if (e.key !== 'PageUp' && e.key !== 'PageDown') return;
    e.preventDefault();
    ex.step(e.key === 'PageUp' ? 10 : -10, 'keyboard');
    ex.noteKeyScrub();
  };
  const onRangePointerDown = (e: React.PointerEvent<HTMLInputElement>) => {
    if (e.button !== 0) return;
    rangePointer.current = true;
    try {
      e.currentTarget.setPointerCapture(e.pointerId);
    } catch {
      /* capture is best-effort */
    }
    ex.beginPointerScrub();
  };
  const onRangePointerEnd = () => {
    if (!rangePointer.current) return;
    rangePointer.current = false;
    ex.endPointerScrub();
  };

  // ------------------------------------------------------------------ transport steps
  // Step buttons stay focusable at the ends (aria-disabled, not disabled), so focus is never
  // dropped to <body> when a press reaches the first or last frame.
  const stepBy = (delta: number, e: React.MouseEvent<HTMLButtonElement>) => {
    if (e.currentTarget.getAttribute('aria-disabled') === 'true') return;
    const keyboard = e.detail === 0;
    ex.step(delta, keyboard ? 'keyboard' : 'pointer');
    if (keyboard) ex.noteKeyScrub();
    else ex.announceSettled();
  };
  const contentKeys = React.useRef<WeakSet<Event>>(new WeakSet());
  // After following a cause (or going back) the activated button unmounts; move focus to the
  // frame title instead of losing it. A counter (not a flag) so every request is consumed in
  // the commit it causes, even when the frame does not change, and never fires later.
  const [focusRequest, setFocusRequest] = React.useState(0);
  React.useEffect(() => {
    if (focusRequest === 0) return;
    document.getElementById(`${prefix}-title`)?.focus();
  }, [focusRequest, prefix]);
  const markStep = (direction: 1 | -1, e: React.MouseEvent<HTMLButtonElement>) => {
    if (e.currentTarget.getAttribute('aria-disabled') === 'true') return;
    ex.stepMarker(direction, e.detail === 0 ? 'keyboard' : 'pointer');
  };

  // ------------------------------------------------------------------ shortcuts (scoped)
  const onRootKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!ready || e.defaultPrevented) return;
    // Keys from consumer content never reach the shortcuts, including content portalled out of
    // the DOM subtree (React events still bubble through the portal to here).
    if (contentKeys.current.has(e.nativeEvent)) return;
    if (!(e.currentTarget as Node).contains(e.target as Node)) return;
    if ((e.target as Element).closest('[data-exposure-content]')) return;
    if (ex.handleShortcut(e)) e.preventDefault();
  };

  const displayIndex = ex.flipping ? ex.panelIndex : index;
  const displayEntry = displayIndex >= 0 ? entries[displayIndex] : null;
  const frameNo = (i: number) => formatFrameNumber(i, n);
  const timingHeader =
    ex.timing === 'even' ? 'hold ×1–12' : ex.hasTiming ? `log · max ${formatGap(ex.maxGapMs)}` : 'no timing data';

  const transportNote = !hydrated
    ? 'Replay needs JavaScript'
    : n === 0
      ? 'Nothing to replay: there are no frames.'
      : !ex.flipbookAvailable
        ? 'Flipbook needs motion: reduced motion or a still tempo is on.'
        : null;
  const noteId = `${prefix}-note`;

  const rootClass = [
    'f12-xs',
    `f12-m-${motion}`,
    density === 'compact' ? 'f12-xs-compact' : '',
    variant === 'quiet' ? 'f12-xs-quiet' : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div
      className={rootClass}
      id={prefix}
      data-density={density}
      data-variant={variant}
      data-timing={ex.timing}
      data-playing={ex.playing ? 'true' : undefined}
      data-flipping={ex.flipping ? 'true' : undefined}
      onKeyDown={onRootKeyDown}
    >
      <div className="f12-xs-grid">
        {/* 1 · Transport (first in tab order) */}
        <fieldset className="f12-xs-transport" disabled={!ready} aria-describedby={transportNote ? noteId : undefined}>
          <legend className="f12-sr-only">{`${label}: replay controls`}</legend>
          <div className="f12-xs-tr-row">
            <button
              type="button"
              className="f12-xs-tbtn"
              id={`${prefix}-prev`}
              aria-disabled={!multi || index <= 0}
              onClick={(e) => stepBy(-1, e)}
            >
              <span aria-hidden="true">‹ </span>Prev
            </button>
            <button
              type="button"
              className="f12-xs-tbtn f12-xs-play"
              id={`${prefix}-play`}
              aria-pressed={ex.playing}
              disabled={!multi}
              onClick={ex.toggle}
            >
              <span className="f12-xs-play-glyph" aria-hidden="true">
                {ex.playing ? '❚❚' : '▶'}
              </span>
              Play
            </button>
            <button
              type="button"
              className="f12-xs-tbtn"
              id={`${prefix}-next`}
              aria-disabled={!multi || index >= n - 1}
              onClick={(e) => stepBy(1, e)}
            >
              Next<span aria-hidden="true"> ›</span>
            </button>
            {n > 1 ? (
              <input
                type="range"
                className="f12-xs-range"
                id={`${prefix}-range`}
                min={1}
                max={n}
                step={1}
                value={displayIndex + 1}
                aria-label="Playhead"
                aria-valuetext={displayEntry ? describeExposureFrame(displayEntry, n) : undefined}
                onChange={onRangeChange}
                onKeyDown={onRangeKeyDown}
                onPointerDown={onRangePointerDown}
                onPointerUp={onRangePointerEnd}
                onPointerCancel={onRangePointerEnd}
                onLostPointerCapture={onRangePointerEnd}
              />
            ) : (
              <span className="f12-xs-one">{n === 1 ? '1 frame' : '0 frames'}</span>
            )}
            <span className="f12-xs-count" aria-hidden="true">
              {n > 0 ? `${displayIndex + 1} / ${n}` : '0 / 0'}
            </span>
          </div>
          <div className="f12-xs-tr-row">
            <button
              type="button"
              className="f12-xs-tbtn"
              id={`${prefix}-prev-mark`}
              aria-disabled={!multi || !ex.markers.some((m) => m < index)}
              onClick={(e) => markStep(-1, e)}
            >
              <span aria-hidden="true">‹◆ </span>Prev mark
            </button>
            <button
              type="button"
              className="f12-xs-tbtn"
              id={`${prefix}-next-mark`}
              aria-disabled={!multi || !ex.markers.some((m) => m > index)}
              onClick={(e) => markStep(1, e)}
            >
              Next mark<span aria-hidden="true"> ◆›</span>
            </button>
            <SegmentedControl
              options={RATE_OPTIONS}
              value={ex.rate}
              onChange={(r) => ex.setRate(r as ExposureRate)}
              ariaLabel="Playback rate"
              idPrefix={`${prefix}-rate`}
              className="f12-xs-rate"
            />
            <fieldset className="f12-tempo f12-xs-timing" disabled={!multi}>
              <legend className="f12-sr-only">Timing</legend>
              <div className="f12-rng f12-tempo-rng">
                {TIMING_OPTIONS.map((opt) => {
                  const id = `${prefix}-timing-${opt.value}`;
                  const unavailable = opt.value === 'flipbook' && !ex.flipbookAvailable;
                  return (
                    <label key={opt.value} className="f12-rng-btn f12-tempo-opt" htmlFor={id} data-unavailable={unavailable ? 'true' : undefined}>
                      <input
                        id={id}
                        className="f12-tempo-input"
                        type="radio"
                        name={`${prefix}-timing`}
                        value={opt.value}
                        checked={ex.requestedTiming === opt.value}
                        disabled={unavailable}
                        aria-describedby={unavailable ? noteId : undefined}
                        onChange={() => ex.setTiming(opt.value)}
                      />
                      <span className="f12-rng-n" aria-hidden="true">
                        {opt.label}
                      </span>
                      <span className="f12-rng-u" aria-hidden="true">
                        {opt.unit}
                      </span>
                      <span className="f12-sr-only">{`${opt.label} ${opt.unit}, ${opt.meaning}`}</span>
                    </label>
                  );
                })}
              </div>
            </fieldset>
          </div>
          {transportNote && (
            <p className="f12-xs-note" id={noteId}>
              {transportNote}
            </p>
          )}
        </fieldset>

        {/* 2 · The exposure sheet (one roving tab stop) */}
        {n > 0 && (
          <details
            className="f12-xs-disc"
            open={sheetOpen}
            onToggle={(e) => setSheetOpen(e.currentTarget.open)}
          >
            <summary className="f12-xs-sum">{`Exposure sheet · ${n} ${frameWord}`}</summary>
            <div className="f12-xs-scroll" ref={scrollRef}>
              <table role="table" className="f12-xs-sheet">
                <caption className="f12-xs-cap">{`${label} · ${n} ${frameWord}`}</caption>
                <thead role="rowgroup">
                  <tr role="row" className="f12-xs-hrow">
                    <th role="columnheader" scope="col">FRAME</th>
                    <th role="columnheader" scope="col">ACTION</th>
                    <th role="columnheader" scope="col">
                      TIMING <span className="f12-xs-sc">{timingHeader}</span>
                    </th>
                    <th role="columnheader" scope="col">MARK</th>
                  </tr>
                </thead>
                <tbody
                  role="rowgroup"
                  ref={tbodyRef}
                  onClick={onBodyClick}
                  onKeyDown={onBodyKeyDown}
                  onPointerDown={onBodyPointerDown}
                  onPointerMove={onBodyPointerMove}
                  onPointerUp={endDrag}
                  onPointerCancel={endDrag}
                  onLostPointerCapture={endDrag}
                >
                  {chunks.map((rows) => {
                    const start = rows[0].index;
                    const end = start + rows.length;
                    return (
                      <ExposureRowChunk
                        key={start}
                        rows={rows}
                        total={n}
                        current={index >= start && index < end ? index : -1}
                        primary={ex.primaryMarkerIndex >= start && ex.primaryMarkerIndex < end ? ex.primaryMarkerIndex : -1}
                        timing={ex.timing}
                        maxGapMs={ex.maxGapMs}
                      />
                    );
                  })}
                </tbody>
              </table>
            </div>
          </details>
        )}

        {/* 3 · The detail panel */}
        <Panel
          className="f12-xs-panel"
          label={`${label}: current frame`}
          variant={variant}
          cut={false}
        >
          <span className="f12-cut f12-xs-cut" aria-hidden="true">
            {ex.flipping ? 'CURRENT CUT / FLIPPING' : panelEntry ? `CURRENT CUT / ${frameNo(panelEntry.index)}` : 'CURRENT CUT / —'}
          </span>
          {n === 0 ? (
            <div className="f12-xs-empty">
              {emptyState ?? (
                <p className="f12-xs-empty-msg">
                  <span className="f12-xs-mono" aria-hidden="true">[ ∅ ] </span>
                  No frames yet. A run with steps will appear here as an exposure sheet.
                </p>
              )}
            </div>
          ) : panelEntry ? (
            // The body and header persist across frames (a focused title survives j/k); only the
            // consumer content is keyed per frame (fresh error boundary, swap transition).
            <div className="f12-xs-body">
              <div className="f12-xs-head">
                <p className="f12-xs-pos">
                  <span className="f12-xs-pnum">{frameNo(panelEntry.index)}</span>
                  {panelEntry.elapsedMs !== undefined && (
                    <span className="f12-xs-pel">{formatElapsed(panelEntry.elapsedMs)}</span>
                  )}
                  {panelEntry.kind && <span className="f12-xs-k">{panelEntry.kind}</span>}
                </p>
                <p className="f12-xs-title" id={`${prefix}-title`} tabIndex={-1}>
                  {panelEntry.label}
                </p>
                {(panelEntry.status || panelEntry.marker) && (
                  <p className="f12-xs-pmeta">
                    {panelEntry.status && <StatusWord status={panelEntry.status} />}
                    {panelEntry.marker && (
                      <span className={panelEntry.index === ex.primaryMarkerIndex ? 'f12-xs-mk f12-xs-mk-primary' : 'f12-xs-mk'}>
                        <span aria-hidden="true">{panelEntry.index === ex.primaryMarkerIndex ? '◆ ' : '◇ '}</span>
                        {panelEntry.index === ex.primaryMarkerIndex ? 'MARK' : 'mark'}
                      </span>
                    )}
                  </p>
                )}
              </div>
              {ex.flipping ? (
                // While flipping the header holds the frame where the flip started and the content
                // is a static slate: the panel does not update (and a focused title survives).
                <div className="f12-xs-slate">
                  <p className="f12-xs-slate-t">FLIPPING</p>
                  <p className="f12-xs-slate-s">
                    12 poses per second{ex.rate !== 1 ? ` × ${ex.rate}` : ''}. Watch the sheet&apos;s rhythm; pause to read a frame.
                  </p>
                </div>
              ) : (
                <>
                  <div
                    className="f12-xs-content"
                    key={panelEntry.key}
                    data-swap={swapped ? 'true' : undefined}
                    data-exposure-content=""
                    onKeyDown={(e) => {
                      contentKeys.current.add(e.nativeEvent);
                    }}
                  >
                    <FrameBoundary frameId={panelEntry.key}>
                      <FrameSlot
                        render={renderFrame}
                        frame={panelEntry.source}
                        index={panelEntry.index}
                        scrubbing={ex.scrubbing}
                        settled={ex.settled}
                      />
                    </FrameBoundary>
                  </div>
                  {(panelEntry.causes.length > 0 || ex.back) && (
                    <div className="f12-xs-links">
                      {panelEntry.causes.length > 0 && (
                        <>
                          <p className="f12-xs-links-h" id={`${prefix}-from`}>
                            Led here from
                          </p>
                          <ul className="f12-xs-links-l" aria-labelledby={`${prefix}-from`}>
                            {panelEntry.causes.map((ci) => (
                              <li key={entries[ci].key}>
                                <button
                                  type="button"
                                  className="f12-xs-tbtn f12-xs-cause"
                                  disabled={!ready}
                                  onClick={() => {
                                    ex.followCause(ci);
                                    setFocusRequest((r) => r + 1);
                                  }}
                                >
                                  {`${frameNo(ci)} · ${entries[ci].label}`}
                                </button>
                              </li>
                            ))}
                          </ul>
                        </>
                      )}
                      {ex.back && (
                        <button type="button" className="f12-xs-tbtn f12-xs-back" disabled={!ready} onClick={() => {
                            ex.goBack();
                            setFocusRequest((r) => r + 1);
                          }}>
                          <span aria-hidden="true">↩ </span>
                          {`Back to ${frameNo(ex.back.index)}`}
                        </button>
                      )}
                    </div>
                  )}
                </>
              )}
            </div>
          ) : null}
        </Panel>
      </div>
      <div className="f12-sr-only" role="status" aria-live="polite" aria-atomic="true">
        {ex.announcement}
      </div>
    </div>
  );
}

'use client';

import * as React from 'react';
import { flushSync } from 'react-dom';
import { useResolvedMotion } from '@/hooks/use-tempo';

/**
 * CutMorph: state changes as film edits, on the platform's View Transitions.
 *
 * - `match`: a match cut. The named subject keeps its identity from one shot to the next: its
 *   geometry moves on twos (or smooth at 60), its old and new images hard-swap at the geometric
 *   midpoint, never crossfade.
 * - `cut`: the shot changes instantly. No View Transition at all.
 *
 * Opt-in only. Calling `useCutMorph` is the opt-in; nothing in FRAME/12 animates through it by
 * default. The grammar lives in `frame12.css` (`f12-match`, `f12-cut`, `f12-vt-stepped`,
 * `f12-vt-smooth`), so React 19.3's `<ViewTransition>` can use it too (see `withCutMorphMode`).
 */
export type CutMorphKind = 'match' | 'cut';
/** The transition-scoped mode key: `stepped` (12, on twos) or `smooth` (60). */
export type CutMorphMode = 'stepped' | 'smooth';

export interface UseCutMorphOptions {
  /**
   * Run element-scoped transitions on this element where the engine supports
   * `Element.prototype.startViewTransition` (Chromium): the snapshots then scroll and clip with
   * it and the rest of the page is untouched. Elsewhere, a document transition with the root
   * excluded.
   */
  scope?: React.RefObject<HTMLElement | null>;
}

export interface CutMorphCallOptions {
  /** `match` (default) animates the named subjects; `cut` updates immediately. */
  kind?: CutMorphKind;
}

/**
 * Runs `update` (synchronous; it must not return a promise) exactly once, in call order. Resolves
 * once the edit is on screen; rejects only with what `update` threw.
 */
export type CutMorph = (update: () => void, opts?: CutMorphCallOptions) => Promise<void>;

export interface CutMorphNameProps {
  /** The `view-transition-name`: `^[a-z][a-z0-9-]{0,63}$`, from a stable data id (never an array index). */
  name: string;
  /** The `view-transition-class`: `f12-match` (default), `f12-cut`, or your own space-separated classes. */
  className?: 'f12-match' | string;
  /** One DOM host element, or a component that forwards `style` and `ref` to one. */
  children: React.ReactElement;
}

/** What the current engine supports (all false on the server). */
export interface CutMorphSupport {
  /** Same-document View Transitions with `view-transition-class`: CutMorph animates. */
  viewTransitions: boolean;
  /** `Element.prototype.startViewTransition`: `scope` runs element-scoped transitions. */
  elementScoped: boolean;
  /** `document.activeViewTransition`: transitions CutMorph does not own are detected and left alone. */
  activeViewTransition: boolean;
}

// Bundlers (Next.js, webpack, Vite) statically replace `process.env.NODE_ENV`. Declared locally so
// browser-only TypeScript consumers without @types/node still compile (as in panel.tsx).
declare const process: { env: { NODE_ENV?: string } };

// Development checks test `process.env.NODE_ENV` inline and unguarded, so a bundler's production
// define folds them away with their messages. Safe wherever React from npm runs: React's own
// entry point reads process.env.NODE_ENV unguarded too.

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;

interface VtLike {
  ready: Promise<unknown>;
  finished: Promise<unknown>;
  updateCallbackDone: Promise<unknown>;
  skipTransition(): void;
}
type VtStarter = { startViewTransition?: (cb: () => void) => VtLike };

interface CutMorphRecord {
  gen: number;
  root: Element;
  scoped: boolean;
  update: () => void;
  updateRan: boolean;
  error: { value: unknown } | null;
  vt: VtLike | null;
  hook: object;
  detach: () => void;
}

interface CutMorphOwner {
  version: 1;
  gen: number;
  /** Owned transitions in flight, oldest first. */
  active: CutMorphRecord[];
  /** Which generation set the mode class on a transition root. */
  classes: WeakMap<Element, { gen: number; cls: string }>;
  /** Development only: live CutMorphName registrations by name. */
  names: Map<string, Array<{ stack: string }>>;
}

const OWNER_KEY = Symbol.for('frame12.cutmorph');
const MODE_CLASS: Record<CutMorphMode, string> = {
  stepped: 'f12-vt-stepped',
  smooth: 'f12-vt-smooth',
};
const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

/** One owner per document, shared by every React root and every copied-in copy of this file. */
function getOwner(): CutMorphOwner {
  const g = globalThis as unknown as Record<symbol, CutMorphOwner | undefined>;
  let owner = g[OWNER_KEY];
  if (!owner) {
    owner = { version: 1, gen: 0, active: [], classes: new WeakMap(), names: new Map() };
    g[OWNER_KEY] = owner;
  }
  return owner;
}

function setModeClass(root: Element, cls: string, gen: number): void {
  const owner = getOwner();
  const prev = owner.classes.get(root);
  if (prev && prev.cls !== cls) root.classList.remove(prev.cls);
  root.classList.add(cls);
  owner.classes.set(root, { gen, cls });
}

/** Generation-guarded: a stale `finally` never strips a newer generation's class. */
function clearModeClass(root: Element, gen: number): void {
  const owner = getOwner();
  const cur = owner.classes.get(root);
  if (!cur || cur.gen !== gen) return;
  root.classList.remove(cur.cls);
  owner.classes.delete(root);
}

export function getCutMorphSupport(): CutMorphSupport {
  if (typeof document === 'undefined' || typeof window === 'undefined') {
    return { viewTransitions: false, elementScoped: false, activeViewTransition: false };
  }
  let classes = false;
  try {
    classes = typeof CSS !== 'undefined' && CSS.supports('view-transition-class', 'f12-match');
  } catch {
    classes = false;
  }
  const doc = document as unknown as VtStarter;
  return {
    viewTransitions: typeof doc.startViewTransition === 'function' && classes,
    elementScoped:
      typeof Element !== 'undefined' &&
      typeof (Element.prototype as unknown as VtStarter).startViewTransition === 'function',
    activeViewTransition: 'activeViewTransition' in document,
  };
}

function callUpdate(update: () => void): void {
  const result: unknown = update();
  if (
    process.env.NODE_ENV !== 'production' &&
    result != null &&
    typeof (result as { then?: unknown }).then === 'function'
  ) {
    console.warn(
      '[frame12] useCutMorph: `update` returned a promise. It must be synchronous: CutMorph snapshots the DOM right after it returns. Await your data first, then call the cut.',
    );
  }
}

/** Runs every owned update that has not run yet, oldest first, so call order is kept. */
function flushPending(owner: CutMorphOwner, sync: boolean): void {
  for (const rec of owner.active) {
    if (rec.updateRan) continue;
    rec.updateRan = true;
    try {
      if (sync) flushSync(() => callUpdate(rec.update));
      else callUpdate(rec.update);
    } catch (e) {
      rec.error = { value: e };
    }
  }
}

function skipOwned(owner: CutMorphOwner, keep: (rec: CutMorphRecord) => boolean): void {
  for (const rec of owner.active.slice()) {
    if (keep(rec)) continue;
    try {
      rec.vt?.skipTransition();
    } catch {
      /* already finished */
    }
  }
}

function finish(rec: CutMorphRecord): void {
  const owner = getOwner();
  const i = owner.active.indexOf(rec);
  if (i >= 0) owner.active.splice(i, 1);
  rec.detach();
  clearModeClass(rec.root, rec.gen);
}

function run(
  update: () => void,
  kind: CutMorphKind,
  mode: 'stepped' | 'smooth' | 'cut',
  scopeEl: HTMLElement | null,
  hook: object,
): Promise<void> {
  const owner = getOwner();
  const gen = ++owner.gen;

  const immediate = (): Promise<void> => {
    // Earlier edits first (exactly once, in order), then the latest edit supersedes them.
    flushPending(owner, false);
    skipOwned(owner, (rec) => rec.scoped && rec.root !== scopeEl);
    try {
      callUpdate(update);
      return Promise.resolve();
    } catch (e) {
      return Promise.reject(e);
    }
  };

  const support = getCutMorphSupport();
  if (
    kind === 'cut' ||
    mode === 'cut' ||
    !support.viewTransitions ||
    document.visibilityState === 'hidden'
  ) {
    return immediate();
  }
  // Never cancel a transition CutMorph does not own (React's <ViewTransition>, a router, the app).
  const current = (document as unknown as { activeViewTransition?: VtLike | null })
    .activeViewTransition;
  if (current && !owner.active.some((rec) => rec.vt === current)) return immediate();

  const scoped = !!scopeEl && support.elementScoped && scopeEl.isConnected;
  const root: Element = scoped ? (scopeEl as Element) : document.documentElement;

  flushPending(owner, true);
  // A new document transition supersedes every owned one; a scoped one supersedes the document
  // transition and any on the same scope. Scoped transitions on other scopes keep running.
  skipOwned(owner, (rec) => scoped && rec.scoped && rec.root !== root);

  const rec: CutMorphRecord = {
    gen,
    root,
    scoped,
    update,
    updateRan: false,
    error: null,
    vt: null,
    hook,
    detach: () => {},
  };
  const listeners: Array<() => void> = [];
  rec.detach = () => {
    for (const off of listeners.splice(0)) off();
  };

  setModeClass(root, MODE_CLASS[mode], gen);
  owner.active.push(rec);

  const onUpdate = () => {
    if (rec.updateRan) return;
    rec.updateRan = true;
    try {
      flushSync(() => callUpdate(update));
    } catch (e) {
      rec.error = { value: e };
      throw e;
    }
  };

  let vt: VtLike;
  try {
    vt = scoped
      ? (root as unknown as Required<VtStarter>).startViewTransition(onUpdate)
      : (document as unknown as Required<VtStarter>).startViewTransition(onUpdate);
  } catch {
    finish(rec);
    if (rec.updateRan) return rec.error ? Promise.reject(rec.error.value) : Promise.resolve();
    rec.updateRan = true;
    return immediate();
  }
  rec.vt = vt;

  const skip = () => {
    try {
      vt.skipTransition();
    } catch {
      /* already finished */
    }
  };
  // Reduced motion turning on mid-transition: skip now (the CSS also stops it).
  if (typeof window.matchMedia === 'function') {
    const mq = window.matchMedia(REDUCED_MOTION_QUERY);
    const onChange = () => {
      if (mq.matches) skip();
    };
    mq.addEventListener?.('change', onChange);
    listeners.push(() => mq.removeEventListener?.('change', onChange));
  }

  return new Promise<void>((resolve, reject) => {
    let settled = false;
    const settle = () => {
      if (settled) return;
      settled = true;
      finish(rec);
      if (rec.error) reject(rec.error.value);
      else resolve();
    };
    vt.updateCallbackDone.catch(() => {});
    vt.ready.then(
      () => {
        if (settled || scoped) return;
        // Document snapshots stay where they were captured: a scroll, resize or pointer drag
        // would detach them from the content, so the edit lands at once (the DOM is updated).
        const sx = window.scrollX;
        const sy = window.scrollY;
        const onScroll = (e: Event) => {
          const t = e.target;
          if (t === document || t === window || t === document.documentElement) {
            if (window.scrollX !== sx || window.scrollY !== sy) skip();
          } else skip();
        };
        const opts = { capture: true, passive: true } as const;
        window.addEventListener('scroll', onScroll, opts);
        window.addEventListener('resize', skip);
        window.addEventListener('pointerdown', skip, opts);
        listeners.push(() => {
          window.removeEventListener('scroll', onScroll, opts);
          window.removeEventListener('resize', skip);
          window.removeEventListener('pointerdown', skip, opts);
        });
      },
      () => {
        /* skipped (superseded, duplicate name, hidden document): not an error */
      },
    );
    vt.finished.then(settle, settle);
  });
}

/**
 * Returns `cutMorph(update, { kind })`. Resolution is from THIS component's tempo context
 * (`useResolvedMotion('stepped')`), so a nested `TempoProvider value="still"` stays still:
 *
 * | Request | Effective mode                                       | Result                             |
 * |---------|------------------------------------------------------|------------------------------------|
 * | `cut`   | any                                                  | `update()` now, no View Transition |
 * | `match` | `cut` (reduced motion, still, still ancestor)        | `update()` now                     |
 * | `match` | no API / no `view-transition-class` / SSR / hidden   | `update()` now                     |
 * | `match` | a transition CutMorph does not own is active         | `update()` now, never cancels it   |
 * | `match` | `stepped`                                            | View Transition, 3 poses on twos   |
 * | `match` | `smooth`                                             | View Transition, 260ms smooth      |
 *
 * Never wrap pointer drag, typing, focus movement, playback or continuous scrubbing.
 */
export function useCutMorph(opts?: UseCutMorphOptions): CutMorph {
  const mode = useResolvedMotion('stepped');
  const modeRef = React.useRef(mode);
  const scopeRef = React.useRef(opts?.scope);
  const [hook] = React.useState(() => ({}));
  useIsoLayoutEffect(() => {
    modeRef.current = mode;
    scopeRef.current = opts?.scope;
    // Tempo became still (or reduced motion turned on) here: this component's edits land now.
    if (mode === 'cut') {
      const owner = getOwner();
      skipOwned(owner, (rec) => rec.hook !== hook);
    }
  });
  return React.useCallback<CutMorph>(
    (update, callOpts) =>
      run(
        update,
        callOpts?.kind ?? 'match',
        modeRef.current,
        scopeRef.current?.current ?? null,
        hook,
      ),
    [hook],
  );
}

/**
 * For React 19.3 `<ViewTransition default="f12-match">` users: sets the CutMorph mode key on
 * `<html>` around `fn` (which calls `startTransition`) and removes it when the transition React
 * starts has finished (or after ~1s if none starts). Pass the mode from `useResolvedMotion`; when
 * it resolves to `cut`, update outside a Transition instead.
 */
export function withCutMorphMode<T>(mode: 'stepped' | 'smooth', fn: () => T): T {
  if (typeof document === 'undefined' || !MODE_CLASS[mode]) return fn();
  const owner = getOwner();
  const gen = ++owner.gen;
  const root = document.documentElement;
  const before = (document as unknown as { activeViewTransition?: VtLike | null })
    .activeViewTransition;
  setModeClass(root, MODE_CLASS[mode], gen);
  let result: T;
  try {
    result = fn();
  } catch (e) {
    clearModeClass(root, gen);
    throw e;
  }
  let frames = 0;
  const raf =
    typeof requestAnimationFrame === 'function'
      ? requestAnimationFrame
      : (cb: () => void) => setTimeout(cb, 16);
  const tick = () => {
    if (owner.classes.get(root)?.gen !== gen) return;
    const vt = (document as unknown as { activeViewTransition?: VtLike | null })
      .activeViewTransition;
    if (vt && vt !== before) {
      const done = () => clearModeClass(root, gen);
      vt.finished.then(done, done);
      return;
    }
    if (++frames > 60) {
      clearModeClass(root, gen);
      return;
    }
    raf(tick);
  };
  raf(tick);
  return result;
}

// ------------------------------------------------------------------------------------- names

const NAME_PATTERN = /^[a-z][a-z0-9-]{0,63}$/;
// Not valid view-transition names: the property's own keywords, the root's UA name, the
// CSS-wide keywords and `default` (reserved for every <custom-ident>).
const RESERVED_NAMES = new Set([
  'none',
  'auto',
  'match-element',
  'root',
  'initial',
  'inherit',
  'unset',
  'revert',
  'revert-layer',
  'default',
]);

/** True for a name `CutMorphName` accepts. */
export function isCutMorphName(name: unknown): name is string {
  return typeof name === 'string' && NAME_PATTERN.test(name) && !RESERVED_NAMES.has(name);
}

function classList(value: string): string | null {
  const parts = value.trim().split(/\s+/);
  for (const p of parts) {
    if (!/^-?[a-z_][a-z0-9_-]*$/i.test(p) || p === 'none' || RESERVED_NAMES.has(p)) return null;
  }
  return parts.join(' ');
}

function captureStack(): string {
  const r = React as unknown as { captureOwnerStack?: () => string | null };
  try {
    const owner = typeof r.captureOwnerStack === 'function' ? r.captureOwnerStack() : null;
    if (owner) return owner;
  } catch {
    /* not available in this build */
  }
  return (new Error('CutMorphName').stack || '').split('\n').slice(2, 8).join('\n');
}

/**
 * Names one subject for match cuts: sets `view-transition-name` (and `view-transition-class`,
 * `f12-match` by default) on its single DOM host child, merging the child's own `style`,
 * `className`, `ref` and handlers. The name is removed on unmount. Invalid names and children
 * that cannot carry a style (Fragment, text, arrays) are a development error and render
 * unchanged in production.
 */
export function CutMorphName({
  name,
  className = 'f12-match',
  children,
}: CutMorphNameProps): React.ReactElement {
  const isHost =
    React.isValidElement(children) && (children as React.ReactElement).type !== React.Fragment;
  const validName = isCutMorphName(name);
  const vtClass = typeof className === 'string' ? classList(className) : null;
  const usable = isHost && validName && vtClass !== null;

  const stackRef = React.useRef('');
  if (process.env.NODE_ENV !== 'production' && !stackRef.current) stackRef.current = captureStack();
  const registered = usable ? name : null;
  React.useEffect(() => {
    if (process.env.NODE_ENV === 'production' || !registered) return;
    const owner = getOwner();
    const list = owner.names.get(registered) ?? [];
    const entry = { stack: stackRef.current };
    if (list.length > 0) {
      console.warn(
        `[frame12] CutMorphName: "${registered}" is already on screen. view-transition-name must be unique among live elements; with a duplicate the browser skips the transition (the update still lands). Use a stable data id.\n--- first owner ---\n${list[0].stack}\n--- second owner ---\n${entry.stack}`,
      );
    }
    list.push(entry);
    owner.names.set(registered, list);
    return () => {
      const cur = owner.names.get(registered);
      if (!cur) return;
      const i = cur.indexOf(entry);
      if (i >= 0) cur.splice(i, 1);
      if (cur.length === 0) owner.names.delete(registered);
    };
  }, [registered]);

  if (!usable) {
    if (process.env.NODE_ENV !== 'production') {
      if (!isHost) {
        console.error(
          '[frame12] CutMorphName needs one DOM host element child (or a component that forwards `style` and `ref`), not a Fragment, text or an array.',
        );
      } else if (!validName) {
        console.error(
          `[frame12] CutMorphName: invalid name ${JSON.stringify(name)}. Use ^[a-z][a-z0-9-]{0,63}$ from a stable data id; none, auto, match-element, root, default and the CSS-wide keywords are reserved.`,
        );
      } else {
        console.error(
          `[frame12] CutMorphName: invalid className ${JSON.stringify(className)} (a view-transition-class list).`,
        );
      }
    }
    return isHost ? (children as React.ReactElement) : <>{children}</>;
  }
  const child = children as React.ReactElement<{ style?: React.CSSProperties }>;
  const style = {
    ...(child.props.style || {}),
    viewTransitionName: name,
    viewTransitionClass: vtClass,
  } as React.CSSProperties;
  return React.cloneElement(child, { style });
}
